NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Jeremiah'

CHAPTERS = {
    1: {
        1: 'Die Worte Jirmejahus, des Sohnes Chilkijahus von den Priestern in Anathoth im Lande Benjamin,',
        2: 'An den das Wort Jehovahs geschah, in den Tagen Joschijahus, des Sohnes Amons, König von Judah, im dreizehnten Jahr seiner Regierung;',
        3: 'Und es geschah in den Tagen Jehojakims, des Sohnes Joschijahus, König von Judah, bis an das Ende des elften Jahres, Zidkijahus, des Sohnes Joschijahus, König von Judah, bis zur Wegführung Jerusalems im fünften Monat.',
        4: 'Und Jehovahs Wort geschah an mich und sprach:',
        5: 'Ehe Ich dich im Mutterleib gebildet hatte, kannte Ich dich, und ehe aus dem Mutterschoß du ausgingst, heiligte Ich dich zum Propheten, für die Völkerschaften gab Ich dich.',
        6: 'Und ich sprach: Ach, Herr Jehovah! Siehe, ich weiß nicht zu reden: denn ein Junge bin ich.',
        7: 'Und es sprach Jehovah zu mir: Sprich nicht: Ich bin ein Junge, sondern gehe, überall, wohin Ich dich sende, und alles, was Ich dir gebiete, das rede.',
        8: 'Fürchte dich nicht vor ihnen, denn Ich bin mit dir, dich zu erretten, spricht Jehovah!',
        9: 'Und Jehovah reckte Seine Hand aus und berührte meinen Mund, und Jehovah sprach zu mir: Siehe, Meine Worte gebe Ich in deinen Mund.',
        10: 'Siehe zu, an diesem Tage habe Ich dich bestellt über die Völkerschaften und über die Königreiche, auszuroden, niederzureißen, zu zerstören und einzureißen, zu bauen und zu pflanzen.',
        11: 'Und es geschah Jehovahs Wort an mich, sprechend: Was siehst du, Jirmejahu? Und ich sprach: Ich sehe einen Stock vom Mandelbaum.',
        12: 'Und Jehovah sprach zu mir: Du hast wohl gesehen. Denn Ich will wachen über Mein Wort, daß Ich es tue.',
        13: 'Und es geschah zum zweitenmal Jehovahs Wort an mich sprechend: Was siehst du? Und ich sprach: Ich sehe einen Topf, der überwallt und seine Vorderseite ist Mitternacht.',
        14: 'Und Jehovah sprach zu mir: Von Mitternacht tut sich auf das Böse über alle Bewohner des Landes.',
        15: 'Denn siehe, Ich rufe allen Familien der Königreiche gegen Mitternacht, spricht Jehovah, daß sie kommen und setzen jeder Mann seinen Thron an den Eingang der Tore Jerusalems und an alle ihre Mauern ringsumher und an alle Städte Judahs.',
        16: 'Und will Meine Gerichte reden mit ihnen über all ihr Böses, daß sie Mich verlassen und anderen Göttern geräuchert und Werke ihrer Hände angebetet haben.',
        17: 'Du aber umgürte deine Lenden und stehe auf und rede zu ihnen alles, was Ich dir gebiete, erschrick vor ihnen nicht, daß Ich dich nicht vor ihnen erschrecke.',
        18: 'Denn siehe, Ich gebe dich heute zur festen Stadt und zur eisernen Säule und zur ehernen Mauer wider das ganze Land, wider die Könige Jehudah, wider dessen Obersten, wider dessen Priester und wider das Volk des Landes.',
        19: 'Und streiten werden sie wider dich und dich nicht übermögen: denn Ich bin mit dir, spricht Jehovah, daß Ich dich errette.',
    },
    2: {
        1: 'Und es geschah an mich Jehovahs Wort sprechend:',
        2: 'Gehe hin und rufe vor den Ohren Jerusalems und sprich: So spricht Jehovah: Ich habe dir gedacht der Barmherzigkeit deiner Jugend, der Liebe deiner Bräutlichkeit, da du gingst Mir nach in der Wüste, in einem Land, das nicht besät wird.',
        3: 'Dem Jehovah heilig war Israel, der Erstling des Ertrages. Jeder, der sie auffressen wollte, verschuldete sich; Böses kam über sie, spricht Jehovah.',
        4: 'Höret das Wort Jehovahs, ihr vom Hause Jakobs und alle ihr Familien vom Hause Israels.',
        5: 'So spricht Jehovah: Was haben eure Väter Verkehrtes an Mir gefunden, daß sie sich von Mir entfernten und der Nichtigkeit nachgingen und nichtig wurden?',
        6: 'Und sie sagten nicht: Wo ist Jehovah, Der uns aus dem Land Ägypten hat heraufgebracht, Der uns in der Wüste gehen ließ, in dem Land der Einöde und der Fallgruben, im Land der Dürre und des Todesschattens, im Land, da kein Mann hindurchgeht, und kein Mensch darin wohnt?',
        7: 'Und Ich brachte euch in ein Land der Fruchtgefilde, damit ihr äßet seine Frucht und sein Gut; ihr aber kamt und verunreinigtet Mein Land und machtet Mein Erbe zum Greuel.',
        8: 'Die Priester sagen nicht: Wo ist Jehovah? Und die das Gesetz handhaben, kennen Mich nicht, und die Hirten sind von Mir abgefallen, und die Propheten weissagen durch Baal, und gehen denen nach, die nichts nützen.',
        9: 'Darum muß Ich noch mit euch hadern, spricht Jehovah, und mit den Söhnen eurer Söhne muß Ich hadern.',
        10: 'Denn geht hinüber nach den Inseln der Kittäer und sehet, und sendet nach Kedar und merket sehr darauf, und sehet, ob dergleichen geschieht.',
        11: 'Hat je eine Völkerschaft die Götter vertauscht, obschon sie keine Götter sind? Aber Mein Volk hat seine Herrlichkeit vertauscht mit etwas, das kein nütze ist.',
        12: 'Erstaunt darob, ihr Himmel und schaudert, werdet sehr öde, spricht Jehovah.',
        13: 'Denn zweifach Böses hat Mein Volk getan: sie haben Mich verlassen, den Born lebendiger Wasser, um sich Gruben auszuhauen, zerbrochene Gruben, die kein Wasser fassen.',
        14: 'Ist Israel ein Knecht, ist er ein Kind des Hauses? Warum ist er zum Raub geworden?',
        15: 'Wider ihn brüllen die jungen Löwen, sie geben ihre Stimme hervor und machen sein Land zur Verwüstung, seine Städte werden angezündet, ohne Bewohner.',
        16: 'Auch die Söhne von Noph und Thachpanches weiden ab dir den Scheitel.',
        17: 'Hast du nicht selbst dir dies damit getan, daß du Jehovah, deinen Gott, verließest zur Zeit, da Er dich auf dem Wege gehen ließ?',
        18: 'Und nun, was hast du mit dem Weg Ägyptens, daß du Schichors Wasser trinkst, und was hast du mit dem Wege Aschurs, daß du des Flusses Wasser trinkst?',
        19: 'Züchtigen wird dich deine Bosheit und dein Zurückwenden dich rügen, und wisse und siehe, daß es böse und bitter ist, daß du Jehovah, deinen Gott, verließest, und keine Scheu vor Mir in dir ist, spricht der Herr Jehovah der Heerscharen.',
        20: 'Denn du hast von Ewigkeit her dein Joch zerbrochen, abgerissen deine Bande und gesagt: Ich will nicht dienen; aber auf jedem hohen Hügel und unter jedem grünen Baum hast du als Buhlerin dich gelagert.',
        21: 'Und Ich hatte dich gepflanzt ganz als Edelrebe, einen Samen der Wahrheit, und wie hast du dich Mir in einen ausgearteten ausländischen Weinstock verwandelt!',
        22: 'Ja, wüschest du mit Lauge dich und mehrtest dir die Seife, ist deine Missetat doch vor Mir besudelt, spricht der Herr Jehovah.',
        23: 'Wie sagst du: Ich bin nicht verunreinigt, gehe den Baalen nicht nach? Siehe deinen Weg in der Schlucht und erkenne, was du getan! Ein schnelles Dromedar bist du, das seine Wege kreuzt;',
        24: 'Eine Waldeselin, der Wüste gewohnt, schnappt sie in ihrer Seele Gelüste nach dem Winde; wer hält ihre Brunst zurück? Alle, so sie suchen, werden nicht matt, in ihrem Monat finden sie sie.',
        25: 'Halt ab deinen Fuß von der Blöße, und deine Kehle von dem Durst! Du sprichst aber: Es ist verzweifelt! Nein! denn Fremde liebe ich und gehe ihnen nach.',
        26: 'Wie die Scham des Diebes, wenn er ausgefunden wird, so werden beschämt die vom Hause Israel, sie, ihre Könige, ihre Obersten und ihre Priester und ihre Propheten.',
        27: 'Zum Holze sagten sie: Du bist mein Vater, und zum Steine: Du hast mich gezeugt! Mir aber wandten sie den Rücken zu, und nicht das Angesicht. Aber zur Zeit ihres Übels sprechen sie: Stehe auf und rette uns!',
        28: 'Und wo sind deine Götter, die du dir gemacht? Laß sie aufstehen, ob sie zur Zeit deines Übels dich retten können? Denn wie die Zahl deiner Städte, so waren deine Götter, Judah!',
        29: 'Warum wollt ihr mit Mir hadern? Ihr alle seid von Mir abgefallen, spricht Jehovah.',
        30: 'Vergeblich schlug Ich eure Söhne; sie nahmen keine Zucht an. Euer Schwert fraß eure Propheten, wie der Löwe, der verdirbt.',
        31: 'O Geschlecht, ihr sehet das Wort Jehovahs! War eine Wüste Ich für Israel, ein Land des Dunkels? Warum spricht denn Mein Volk: Wir herrschen, wir kommen nicht mehr zu Dir?',
        32: 'Vergißt denn die Jungfrau ihres Schmukkes, die Braut ihres Bandes? Aber Mein Volk hat Tage ohne Zahl Mein vergessen.',
        33: 'Was willst du deinen Weg gut machen, Liebe zu suchen? Darum hast du auch die Bosheiten deine Wege gelehrt.',
        34: 'Auch ist an deinen Fittichen gefunden worden das Blut der Seelen der Dürftigen, der Unschuldigen; nicht beim Einbruch fand Ich sie, sondern allüberall.',
        35: 'Und du sprichst: Ich bin unschuldig, ja, Sein Zorn hat von mir sich zurückgewendet. Siehe, wir wollen rechten mit dir ob deiner Rede: Ich habe nicht gesündigt!',
        36: 'Was rennst du, so deinen Weg zu verändern? Auch Ägyptens wirst du dich schämen, wie du dich Aschurs schämtest.',
        37: 'Von da auch wirst du ausgehen, und deine Hände auf deinem Haupte; denn Jehovah hat das verschmäht, worauf du vertraut hast, so daß dir mit ihnen nichts gelingen wird.',
    },
    3: {
        1: 'Er spricht: Siehe, wenn ein Mann sein Weib entläßt und sie geht von ihm fort und wird eines anderen Mannes, wird er noch zu ihr zurückkehren? Ist nicht ein solches Land ganz und gar entheiligt, und du hast gebuhlt mit vielen Genossen. Aber kehre zurück zu Mir! spricht Jehovah.',
        2: 'Erhebe deine Augen zu den Anhöhen und siehe wo du nicht bist geschändet worden? An den Wegen saßest du für sie, wie der Araber in der Wüste, und entheiligtest das Land durch deine Buhlereien und durch deine Bosheit.',
        3: 'Da wurden die Regengüsse vorenthalten und es ward kein Spätregen; du aber hast die Stirn eines Buhlweibes, du weigerst dich, Schande zu fühlen.',
        4: 'Riefst du nicht eben noch zu Mir: Mein Vater, der Leiter meiner Jugend warst Du?',
        5: 'Wird Er es ewiglich nachtragen, immerdar es behalten? Siehe, du redetest und tatest das Böse und vermochtest es.',
        6: 'Und Jehovah sprach zu mir in den Tagen des Königs Joschijahu: Hast du gesehen, was das abwendige Israel hat getan, wie es hinging auf jeden hohen Berg und unter jeden grünen Baum und allda buhlte?',
        7: 'Und Ich sprach, nachdem sie alles dies getan: Kehre zurück zu Mir. Sie kehrte aber nicht zurück, und seine treulose Schwester Judah sah es.',
        8: 'Und Ich sah, daß nach all der Weise, in der das abwendige Israel Ehebruch begangen, Ich sie entließ und ihr einen Scheidebrief gab, so fürchtete das treulose Jehudah, ihre Schwester, sich doch nicht, und ging und buhlte auch sie.',
        9: 'Und von der Stimme ihrer Buhlerei ward entheiligt das Land und sie trieb Ehebruch mit Stein und Holz.',
        10: 'Und auch bei all dem kehrt ihre treulose Schwester Judah nicht zurück zu Mir von ganzem Herzen, sondern mit Lüge, spricht Jehovah.',
        11: 'Und Jehovah sprach zu mir: Das abwendige Israel rechtfertigt ihre Seele gegen das treulose Jehudah.',
        12: 'Gehe und rufe aus gegen Mitternacht diese Worte und sprich: Kehre zurück abwendiges Israel, spricht Jehovah: Ich will Mein Angesicht nicht fallen lassen wider euch, denn Ich bin barmherzig, spricht Jehovah, Ich will nicht ewig nachtragen.',
        13: 'Allein erkenne deine Missetat, daß du von Jehovah, deinem Gotte, abgefallen bist, und deine Wege verteiltest den Fremden unter jedem grünen Baum, und daß ihr nicht auf Meine Stimme hörtet, spricht Jehovah.',
        14: 'Kehret zurück, ihr abwendigen Söhne, spricht Jehovah, denn Ich habe euch Mir vermählt und will euch nehmen, einen aus einer Stadt und zwei aus einer Familie, und euch gen Zion bringen.',
        15: 'Und will euch Hirten geben nach Meinem Herzen, daß sie euch weiden mit Erkenntnis und Verstand.',
        16: 'Und wird geschehen, wenn ihr euch mehret und fruchtbar werdet in dem Land in jenen Tagen, spricht Jehovah, daß man nicht mehr spricht von der Lade des Bundes Jehovahs, noch wird sie einem in das Herz kommen, noch wird man ihrer gedenken oder sie vermissen und wird nicht mehr gemacht werden.',
        17: 'Zur selben Zeit wird man Jerusalem den Thron Jehovahs nennen, und werden sich allda ansammeln alle Völkerschaften zum Namen Jehovahs nach Jerusalem und nicht mehr wandeln nach dem Eigensinn ihres bösen Herzens.',
        18: 'In jenen Tagen geht das Haus Jehudahs zu dem Hause Israel, und sie kommen allzumal aus dem Lande der Mitternacht in das Land, das Ich eure Väter erben ließ.',
        19: 'Und Ich sprach: Wie will Ich dich unter die Söhne stellen und dir ein begehrenswertes Land, ein Erbe, die Zierde der Zierden der Völkerschaften geben?! Und Ich sprach: Ihr würdet Mich Vater nennen, und nicht hinter Mir zurückweichen.',
        20: 'Doch wie ein Weib treulos wird ihrem Genossen, seid ihr, Haus Israels, Mir treulos worden, spricht Jehovah.',
        21: 'Auf den Anhöhen hat man eine Stimme gehört, Weinen, Flehen der Söhne Israels, daß sie ihren Weg krumm gemacht, daß sie Jehovah, ihren Gott, vergessen hatten.',
        22: 'Kehret zurück, ihr abwendigen Söhne; Ich will heilen eure Abwendung. Siehe uns, wir kommen zu Dir, denn Du bist Jehovah, unser Gott.',
        23: 'Fürwahr, zur Lüge ist es mit den Hügeln, der Menge der Berge; fürwahr in Jehovah, unserem Gott, ist Israels Heil.',
        24: 'Und die Beschämung hat von unserer Jugend an die Arbeit unserer Väter, ihr Kleinvieh und ihre Rinder, und ihre Söhne und Töchter aufgefressen.',
        25: 'Wir liegen da in unserer Scham, und unsere Schande bedeckt uns; denn wider Jehovah, unseren Gott, haben gesündigt wir und unsere Väter von unserer Jugend auf, und bis auf diesen Tag, und auf die Stimme Jehovahs, unseres Gottes, nicht gehört.',
    },
    4: {
        1: 'Wenn du zurückkehrst, Israel, spricht Jehovah, zu Mir zurückkehrst und deine Scheusale wegtust vor Meinem Angesicht, und nicht schwankst;',
        2: 'Und schwörst bei Jehovahs Leben in Wahrheit, in Recht und in Gerechtigkeit: so werden in Ihm die Völkerschaften gesegnet werden und in Ihm sich rühmen.',
        3: 'Denn so spricht Jehovah zu dem Mann von Judah und zu Jerusalem: Brecht einen Neubruch euch und sät nicht unter Dornen.',
        4: 'Beschneidet euch dem Jehovah und tut weg die Vorhaut eures Herzens, o Mann Jehudahs und Bewohner von Jerusalem, daß nicht wie Feuer ausgehe Mein Grimm und brenne und niemand da sei, der lösche, ob der Bosheit eures Tuns.',
        5: 'Sagt es an in Jehudah und in Jerusalem laßt es hören, und sprechet und blaset die Posaune im Land, macht es voll und sprecht: Sammelt euch und laßt uns in die festen Städte gehen.',
        6: 'Erhebt das Panier Zijon zu, flüchtet euch zusammen und bleibt nicht stehen, denn Böses laß Ich kommen von Mittenacht und ein großes Zerbrechen.',
        7: 'Ein Löwe kommt herauf aus seinem Dickicht und wird Völkerschaften verderben, er ist aufgebrochen, aus seinem Orte ausgezogen, dein Land zur Wüstenei zu machen, daß deine Städte zertrümmert werden, niemand darin wohne.',
        8: 'Darum gürtet euch mit Säcken, klaget und heulet; denn die Entbrennung von Jehovahs Zorn kehrt nicht von uns zurück.',
        9: 'Und an jenem Tage wird geschehen, spricht Jehovah, daß das Herz des Königs und das Herz der Obersten vergeht, daß die Priester erstaunen und die Propheten sich verwundern.',
        10: 'Und ich sprach: Ach, Herr Jehovah, fürwahr hast Du dies Volk und Jerusalem verführen und ihm sagen lassen: Ihr werdet Frieden haben, und es reicht bis an die Seele das Schwert.',
        11: 'Zur selben Zeit wird man diesem Volk und Jerusalem sagen: Ein sengender Wind der Anhöhen in der Wüste ist der Weg der Tochter Meines Volkes, nicht um zu worfeln und zu säubern.',
        12: 'Ein voller Wind kommt Mir von ihnen. Nun will Ich auch mit diesen von Gerichten reden.',
        13: 'Siehe, wie Wolken zieht es herauf und wie der Sturmwind sind seine Streitwagen, schneller denn Adler seine Rosse! Wehe uns! wir sind verheert!',
        14: 'Wasche dein Herz vom Bösen, Jerusalem, daß du gerettet werdest! Wie lange willst du in deinem Inneren herbergen deines Unrechts Gedanken!',
        15: 'Denn eine Stimme, die es ansagt, kommt von Dan, er, der Unrechtes hören läßt, von Ephraims Gebirge.',
        16: 'Meldet es den Völkerschaften! Siehe! Laßt es hören über Jerusalem! Wächter kommen aus fernem Land und geben ihre Stimme wider Jehudahs Städte hervor.',
        17: 'Wie Hüter des Feldes sind sie wider sie rings umher, weil sie widerspenstig geworden ist, spricht Jehovah.',
        18: 'Dein Weg und dein Tun haben dir es getan. Das ist deine Bosheit, daß dir es bitter ist, daß dir es an das Herz reicht.',
        19: 'Mein Eingeweide! Mein Eingeweide! Es kreißen die Wände meines Herzens. Mein Herz tobt auf, ich kann nicht stille schweigen; denn der Posaune Stimme hört meine Seele, des Streites Feldgeschrei.',
        20: 'Bruch auf Bruch begegnet man. Denn verheert ist das ganze Land, plötzlich verheert sind meine Zelte, in einem Augenblick meine Teppiche.',
        21: 'Wie lange soll Ich sehen das Panier, hören der Posaune Stimme?',
        22: 'Denn Mein Volk ist dumm, Mich kennt es nicht. Närrische Söhne sind sie, und ohne Einsicht sind sie, weise sind sie zum Böses tun, aber Gutes zu tun, wissen sie nicht.',
        23: 'Ich sah die Erde, und siehe! eine Leere und Öde, und auf zu den Himmeln, und ihr Licht war nicht da.',
        24: 'Ich sah die Berge und siehe! sie bebten, und alle Hügel wankten.',
        25: 'Ich sah, und siehe! da war kein Mensch, und alles Gevögel der Himmel war entflohen.',
        26: 'Ich sah, und siehe! der Karmel war eine Wüste, und alle seine Städte waren eingerissen vor Jehovah, vor der Entbrennung Seines Zorns.',
        27: 'Denn so spricht Jehovah: Verwüstet soll sein das ganze Land, doch will Ich nicht eine Vollendung machen.',
        28: 'Darüber soll das Land trauern und die Himmel droben sich verdunkeln, weil, was Ich geredet habe, habe Ich beschlossen, und nicht gereut es Mich, noch wende Ich Mich davon zurück.',
        29: 'Vor der Stimme des Reiters und des Bogenschützen entweicht die ganze Stadt; sie gehen hinein in die dichten Wolken und zu den Felskuppen steigen sie auf. Verlassen ist die ganze Stadt und kein Mann wohnt darinnen.',
        30: 'Und du, Verheerte, was tust du? Ziehst du Scharlach an, schmückst dich mit Goldschmuck, schminkst mit Bleiglanz deine Augen, - umsonst machst du dich schön - es verschmähen dich deine Liebhaber, sie trachten dir nach der Seele.',
        31: 'Ich höre die Stimme wie einer Kreißenden, Bedrängnis wie einer, die zum erstenmal gebiert, die Stimme der Tochter Zijons, die schluchzt, die ihre Hände ausbreitet. O weh, mir doch; denn meine Seele ermattet vor den Mordenden!',
    },
    5: {
        1: 'Streifet umher in den Gassen von Jerusalem, und seht doch und erkennt und sucht in seinen Straßen, ob einen Mann ihr findet, ob einer da ist, der Recht tut, der Wahrheit sucht: so will Ich ihr vergeben.',
        2: 'Und ob sie sprechen: Beim Leben Jehovahs! schwören sie dennoch zur Lüge.',
        3: 'Jehovah, sind Deine Augen nicht auf dem Wahren? Du schlugst sie und es erschütterte sie nicht; Du riebst sie auf, sie weigerten sich, Zucht anzunehmen, machen fester denn die Felsenklippe ihr Angesicht, weigern sich, umzukehren.',
        4: 'Und ich sprach: Es sind nur die Armen, die dumm sind, weil sie den Weg Jehovahs, ihres Gottes Recht, nicht kennen.',
        5: 'Ich will doch zu den Großen gehen und will mit ihnen reden, denn sie kennen den Weg Jehovahs, ihres Gottes Recht. Aber sie hatten allzumal das Joch gebrochen, die Bande abgerissen.',
        6: 'Darum schlägt sie der Löwe aus dem Wald, es verheert sie der Wolf der Einöden, der Pardel lauert wider ihre Städte. Jeder, der aus denselben herausgeht, wird zerfleischt, denn viel ist ihrer Übertretungen, mächtig ist ihre Abwendung geworden.',
        7: 'Ob dem sollte Ich vergeben dir? Deine Söhne verließen Mich und schwuren bei einem, der nicht Gott ist: und als Ich sie sättigte, trieben sie Ehebruch und scharten sich zusammen in der Buhlerin Haus.',
        8: 'Wie geile Rosse sind sie früh auf und wiehern, ein jeder Mann nach des Genossen Weib.',
        9: 'Sollte Ich deshalb nicht heimsuchen? spricht Jehovah. - Oder soll an einer Völkerschaft wie diese Meine Seele nicht Rache nehmen?',
        10: 'Steigt auf ihre Mauern und verderbt sie; aber macht keine Vollendung. Tut weg ihre Ranken, denn sie sind nicht Jehovahs.',
        11: 'Denn treulos haben an Mir gehandelt das Haus Israel und das Haus Judah, spricht Jehovah.',
        12: 'Verleugnet haben sie Jehovah und gesagt: Er ist nicht, und es wird nichts Böses kommen über uns. Und Schwert und Hunger werden wir nicht sehen.',
        13: 'Und die Propheten werden zu Wind werden und das Wort ist nicht in ihnen. So wird es ihnen geschehen.',
        14: 'Darum spricht also Jehovah, der Gott der Heerscharen: Weil ihr redet solches Wort, siehe, so will Ich Meine Worte in deinen Mund geben zum Feuer, und dieses Volk zu Holz, daß es sie auffresse.',
        15: 'Siehe, aus der Ferne bringe Ich über euch eine Völkerschaft, Haus Israel, spricht Jehovah: Eine mächtige Völkerschaft ist es, eine uralte Völkerschaft, eine Völkerschaft, deren Zunge du nicht kennst und nicht verstehst, was es redet.',
        16: 'Sein Köcher ist wie ein geöffnetes Grab, sie alle sind Helden.',
        17: 'Und es wird auffressen deine Ernte und dein Brot; sie werden auffressen deine Söhne und deine Töchter; auffressen dein Kleinvieh und dein Rind; auffressen deinen Weinstock und deinen Feigenbaum; es wird deine festen Städte, auf die du vertraut, arm machen mit dem Schwert.',
        18: 'Aber auch in jenen Tagen, spricht Jehovah, will Ich mit euch keine Vollendung machen.',
        19: 'Und soll geschehen, wenn ihr sagt, warum hat uns Jehovah, unser Gott, solches alles getan, daß du ihnen sagst: Wie ihr Mich habt verlassen und Göttern des Auslandes in eurem Lande gedient, so sollt ihr Fremden dienen in einem Lande, das nicht euer ist.',
        20: 'Sagt solches an im Hause Jakobs und laßt hören in Jehudah und sprechet:',
        21: 'Höret doch dies, närrisches Volk, ohne Herz; die Augen haben und sehen nicht, Ohren haben und hören nicht!',
        22: 'Mich wollt ihr nicht fürchten, spricht Jehovah, vor Mir nicht erschüttert sein, Der Ich den Sand dem Meere zur Grenze setze, zur ewigen Satzung, und es überschreitet sie nicht; und es wogt einher und vermag nichts; die Wogen toben und überschreiten es nicht.',
        23: 'Aber dies Volk hat ein störrisch und widerspenstig Herz. Sie sind abgewichen und sind dahingegangen,',
        24: 'Und sagten nicht in ihrem Herzen: Lasset uns doch Jehovah fürchten, unseren Gott, Der den Platzregen uns, den Frühregen und Spätregen gibt zu seiner Zeit, Der die Wochen, die Satzungen der Ernte, für uns behütet.',
        25: 'Eure Missetaten wendeten dies ab, und eure Sünden hielten ab von euch das Gute.',
        26: 'Denn Ungerechte finden sich in Meinem Volk, sie schauen zu, wie Vogelsteller sich duckend die Fallen stellen, sie fangen Männer.',
        27: 'Wie ein Vogelbauer voll vom Gevögel ist, sind vom Betruge ihre Häuser voll. Daher werden sie groß und reich.',
        28: 'Sie werden fett, sie glitzern, auch fließen sie über mit Worten der Bosheit. Die Rechtssache rechten sie nicht, die Rechtssache der Waise, daß es ihnen gelänge, und das Recht der Dürftigen richten sie nicht.',
        29: 'Und solches sollte Ich nicht heimsuchen? spricht Jehovah, an einer Völkerschaft wie diese soll Meine Seele nicht Rache nehmen?',
        30: 'Erstaunliches und Schauerliches geschieht im Lande!',
        31: 'Lüge weissagen die Propheten und die Priester herrschen durch deren Hände, und Mein Volk liebt es so. Und was wollt ihr zuletzt dabei tun?',
    },
    6: {
        1: 'Flüchtet euch zusammen, Benjamins Söhne, aus Jerusalems Mitte. In Thekoa stoßet in die Posaune und auf dem Hause des Weinbergs erhebt das Feuerzeichen; denn Böses schaut hervor aus Mitternacht und großes Zerbrechen.',
        2: 'Einer Holden und Üppigen vergleiche Ich die Tochter Zijon.',
        3: 'Zu ihr kommen die Hirten und ihre Herden, sie schlagen ihre Zelte ringsum bei ihr auf; sie weiden, jeder Mann seine Stelle ab.',
        4: 'Heiligt wider sie den Streit; stehet auf und lasset uns gen Mittag hinaufziehen! Wehe uns, denn der Tag hat sich gewendet, und die Schatten des Abends strecken sich.',
        5: 'Stehet auf! und laßt uns in der Nacht hinaufziehen und ihre Paläste verderben.',
        6: 'Denn also spricht Jehovah der Heerscharen: Haut Bäume um und schüttet einen Wall auf wider Jerusalem; sie ist die Stadt, die heimgesucht wird. In ihrem Inneren ist alles Erpressung.',
        7: 'Wie der Brunnen läßt hervorquellen sein Wasser, so quillt hervor ihre Bosheit. Gewalttat und Verheerung hört man in ihr, vor Meinem Angesicht beständig Krankheit und Schlag.',
        8: 'Nimm Zucht an, Jerusalem, daß sich Meine Seele nicht von dir abneige, daß Ich dich nicht zur Verwüstung mache, zu einem Lande, das man nicht bewohnt.',
        9: 'So spricht Jehovah der Heerscharen: Eine Nachlese soll man nachlesen, wie am Weinstock, an dem Überrest Israels. Deine Hand soll sie in die Körbe bringen wie der Winzer!',
        10: 'Zu wem soll ich reden und zeugen, daß sie es hören? Siehe, ihr Ohr ist unbeschnitten, sie vermögen nicht zu horchen. Siehe, das Wort Jehovahs ist ihnen zur Schmach geworden. Sie haben keine Lust dazu.',
        11: 'Aber ich bin voll vom Grimme Jehovahs, bin ermüdet, davon ihn zurückzuhalten. Schütte ihn aus über das Kindlein auf der Gasse und über den Kreis der Jünglinge allzumal; denn auch der Mann mit dem Weib wird gefangen werden, der Alte mit dem, der voll ist von Tagen.',
        12: 'Und ihre Häuser gehen an andere über, Felder und Weiber allzumal, wenn Meine Hand Ich ausrecke über die, so im Lande wohnen, spricht Jehovah.',
        13: 'Denn von ihren Kleinen bis zu ihren Großen geizt alles nach Gewinn, und vom Propheten bis zum Priester tut alles Lüge;',
        14: 'Und heilen den Bruch der Tochter Meines Volkes leichthin und sagen: Friede, Friede, und ist kein Friede.',
        15: 'Schämen sie sich, daß sie Greuel tun? Sie schämen sich mit keiner Scham, auch wissen sie nichts von Schande; darum sollen sie fallen unter den Fallenden; zur Zeit, da Ich sie heimsuche, straucheln sie, spricht Jehovah.',
        16: 'So spricht Jehovah: Stehet bei den Wegen und sehet und fraget nach den Steigen der Ewigkeit, welches der gute Weg sei, und wandelt darin, und ihr werdet Rast finden für eure Seele. Sie aber sprechen: Wir wollen nicht darauf wandeln.',
        17: 'Und Ich habe Wächter über euch eingesetzt. Horchet auf die Stimme der Posaune. Sie aber sprachen: Wir wollen nicht horchen.',
        18: 'So hört denn, ihr Völkerschaften, und wisse, du Gemeinde, was in ihnen ist.',
        19: 'Höre, du Erde: Siehe, Ich bringe Böses über dieses Volk, die Frucht ihrer Gedanken, daß sie auf Meine Worte nicht horchen, und Mein Gesetz, das verschmähen sie.',
        20: 'Was soll Mir dies, daß Weihrauch aus Scheba kommt und der gute Kalmus aus fernem Lande? Eure Brandopfer sind nicht nach Meinem Wohlgefallen, und eure Schlachtopfer sind Mir nicht angenehm.',
        21: 'Darum spricht also Jehovah: Siehe, Ich gebe einen Anstoß diesem Volk, daß sich daran anstoßen Väter und Söhne allzumal, daß der Nachbar und sein Genosse vergehen.',
        22: 'So spricht Jehovah: Siehe, ein Volk kommt von dem Land der Mitternacht, und eine große Völkerschaft wird auferweckt von der Erde Seiten.',
        23: 'Bogen und Wurfspieß erfassen sie, sind grausam und haben kein Erbarmen; ihre Stimme tobt wie das Meer; und sie reiten auf Rossen, gerüstet wie ein Mann zum Streite wider dich, Tochter Zions.',
        24: 'Wir hören ihr Gerücht, unsere Hände erschlaffen. Bedrängnis erfaßt uns, ein Kreißen wie der Gebärerin.',
        25: 'Geht nicht hinaus auf das Feld und wandelt nicht auf dem Weg; denn des Feindes Schwert, Bangen ist ringsumher.',
        26: 'O Tochter meines Volkes, gürte dich mit dem Sacke, wälze dich umher in der Asche, mache dir Trauer wie um den Einzigen, eine Klage der Bitterkeit; denn plötzlich kommt der Verheerer über uns.',
        27: 'Zum Prüfer gebe Ich dich, zur Festung unter Mein Volk, daß ihren Weg du kennen und prüfen sollst.',
        28: 'Sie alle sind Abgefallene der Abgefallenen; sie gehen als Zwischenträger, Erz und Eisen sind sie, sie sind alle Verderber.',
        29: 'Es glüht der Blasebalg; verzehrt vom Feuer ist das Blei; umsonst läutert man, die Bösen lassen sich nicht abreißen.',
        30: 'Verschmähtes Silber nennt man sie; denn Jehovah hat sie verschmäht.',
    },
    7: {
        1: 'Das Wort, das von Jehovah an Jirmejahu geschah, sprechend:',
        2: 'Stehe in dem Tor des Hauses Jehovahs und rufe allda dies Wort und sprich: Höret das Wort Jehovahs ganz Jehudah, ihr, die ihr zu diesen Toren eingeht, Jehovah anzubeten.',
        3: 'So spricht Jehovah der Heerscharen, der Gott Israels: Macht eure Wege gut und euer Tun, so will Ich euch wohnen lassen an diesem Ort.',
        4: 'Vertraut euch nicht auf Worte der Lüge, sprechend: Der Tempel Jehovahs, der Tempel Jehovahs, der Tempel Jehovahs ist das.',
        5: 'Sondern macht eure Wege gut und euer Tun, daß ihr das Recht tuet zwischen dem Mann und seinem Genossen.',
        6: 'Gegen den Fremdling, die Waise und die Witwe übet nicht Erpressung, und vergießet nicht unschuldig Blut an diesem Ort, und geht nicht anderen Göttern nach, euch zum Übel.',
        7: 'Dann will Ich euch an diesem Ort, in dem Lande wohnen lassen, das Ich euren Vätern gegeben habe, von Ewigkeit zu Ewigkeit.',
        8: 'Siehe, ihr vertraut euch auf Worte der Lüge, die kein nütze sind.',
        9: 'Wollt ihr stehlen, morden und ehebrechen und zur Lüge schwören und dem Baal räuchern und anderen Göttern nachgehen, die ihr nicht kennt,',
        10: 'Und hereinkommen und stehen vor Mein Angesicht in diesem Hause, über dem Mein Name ist genannt, und sprechen: Wir sind errettet! während ihr alle diese Greuel tut?',
        11: 'Ist dies Haus, über dem Mein Name ist genannt, in euren Augen zur Höhle der Räuber geworden? Siehe, auch Ich habe es gesehen, spricht Jehovah.',
        12: 'Gehet doch hin an Meinen Ort in Schilo, wo Meinen Namen Ich hatte früher wohnen lassen, und sehet, was Ich mit ihm getan wegen der Bosheit Meines Volkes Israel.',
        13: 'Und nun, weil ihr alle diese Werke tut, spricht Jehovah, und Ich zu euch geredet, indem Ich früh aufstand und redete, und ihr nicht hörtet, und Ich euch rief und ihr nicht antwortet.',
        14: 'So will Ich dem Hause tun, über dem Mein Name genannt wird, worauf ihr vertrauet, und dem Orte, den Ich euch und euren Vätern gegeben habe, wie Ich Schilo getan habe.',
        15: 'Und werfe euch weg von Meinem Angesicht, wie Ich weggeworfen habe alle eure Brüder, allen Samen Ephraims.',
        16: 'Du aber bete nicht für dieses Volk, und erhebe nicht Klageruf, noch Gebet für sie, und dränge nicht in Mich, denn Ich höre nicht auf dich.',
        17: 'Siehst du nicht, was sie in den Städten Jehudahs tun und in den Gassen Jerusalems?',
        18: 'Die Söhne lesen Holz auf und die Väter zünden das Feuer an und die Weiber kneten Teig, Kuchen zu machen für die Königin des Himmels und zu gießen anderen Göttern Trankopfer, daß sie Mich reizen?',
        19: 'Reizen sie Mich, spricht Jehovah, nicht vielmehr sich selbst zur Beschämung ihres Angesichts?',
        20: 'Darum, so spricht der Herr Jehovah: Siehe Mein Zorn und Mein Grimm sind ergossen über diesen Ort, über Mensch und über Vieh, und über den Baum des Feldes, und über die Frucht des Bodens; und es brennt und erlöscht nicht.',
        21: 'So spricht Jehovah der Heerscharen, der Gott Israels: Tut eure Brandopfer hinzu zu euren Schlachtopfern und esset Fleisch.',
        22: 'Denn Ich habe nicht zu euren Vätern geredet, noch ihnen geboten am Tage, da Ich sie aus dem Lande Ägypten herausgebracht, über Worte des Brandopfers und des Schlachtopfers.',
        23: 'Sondern Ich gebot ihnen dies Wort und sprach: Höret auf Meine Stimme, so will Ich Gott euch sein, und ihr sollt Mir zum Volke sein, und wandeln auf jeglichem Wege, den Ich euch gebiete, daß es gut mit euch sei.',
        24: 'Aber sie hörten nicht und neigten nicht ihr Ohr, und wandeln nach den Ratschlägen, nach der Verstocktheit ihres bösen Herzens, und kehrten sich nach hinten, und nicht nach vorn.',
        25: 'Vom Tage, da eure Väter auszogen aus dem Lande Ägypten bis auf diesen Tag, da sandte Ich zu euch alle Meine Knechte, die Propheten, indem Ich täglich früh aufstand und sie sandte.',
        26: 'Sie aber hörten nicht auf Mich und neigten nicht ihr Ohr und verhärteten ihren Nacken, und machten es schlimmer als ihre Väter.',
        27: 'Und redest du zu ihnen alle diese Worte, so hören sie nicht auf dich, und rufst du ihnen, so antworten sie dir nicht;',
        28: 'Und du, sprich zu ihnen: Das ist die Völkerschaft, die nicht gehört hat auf die Stimme Jehovahs, ihres Gottes, und keine Zucht annahm. Vergangen ist die Wahrheit und aus ihrem Munde ausgerottet.',
        29: 'Scher ab dein Nasiräat und wirf es hin und erhebe auf den Abhängen ein Klagelied. Denn Jehovah hat verschmäht und hingegeben das Geschlecht Seines Wütens.',
        30: 'Denn die Söhne Jehudahs tun, was böse ist in Meinen Augen, spricht Jehovah, sie stellen ihre Scheusale in dem Hause auf, über dem Mein Name ist genannt, es zu verunreinigen.',
        31: 'Und bauen die Opferhöhen des Topheth in der Schlucht des Ben-Hinnom, um ihre Söhne und ihre Töchter im Feuer zu verbrennen, was Ich nicht geboten, und was Mir nicht in das Herz heraufgekommen ist.',
        32: 'Darum, siehe, es kommen Tage, spricht Jehovah, da man nicht mehr wird sagen Topheth oder die Schlucht des Ben-Hinnom, sondern die Schlucht des Würgens und in Topheth werden sie begraben, bis daß kein Raum da ist.',
        33: 'Und dieses Volkes Leichname werden zur Speise sein für des Himmels Gevögel und dem Getier der Erde, und niemand wird sie aufscheuchen.',
        34: 'Und von den Städten Judahs und von den Gassen Jerusalems lasse Ich aufhören die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut; denn zur Öde wird das Land.',
    },
    8: {
        1: 'Zu derselben Zeit, spricht Jehovah, wird man die Gebeine der Könige Jehudahs und die Gebeine seiner Obersten und die Gebeine der Priester und die Gebeine der Propheten und die Gebeine der Bewohner Jerusalems aus ihren Gräbern herausbringen.',
        2: 'Und sie werden sie ausspreiten vor die Sonne und den Mond und alles Heer der Himmel, die sie geliebt und denen sie gedient und denen sie nachgegangen und denen sie nachgefragt und die sie angebetet hatten. Sie werden nicht gesammelt und nicht begraben. Zum Dünger auf dem Angesichte des Bodens werden sie.',
        3: 'Und der Tod wird gewählt werden vor dem Leben bei all dem Überrest, der von dieser bösen Familie verblieben ist an allen übriggebliebenen Orten, wohin Ich sie verstoßen hatte, spricht Jehovah der Heerscharen.',
        4: 'Und sprich zu ihnen: Also spricht Jehovah: Werden sie fallen, und nicht aufstehen? Wird der, so sich hat abgekehrt, nicht zurückkehren?',
        5: 'Warum hat dieses Volk sich abgekehrt, Jerusalem, in immerwährender Abkehr? Sie halten an ihrem Truge fest, sie weigern sich zurückzukehren.',
        6: 'Ich horchte und hörte: Nichts Rechtes reden sie. Da ist kein Mann, den seine Bosheit reuete, der spräche: Was habe ich getan? Sie alle kehren zurück in ihrem Lauf, wie das Roß hinrennt in den Streit.',
        7: 'Auch der Storch am Himmel weiß seine bestimmte Zeit, und die Turteltaube und die Schwalbe und der Kranich halten die Zeit ihres Kommens, aber Mein Volk weiß nicht das Recht Jehovahs.',
        8: 'Wie möget ihr sprechen: Weise sind wir, und das Gesetz Jehovahs ist bei uns! Aber siehe, zur Lüge hat es gemacht der Lügengriffel der Schreiber.',
        9: 'Beschämt sind die Weisen, sie sind entsetzt und gefangen. Siehe, das Wort Jehovahs verschmähten sie, und was für Weisheit haben sie?',
        10: 'Darum gebe Ich anderen ihre Weiber, ihre Felder denen, so sie erblich besitzen. Denn allesamt vom Kleinen und bis zum Großen geizen sie nach Gewinn. Von den Propheten und bis zum Priester treibt jeder Lüge.',
        11: 'Und sie heilen leichthin den Bruch der Tochter Meines Volkes und sprechen: Friede, Friede! und ist kein Friede da.',
        12: 'Schämen sie sich, daß sie Greuel taten? Sie schämen sich auch mit keiner Scham und wissen nichts von Schande; darum müssen sie zur Zeit ihrer Heimsuchung fallen unter den Fallenden, sie sollen straucheln, spricht Jehovah.',
        13: 'Wegraffend raffe Ich sie weg, spricht Jehovah: Keine Weinbeeren sind am Weinstock und keine Feigen am Feigenbaum, und das Blatt ist abgefallen; und Ich will sie geben denen, so an ihnen vorübergehen.',
        14: 'Wofür sitzen wir da? Versammelt euch, und lasset uns in die festen Städte eingehen und daselbst untergehen; denn untergehen läßt uns Jehovah, unser Gott, und läßt uns Wasser der Galle trinken, weil wir wider Jehovah gesündigt haben.',
        15: 'Man hofft auf Frieden und nichts Gutes ist da; auf eine Zeit der Heilung, und siehe da, Schrecknis.',
        16: 'Von Dan her hört man seiner Rosse Schnauben, von der Stimme des Wieherns seiner Gewaltigen erbebt das ganze Land. Und sie kommen und fressen auf das Land und seine Fülle, die Stadt und die darin wohnen.',
        17: 'Denn siehe, Schlangen, Basilisken sende Ich wider euch. Für die ist keine Beschwörung, und sie sollen euch beißen, spricht Jehovah.',
        18: 'Gibt es Linderung für mich über den Gram? Mein Herz ist siech!',
        19: 'Siehe, die Stimme des Angstschreis der Tochter meines Volkes aus dem Lande der Ferne! Ist denn Jehovah nicht in Zijon? Ist ihr König nicht in ihr? Warum haben sie mich gereizt mit ihren Schnitzbildern, mit des Auslandes Nichtigkeiten?',
        20: 'Die Ernte ist vorbei, der Sommer ist zu Ende, und wir sind nicht gerettet.',
        21: 'Ich bin gebrochen ob dem Bruch der Tochter meines Volkes, ich bin verdüstert, Erstaunen erfasset mich.',
        22: 'Ist kein Balsam in Gilead? Ist kein Arzt daselbst? Warum ersteht keine Genesung der Tochter meines Volkes? Wer gäbe, daß mein Haupt Wasser werde, und mein Auge ein Born der Tränen, daß ich bei Tag und Nacht beweinete die Erschlagenen der Tochter meines Volkes!',
    },
    9: {
        1: 'Wer gibt Mir in der Wüste eine Herberge der Reisenden, so verließe Ich Mein Volk und ginge von ihnen; denn sie alle sind Ehebrecher, eine Rotte von Treulosen.',
        2: 'Und sie spannen ihre Zungen als ihren Bogen der Lüge, und nicht für Wahrheit sind mächtig sie im Lande; denn von Bösem gehen sie auf Böses aus, und Mich kennen sie nicht, spricht Jehovah.',
        3: 'Der Mann hüte sich vor seinem Genossen, und vertraue auf keinen Bruder; denn jeder Bruder überlistet und jeder Genosse geht als Zwischenträger um.',
        4: 'Und der Mann hintergeht seinen Genossen, und Wahrheit reden sie nicht. Sie lehren ihre Zunge Lüge reden. Sie mühen sich ab, verkehrt zu handeln.',
        5: 'Du wohnst mitten unter Trug. Vor Trug weigern sie sich, Mich zu erkennen, spricht Jehovah.',
        6: 'Darum spricht also Jehovah der Heerscharen: Siehe, läutern und prüfen will Ich sie. Denn was sollte Ich tun vor der Tochter Meines Volkes?',
        7: 'Ein geschärfter Pfeil ist ihre Zunge. Trug redet sie. Mit seinem Munde redet er Frieden mit dem Genossen, und in seinem Inneren legt er ihm einen Hinterhalt.',
        8: 'Sollte über solchem Ich sie nicht heimsuchen? spricht Jehovah. Sollte an einer Völkerschaft wie diese nicht Meine Seele Rache nehmen?',
        9: 'Über die Berge will Ich ein Weinen erheben und ein Trauerlied, und über der Wüste Auen ein Klagelied. Denn sie sind versengt, so daß kein Mann vorübergeht, und man nicht hört die Stimme der Viehherde. Sie sind entflohen, hingegangen, vom Gevögel der Himmel bis zum Vieh.',
        10: 'Und Ich gebe Jerusalem dahin, zum Trümmerhaufen, zur Wohnstätte der Drachen und die Städte Jehudahs gebe Ich zur Verwüstung ohne Bewohner.',
        11: 'Wer ist der weise Mann, daß er dies einsehe und zu dem Jehovahs Mund geredet, daß er es ansage? Weshalb wird dieses Land zerstört, versengt wie die Wüste, daß niemand durchgeht?',
        12: 'Und Jehovah spricht: Darum, daß sie verlassen Mein Gesetz, das Ich vor sie gegeben, und auf Meine Stimme nicht gehört und nicht danach gewandelt haben;',
        13: 'Und gingen der Verstocktheit ihrer Herzen nach und nach den Baalen, wie ihre Väter sie gelehrt hatten.',
        14: 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels, siehe, Ich lasse dieses Volk Wermut essen und tränke sie mit Wasser der Galle.',
        15: 'Und zerstreue sie unter die Völkerschaften, die weder sie selbst noch ihre Väter kannten, und sende ihnen das Schwert nach, bis Ich sie aufgerieben.',
        16: 'So spricht Jehovah der Heerscharen: Merket auf und ruft den Klageweibern, daß sie kommen, und sendet nach den weisen Frauen, daß sie kommen.',
        17: 'Daß sie eilen und über uns das Trauerlied erheben, und Tränen von unseren Augen herabrinnen, und Wasser von unseren Wim- pern riesle.',
        18: 'Denn aus Zijon hört man des Trauerliedes Stimme: Wie sind wir verheert, wir sind beschämt sehr. Denn wir verlassen das Land, denn niedergeworfen sind unsere Wohnungen.',
        19: 'Ja, höret, ihr Weiber, Jehovahs Wort, und Seines Mundes Wort nehmet zu Ohr, und lehret eure Töchter das Trauerlied und das Weib die Genossin das Klagelied.',
        20: 'Denn zu unseren Fenstern steigt herauf der Tod, er kommt in unsere Paläste, auszurotten das Kindlein aus der Gasse, die Jünglinge aus der Straße.',
        21: 'Rede: So spricht Jehovah: Wie Dünger fällt des Menschen Leichnam auf des Feldes Angesicht und wie die Garbe hinter dem Schnitter, und keiner sammelt sie.',
        22: 'So spricht Jehovah: Nicht rühme der Weise sich seiner Weisheit und nicht rühme der Mächtige sich seiner Macht; nicht rühme der Reiche sich seines Reichtums.',
        23: 'Sondern wer sich rühmen will, der rühme sich, daß er verständig ist und Mich kennt, daß Ich Jehovah bin, Welcher tut Barmherzigkeit, Recht und Gerechtigkeit auf Erden; denn daran habe Ich Lust, spricht Jehovah.',
        24: 'Siehe, es kommen Tage, spricht Jehovah, daß Ich an allen die Beschneidung in der Vorhaut heimsuche.',
        25: 'An Ägypten und an Jehudah und an Edom, und an den Söhnen Ammons und an Moab und an allen, welche die Ecke stutzen, die in der Wüste wohnen; denn alle die Heiden sind unbeschnitten und das ganze Haus Israels ist unbeschnittenen Herzens.',
    },
    10: {
        1: 'Höret das Wort, das Jehovah über euch redet, ihr vom Hause Israels.',
        2: 'So spricht Jehovah: Lernet nicht den Weg der Völkerschaften und entsetzet euch nicht ob den Zeichen an dem Himmel, denn die Völkerschaften entsetzen sich darob.',
        3: 'Denn nichtig sind die Satzungen der Völker: Wenn man den Baum im Walde umgehauen, ein Werk von den Händen der Werkleute mit dem Beile.',
        4: 'Mit Silber und mit Gold macht er ihn schön, und macht ihn fest mit Nägeln und mit Hämmern, daß er nicht schlottere.',
        5: 'Fest wie die Palmen sind sie und reden nicht, sie müssen sie tragen, weil sie nicht schreiten. Fürchtet euch nicht vor ihnen: Sie können kein Übel tun, und auch Gutes zu tun, ist nicht bei ihnen.',
        6: 'Von wannen ist einer wie Du, Jehovah? Du bist groß und groß ist Dein Name an Macht.',
        7: 'Wer sollte Dich nicht fürchten, Du König der Völkerschaften? Dir ja kommt es zu. Denn von wannen unter allen Weisen der Völkerschaften und in irgendeinem ihrer Reiche ist einer wie Du?',
        8: 'Allzumal sind sie tierisch und dumm. Eine nichtige Belehrung ist das Holz.',
        9: 'Breitgeschlagenes Silber wird aus Tharschisch herbeigebracht und das Gold aus Uphas, gemacht vom Werkmann und den Händen des Goldschmiedes, blauer und roter Purpur ihr Gewand; ein Machwerk der Weisen sind sie alle.',
        10: 'Aber Jehovah ist ein Gott der Wahrheit, ein lebendiger Gott ist Er und ein König der Ewigkeit. Vor Seiner Entrüstung erbebt die Erde, und Seinen Unwillen halten die Völkerschaften nicht aus.',
        11: 'Also sollt ihr zu ihnen sprechen: Die Götter, die den Himmel und die Erde nicht gemacht, sie sollen von der Erde und unter dem Himmel weg zerstört werden.',
        12: 'Er hat die Erde gemacht durch Seine Kraft, die Welt bereitet durch Seine Weisheit und durch Seine Einsicht die Himmel ausgespannt;',
        13: 'Gibt Seine Stimme Er dahin, so ist eine Menge der Wasser an den Himmeln, und von der Erde Ende läßt Er Dünste aufsteigen, Er macht Blitze für den Regen und bringt heraus die Winde aus Seinen Schatzkammern.',
        14: 'Tierisch ist jeder Mensch durch das Wissen, beschämt wird jeder Goldschmied durch sein Schnitzbild. Denn sein Gußbild ist Lüge und kein Hauch ist in denselben.',
        15: 'Nichtigkeit sind sie, ein Machwerk der Irrtümer, sie vergehen zur Zeit ihrer Heimsuchung.',
        16: 'Nicht wie sie ist Jakobs Teil; denn Er ist es, Der das Ganze gebildet hat, und Israel ist Seines Erbes Rute; Jehovah der Heerscharen ist Sein Name.',
        17: 'Sammle ein deine Ware von der Erde, die du im Bollwerk sitzest.',
        18: 'Denn also spricht Jehovah: Siehe, diesmal schleudere Ich weg die, so im Lande wohnen, und bedränge sie, daß sie es ausfinden.',
        19: 'Wehe mir, ob meinem Bruch, mein Schlag ist schmerzhaft, aber ich spreche: Das ist eben meine Krankheit und ich will sie tragen.',
        20: 'Verheert ist mein Zelt und alle meine Seile abgerissen, meine Söhne sind von mir ausgezogen und sind nicht mehr. Ich habe keinen, der noch mein Zelt aufspannt und meine Teppiche aufrichtet.',
        21: 'Denn tierisch sind geworden die Hirten, und haben Jehovah nicht nachgefragt und waren darum nicht klug, und alles, was sie weiden, wird zerstreut.',
        22: 'Die Stimme eines Gerüchtes, siehe, es kommt und ein groß Erbeben vom Land der Mitternacht, um die Städte Jehudahs zur Verwüstung zu setzen, eine Wohnstätte der Drachen.',
        23: 'Ich weiß, Jehovah, daß dem Menschen sein Weg nicht gehört, noch dem Manne, zu wandeln und seinen Schritt zu richten.',
        24: 'Züchtige mich, Jehovah, doch nach dem Recht, nicht in Deinem Zorne, daß Du meiner nicht wenig machst.',
        25: 'Schütte Deinen Grimm aus über die Völkerschaften, die Dich nicht kennen, und über die Familien, die Deinen Namen nicht anrufen, denn sie fraßen Jakob auf, sie fraßen ihn auf und rieben ihn auf, und machten wüste seinen Wohnort.',
    },
    11: {
        1: 'Das Wort, das von Jehovah an Jirmejahu geschah und sprach:',
        2: 'Höret die Worte dieses Bundes und redet zu dem Mann Jehudahs und zu denen, die da wohnen in Jerusalem.',
        3: 'Und sprich zu ihnen: Also spricht Jehovah, der Gott Israels: Verflucht der Mann, der nicht hört auf die Worte dieses Bundes,',
        4: 'Den Ich euren Vätern habe geboten am Tage, da Ich sie herausbrachte aus dem Lande Ägypten, aus dem Schmelzofen von Eisen, und sprach: Höret auf Meine Stimme und tut sie, nach allem, was Ich euch geboten habe, auf daß ihr Mein Volk seiet, und Ich euer Gott sei.',
        5: 'Auf daß den Schwur Ich aufrecht erhalte, den euren Vätern Ich geschworen habe, ihnen ein Land zu geben, da Milch und Honig fließt, wie an diesem Tag. Und ich antwortete und sprach: Amen, Jehovah.',
        6: 'Und Jehovah sprach zu mir: Rufe alle diese Worte in den Städten Jehudahs und in den Gassen Jerusalems und sprich: Höret die Worte dieses Bundes und tut sie!',
        7: 'Denn Ich habe euren Vätern ernstlich bezeugt an dem Tage, da Ich sie aus dem Lande Ägypten heraufbrachte bis auf diesen Tag, indem Ich früh aufstand, und bezeugte, sprechend: Höret auf Meine Stimme!',
        8: 'Aber sie hörten nicht und neigten nicht ihr Ohr, und wandelten jeder Mann nach der Verstockung ihres bösen Herzens; so will Ich denn auch über sie kommen lassen alle die Worte dieses Bundes, die Ich gebot zu tun, und sie taten es nicht.',
        9: 'Und Jehovah sprach zu mir: Es findet sich eine Verschwörung bei dem Manne Jehudahs und bei den Bewohnern Jerusalems.',
        10: 'Sie sind zu den früheren Missetaten ihrer Väter zurückgekehrt, die sich geweigert hatten, auf Meine Worte zu hören, und anderen Göttern nachgingen, ihnen zu dienen. Sie, das Haus Israel und das Haus Jehudah, haben Meinen Bund zunichte gemacht, den Ich mit ihren Vätern geschlossen hatte.',
        11: 'Darum siehe, so spricht Jehovah, Ich bringe Böses über sie, aus dem sie nicht vermögen herauszukommen; und sie werden zu Mir schreien, aber Ich höre nicht auf sie.',
        12: 'Und die Städte Jehudahs und die Bewohner Jerusalems sollen gehen und zu den Göttern schreien, denen sie räucherten; aber sie werden ihnen zur Zeit ihres Übels nicht helfen.',
        13: 'Denn nach der Zahl deiner Städte, Jehudah, waren deine Götter, und nach der Zahl der Gassen Jerusalems stelltest du Altäre der Scham auf, Altäre dem Baal zu räuchern.',
        14: 'Du aber bete nicht für dieses Volk und erhebe für sie keinen Klageruf, noch Gebet; denn Ich höre nicht zur Zeit, da sie zu Mir rufen in ihrem Übel.',
        15: 'Was hat mein Liebling in meinem Haus zu tun, wenn die vielen Arglist üben und das Fleisch der Heiligkeit von dir hinübergeht. Bei deiner Bosheit jauchzest du.',
        16: 'Einen grünen Ölbaum, schön von Frucht, von Gestalt, nannte Jehovah deinen Namen. Mit der Stimme eines großen Brausens zündet Er ein Feuer wider ihn an und sie zerbrechen seine Äste.',
        17: 'Und Jehovah der Heerscharen, Der dich gepflanzt, hat Böses über dich geredet wegen der Bosheit des Hauses Israel und des Hauses Jehudah, das sie für sich getan, damit daß sie Mich reizten, daß sie dem Baal räucherten.',
        18: 'Und mir hat es zu wissen getan Jehovah, und ich weiß es, da hast Du ihr Tun mich sehen lassen.',
        19: 'Ich aber war wie ein Leiter der Schafe, der zum Schlachten dargebracht wird, und wußte nicht, daß sie über mich Gedanken dachten: Laßt uns den Baum in seinem Saft verderben und ihn aus dem der Lebenden ausrotten, daß seines Namens nicht mehr werde gedacht.',
        20: 'Du aber, Jehovah der Heerscharen, bist ein gerechter Richter, prüfest Nieren und Herz. Laß Deine Rache mich an ihnen sehen; denn Dir habe ich meinen Hader geoffenbart.',
        21: 'Darum, so spricht Jehovah über die Männer Anathoths, die dir nach der Seele trachten und sagen: Weissage nicht in Jehovahs Namen, daß du nicht durch unsere Hände sterbest.',
        22: 'Darum, so spricht Jehovah der Heerscharen: Siehe, Ich werde sie heimsuchen; die Jünglinge sollen durch das Schwert sterben, ihre Söhne und ihre Töchter vor Hunger sterben.',
        23: 'Und kein Überrest wird von ihnen sein, denn Böses lasse Ich kommen über die Männer Anathoths im Jahre ihrer Heimsuchung.',
    },
    12: {
        1: 'Gerecht bist Du, Jehovah, wenn ich mit Dir hadere, doch will ich von Gerichten mit Dir reden. Warum gelingt der Weg der Ungerechten? behaglich sind alle Treulosen, die treulos handeln.',
        2: 'Du pflanztest sie, auch wurzeln sie. Sie gehen und bringen auch Frucht. Nah bist Du ihrem Mund, und fern von ihren Nieren.',
        3: 'Du aber kennst mich, Jehovah, Du siehst mich und prüfst mein Herz bei Dir. Reiße sie weg wie Schafe zur Schlachtung und heilige sie für den Tag des Würgens!',
        4: 'Wie lange soll das Land trauern und das Kraut auf allem Felde verdorren ob der Bosheit derer, die darin wohnen, Vieh und Gevögel weggerafft werden, weil sie sagen: Er sieht nicht auf unser Letztes.',
        5: 'Wenn du mit Fußgängern läufst, und sie dich ermüden, wie willst du es Rossen gleichtun? und wenn im Land des Friedens du vertraust, und was tust du, bei des Jordans Hochmut?',
        6: 'Denn auch deine Brüder und deines Vaters Haus, auch sie wurden dir treulos, auch sie riefen vollauf dir nach. Glaube ihnen nicht, wenn Gutes sie mit dir reden.',
        7: 'Mein Haus habe Ich verlassen, Mein Erbe hingegeben, habe das Liebste Meiner Seele in die Hand ihrer Feinde gegeben.',
        8: 'Mein Erbe ist Mir wie der Löwe im Wald geworden, gibt seine Stimme wider Mich hervor, darum hasse Ich es.',
        9: 'Ist ein buntfarbiger Raubvogel Mir Mein Erbe? Raubvögel ringsum wider dasselbe. Geht, sammelt alles wilde Tier des Feldes! Bringt es her zum Fraß.',
        10: 'Viele Hirten haben Meinen Weinberg verdorben, Meinen Teil zertreten, sie machen den Teil Meines Begehrens zur Wüste der Einöde.',
        11: 'Zur Verwüstung hat man ihn gemacht. Er trauert vor Mir, verwüstet und wüste gelegt ist das ganze Land; denn kein Mann ist da, der es zu Herzen nimmt.',
        12: 'Über alle Anhöhen in der Wüste kommen die Verheerer; denn Jehovahs Schwert frißt vom Landesende und bis zum Landesende. Kein Fleisch hat Frieden.',
        13: 'Weizen säen sie und ernten Dornen, mühen sich ab und haben keinen Nutzen. Und ihr schämt euch eures Ertrages vor der Entbrennung von Jehovahs Zorn.',
        14: 'So spricht Jehovah: Über alle Meine bösen Nachbarn, die das Erbe anrühren, das Ich Mein Volk Israel erben ließ: Siehe, Ich reiße sie aus ihrem Boden und das Haus Jehudah reiße Ich aus ihrer Mitte.',
        15: 'Und soll geschehen, wenn Ich sie ausgerissen habe, daß Ich Mich zurückwende und ihrer Mich erbarme, und sie zurückbringe; jeden Mann in sein Erbe und jeden Mann in sein Land.',
        16: 'Und soll geschehen, wenn sie die Wege Meines Volkes lernen, zu schwören bei Meinem Namen: Beim Leben Jehovahs, wie sie Mein Volk gelehrt hatten, beim Baal zu schwören, so sollen sie inmitten Meines Volkes aufgebaut werden.',
        17: 'Wo aber sie nicht hören, will Ich solche Völkerschaft ausreißen und zerstören, spricht Jehovah.',
    },
    13: {
        1: 'So spricht zu mir Jehovah: Gehe und kaufe dir einen leinenen Gurt und lege ihn um deine Lenden, aber bring ihn nicht ins Wasser.',
        2: 'Und ich kaufte den Gurt nach dem Wort Jehovahs und legte ihn um meine Lenden.',
        3: 'Und es geschah Jehovahs Wort an mich zum zweitenmal, sprechend:',
        4: 'Nimm den Gurt, den du gekauft, der um deine Lenden ist, und stehe auf und gehe nach dem Phrath und lege ihn da hehlings in die Kluft der Felsenklippe.',
        5: 'Und ich ging und legte ihn hehlings an dem Phrath so, wie Jehovah mir geboten hatte.',
        6: 'Und es geschah am Ende vieler Tage, daß Jehovah zu mir sprach: Stehe auf, gehe nach dem Phrath und nimm von da den Gurt, den Ich dir gebot allda hehlings hinzulegen.',
        7: 'Und ich ging nach dem Phrath und ich grub und nahm den Gurt vom Ort, da ich ihn hehlings hingelegt hatte, und siehe, der Gurt war verdorben, daß er zu nichts mehr taugte.',
        8: 'Und es geschah an mich Jehovahs Wort, sprechend:',
        9: 'So spricht Jehovah: Ebenso will Ich verderben den Stolz Jehudahs und den vielen Stolz Jerusalems.',
        10: 'Dies böse Volk, sie, die sich weigern zu hören auf Meine Worte, die hingehen in der Verstocktheit ihres Herzens und anderen Göttern nachgehen, ihnen zu dienen und sie anzubeten, soll werden gleich wie dieser Gurt, der zu nichts taugt.',
        11: 'Denn wie der Gurt anhaftet an des Mannes Lenden, so habe Ich Mir lassen anhaften das ganze Haus Israels und das ganze Haus Jehudahs, spricht Jehovah, daß es Mir sei zum Volk und zum Namen und zum Lob und zum Schmuck, aber sie haben nicht gehört.',
        12: 'So sage ihnen dies Wort: So spricht Jehovah, der Gott Israels: Jeglicher Schlauch wird mit Wein gefüllt! Und sagen sie zu dir: Wissen wir nicht, daß jeglicher Schlauch soll mit Wein gefüllt werden?',
        13: 'So sprich zu ihnen: So spricht Jehovah: Siehe, Ich erfülle alle, die in diesem Lande wohnen, und die Könige, die von David auf seinem Throne sitzen, und die Priester und die Propheten und alle Bewohner Jerusalems, mit starkem Getränk.',
        14: 'Und will zerstreuen den Mann mit seinem Bruder und die Väter und die Söhne allzumal, spricht Jehovah. Ich will nicht Mitleid haben, noch schonen, und Mich nicht erbarmen, daß Ich sie nicht verderbe.',
        15: 'Höret und nehmt zu Ohren, seid nicht hoffärtig. Denn Jehovah redet!',
        16: 'Gebet Jehovah, eurem Gott, die Herrlichkeit, bevor Er es finster werden läßt und bevor eure Füße sich stoßen an den Bergen der Dämmerung und ihr hoffet auf Licht; Er aber wird es zum Todesschatten machen, und in Wolkendunkel setzen.',
        17: 'Und wenn ihr nicht darauf hört, wird meine Seele im Verborgenen weinen ob dem Hochmut und mein Auge tränt und fließt in Tränen herab, daß Jehovahs Herde gefangengenommen wird.',
        18: 'Saget dem Könige und der Gebieterin: Erniedrigt euch, setzt euch hin, denn herabgefallen ist euer Kopfputz, die Krone eures Schmuckes.',
        19: 'Des Mittags Städte sind geschlossen und niemand öffnet sie; ganz Jehudah ist weggeführt, weggeführt ist Schelomim!',
        20: 'Erhebet eure Augen und sehet, die da kommen von Mitternacht! Wo ist nun die Herde, die dir gegeben war, die Herde, deines Schmuckes?',
        21: 'Was wirst du sagen, wenn Er über dir heimsucht? Und du hast sie gelehrt als Leiter über dich zum Haupte zu sein. Sollten nicht Geburtsnöte dich ergreifen, wie ein Weib, die gebären soll?',
        22: 'Und wenn du sprichst in deinem Herzen: Warum ist solches mir begegnet? Ob der Menge deiner Missetat wurden deine Säume aufgedeckt und deinen Fersen wurde Gewalt angetan.',
        23: 'Kann auch ein Mohr seine Haut wandeln, und ein Pardel seine Flecken? So vermöchtet auch ihr Gutes zu tun, die ihr gelernt habt, Böses tun.',
        24: 'Und Ich will sie zerstreuen wie die Spreu, die bei der Wüste Wind vorüberfährt.',
        25: 'Das soll dein Los sein, dein Anteil, von Mir dir zugemessen, spricht Jehovah, daß du hast Mein vergessen und auf die Lüge vertraust.',
        26: 'Und Ich will auch deine Säume entblößen über dein Angesicht, daß deine Unehre gesehen werde.',
        27: 'Deine Ehebrüche und dein Wiehern, die Unzucht deiner Buhlerei auf den Hügeln, im Felde, deine Scheusale habe Ich gesehen. Wehe dir, Jerusalem, willst du dich nicht hernachmals reinigen? Wie lange noch?',
    },
    14: {
        1: 'Was als Jehovahs Wort geschah an Jirmejahu über das Wort der Dürre.',
        2: 'Jehudah trauert und seine Tore verschmachten, verdüstert bis zur Erde, und das Klagegeschrei Jerusalems steigt auf.',
        3: 'Und ihre Stattlichen senden nach Wasser ihre Geringen. Sie kommen zu den Graben, sie finden kein Wasser, leer kehren ihre Gefäße zurück. Sie sind beschämt und in Schande, und haben verhüllt ihr Haupt,',
        4: 'Weil der Boden klaffet, denn kein Regen war im Land. Beschämt sind die Ackerleute, sie haben verhüllt ihr Haupt.',
        5: 'Denn auch die Hindin auf dem Felde gebiert und verläßt es, weil kein junges Grün da ist.',
        6: 'Und Waldesel stehen auf den Anhöhen, schnappen nach Wind wie die Walfische, ihre Augen sind verzehrt, denn kein Kraut ist da.',
        7: 'Wenn unsere Missetaten wider uns antworten, o Jehovah, tue Du es um Deines Namens willen; denn viel sind unserer Abwendungen; wider Dich haben wir gesündigt.',
        8: 'Du Hoffnung Israels, Du, sein Retter zur Zeit der Drangsal, warum willst Du sein wie ein Fremdling in dem Lande, und wie ein Wanderer, der einkehrt, um zu übernachten?',
        9: 'Warum bist Du wie ein verlegener Mann, wie ein Held, der nicht zu retten vermag? Und Du bist in unserer Mitte, Jehovah, und Dein Name wird über uns genannt. Laß nicht ab von uns.',
        10: 'So spricht Jehovah zu diesem Volke: So lieben sie es umherzuwandern, und halten ihre Füße nicht zurück, und Jehovah hat kein Gefallen an ihnen. Jetzt gedenkt Er ihrer Missetat und sucht heim ihre Sünden.',
        11: 'Und Jehovah sprach zu mir: Bete nicht für dieses Volk zum Guten!',
        12: 'Wenn sie gleich fasten, höre Ich nicht auf ihren Klageruf, und wenn sie gleich Brandopfer und Speiseopfer darbringen, habe Ich kein Gefallen; mit Schwert und mit Hunger und mit Pestilenz mache Ich sie alle.',
        13: 'Und ich sagte: Ach, Herr Jehovah, siehe, die Propheten sagen ihnen: Ihr werdet kein Schwert sehen und Hunger wird nicht bei euch sein, sondern der Wahrheit Frieden gebe ich euch an diesem Ort.',
        14: 'Jehovah aber sprach zu mir: Lüge weissagen die Propheten in Meinem Namen, Ich habe sie nicht gesandt und ihnen nicht geboten und nicht zu ihnen geredet. Ein Gesicht der Lüge und Wahrsagerei und Nichtiges und den Trug ihres Herzens weissagen sie euch.',
        15: 'Darum spricht also Jehovah über die Propheten, die weissagen in Meinem Namen und Ich habe sie nicht gesandt, und die da sagen: Schwert und Hunger wird nicht sein in diesem Lande: Durch Schwert und Hunger sollen diese Propheten umkommen.',
        16: 'Und hingeworfen wird das Volk, dem sie geweissagt, auf die Gassen Jerusalems vor dem Hunger und dem Schwert und ist niemand, der sie begräbt, sie, ihre Weiber und ihre Söhne und ihre Töchter, und Ich schütte über sie ihre Bosheit aus.',
        17: 'Und du sprich dieses Wort zu ihnen: Nacht und Tag fließen herab mit Tränen Meine Augen, und wollen nicht stille sein, denn mit großem Bruch ist die Jungfrau, die Tochter Meines Volkes zerbrochen, mit einem sehr schmerzhaften Schlage.',
        18: 'Gehe Ich hinaus auf das Feld, und siehe, vom Schwert Erschlagene; und komme Ich in die Stadt, und siehe, Erkrankungen vom Hunger; denn beide, der Prophet wie der Priester, wandern im Land umher und wissen nichts.',
        19: 'Hast Du Jehudah ganz verschmäht? Ist Deine Seele Zijons überdrüssig? Warum hast Du uns geschlagen, daß keine Heilung für uns da ist? Wir hofften auf Frieden und da war nichts Gutes, und auf eine Zeit der Heilung, und siehe, Schrecknis.',
        20: 'Jehovah, wir erkennen unsere Ungerechtigkeit, unserer Väter Missetat, daß wider Dich wir sündigten.',
        21: 'Verwirf nicht um Deines Namens willen, verunehre nicht den Thron Deiner Herrlichkeit; gedenke, mache nicht zunichte Deinen Bund mit uns.',
        22: 'Ist da einer der Nichtigkeiten der Völkerschaften, der regnen lassen kann, und können die Himmel Regengüsse geben? Bist Du es nicht, Jehovah, unser Gott? Und auf Dich hoffen wir; denn Du tust alles dies.',
    },
    15: {
        1: 'Und Jehovah sprach zu mir: Ständen Mose und Samuel vor Meinem Angesicht, so wäre Meine Seele doch nicht für dieses Volk. Sende sie von Meinem Angesicht, daß sie hinausgehen.',
        2: 'Und es geschehe, wenn sie zu dir sagen: Wohin sollen wir hinausgehen? so sprich zu ihnen: So spricht Jehovah! Die, so da sind für den Tod, zum Tode; die für das Schwert, zum Schwert; die für den Hunger, zum Hunger; und die für die Gefangenschaft, zur Gefangenschaft!',
        3: 'Und mit vier Arten suche Ich sie heim, spricht Jehovah, mit dem Schwerte, sie zu erwürgen, und mit den Hunden, sie herumzuschleifen, und mit dem Gevögel der Himmel und dem Getier der Erde, sie zu fressen und zu verderben.',
        4: 'Und Ich gebe sie zu einer Aufregung für alle Königreiche der Erde, wegen Menascheh, dem Sohne Jechiskijahus, des Königs von Jehudah, ob dem, das er getan hat in Jerusalem.',
        5: 'Denn wer wird dich bemitleiden, Jerusalem, und wer dich bedauern, und wer sich hinwenden, um nach deinem Frieden zu fragen?',
        6: 'Du hast Mich aufgegeben, spricht Jehovah, bist hinter dich gegangen. Und Ich habe Meine Hand über dich ausgereckt, daß Ich dich verderbe, Ich bin des Tröstens müde.',
        7: 'Und will sie mit der Worfschaufel zu des Landes Toren hinausschaufeln, kinderlos machen, zerstören Mein Volk, da sie von ihren Wegen nicht zurückkehrten.',
        8: 'Zahlreicher werden Mir seine Witwen als der Sand der Meere, und Ich bringe über die Mutter des Jünglings den Verheerer am Mittage, und lasse plötzlich über sie fallen Wehen und Bestürzung.',
        9: 'Es verschmachtet die, so sieben geboren, sie haucht ihre Seele aus, ihre Sonne geht unter, während es noch Tag ist. Sie ist beschämt und errötet; und ihren Überrest gebe Ich dem Schwerte vor ihren Feinden, spricht Jehovah.',
        10: 'Wehe mir, meine Mutter, daß du mich geboren! Ein Mann des Haders bin ich und ein Mann des Rechtens für das ganze Land. Ich lieh nicht und sie liehen mir nicht. Sie alle doch fluchen mir.',
        11: 'Es sprach Jehovah: Lasse Ich dich nicht befreien zum Guten, lasse Ich nicht vermitteln für dich beim Feind zur Zeit des Übels und zur Zeit der Drangsal?',
        12: 'Wird denn zerbrochen werden das Eisen, das Eisen von Mitternacht und das Erz?',
        13: 'Dein Vermögen und deine Schätze will Ich ohne Kaufpreis zum Raube geben, und das um all eurer Sünden willen, und in allen euren Grenzen.',
        14: 'Und Ich lasse deine Feinde übergehen in ein Land, das du nicht kennst. Denn Feuer ist angefacht in Meinem Zorn, über euch lodert es auf.',
        15: 'Du weißt es, Jehovah, gedenke meiner und suche mich heim, und räche mich an meinen Verfolgern. Nimm mich nicht hin in Deiner Langmut, wisse, daß ob Deiner ich Schmach trage.',
        16: 'Deine Worte wurden gefunden und ich verzehrte sie, und Deine Worte wurden mir zur Freude und zur Fröhlichkeit meines Herzens; denn Dein Name ward über mich genannt, Jehovah, Gott der Heerscharen.',
        17: 'Ich saß nicht in dem Kreis der Scherzenden und jauchzte. Einsam saß ich vor Deiner Hand; denn mit Unwillen hattest Du mich erfüllt.',
        18: 'Warum ist mein Schmerz immerwährend und meine Wunde verzweifelt, weigert sich zu heilen? Bist du wirklich mir falsch, Wasser, die nicht währen?',
        19: 'Darum, so spricht Jehovah: So du zurückkehrst und Ich dich zu Mir zurückwende, sollst du vor Meinem Angesicht stehen und wenn du herausbringst das Kostbare von dem Mißachteten, sollst du sein, wie Mein Mund. Sie sollen zu dir zurückkehren und du sollst dich nicht zu ihnen zurückkehren.',
        20: 'Und Ich mache dich für dies Volk zu einer befestigten Mauer von Erz, und sie werden streiten wider dich, werden aber nichts wider dich vermögen; denn Ich bin mit dir, dir zu helfen und dich zu erretten, spricht Jehovah.',
        21: 'Und Ich will dich erretten aus der Hand der Bösen und dich loskaufen aus der Faust der Trotzigen.',
    },
    16: {
        1: 'Und es geschah das Wort Jehovahs an mich, sprechend:',
        2: 'Du sollst dir kein Weib nehmen und keine Söhne, noch Töchter haben an diesem Ort!',
        3: 'Denn also spricht Jehovah über die Söhne und über die Töchter, die an diesem Ort geboren werden, und über ihre Mütter, die sie gebären, und über ihre Väter, die sie in diesem Lande zeugen:',
        4: 'Sie, die des Todes sterben an Krankheiten, sollen nicht beklagt noch begraben werden; zum Dünger sollen sie auf des Bodens Oberfläche werden, und sollen durch das Schwert und durch Hunger alle werden und ihre Leichen zum Fraß dem Gevögel des Himmels und dem Getier der Erde.',
        5: 'Denn also spricht Jehovah: Gehe nicht hinein in das Haus des Klageschreis, und gehe nicht zu klagen, noch ihnen Beileid zu erzeigen, denn weggenommen habe Ich Meinen Frieden von diesem Volke, spricht Jehovah, die Barmherzigkeit und die Erbarmungen.',
        6: 'Und Kleine und Große werden in diesem Lande sterben, nicht begraben werden sie und nicht wird um sie geklagt werden, und man wird sich ihretwegen nicht ritzen, noch sich kahl machen.',
        7: 'Und sie werden ihnen nichts austeilen ob der Trauer, ihn zu trösten über den Toten, sie auch nicht mit des Trostes Becher tränken über seinen Vater und über seine Mutter.',
        8: 'Und in das Haus des Gastmahls sollst du nicht eingehen, mit ihnen zu sitzen, zu essen und zu trinken.',
        9: 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich lasse von diesem Ort zu Ende kommen vor euren Augen und in euren Tagen die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut.',
        10: 'Und soll geschehen, wenn du alle diese Worte diesem Volk ansagst und sie zu dir sprechen: Warum denn hat Jehovah all dies große Übel über uns geredet, und was ist unsere Missetat und was unsere Sünde, die wir gesündigt wider Jehovah, unseren Gott?',
        11: 'So sollst du zu ihnen sagen: Dafür, daß eure Väter Mich verlassen haben, spricht Jehovah, und gingen anderen Göttern nach, und haben denselben gedient und sie angebetet und Mich verlassen, und haben Mein Gesetz nicht gehalten;',
        12: 'Und ihr noch ärger tut, denn eure Väter, und siehe, ihr geht, jeder Mann der Verstockt- heit seines bösen Herzens nach, daß er nicht hört auf Mich.',
        13: 'Und Ich will euch schleudern aus diesem Lande in das Land, das ihr nicht kennt, weder ihr, noch eure Väter. Und dort mögt ihr anderen Göttern dienen bei Tag und bei Nacht, wo Ich euch keine Gnade geben werde.',
        14: 'Darum seht: Tage kommen, spricht Jehovah, daß man nicht mehr sagen wird: Jehovah lebt, Der die Söhne Israels heraufgebracht hat aus dem Lande Ägypten!',
        15: 'Sondern: Jehovah lebt, Der die Söhne Israels heraufgebracht hat aus dem Land der Mitternacht und aus allen Ländern, dahin Ich sie verstoßen hatte; und Ich will sie wiederbringen auf ihren Boden, den Ich ihren Vätern gegeben hatte.',
        16: 'Siehe, Ich sende nach vielen Fischern, spricht Jehovah, und sie fischen sie, und danach sende Ich nach vielen Jägern, und sie erjagen sie von jedem Berg und von jedem Hügel und aus den Klüften der Felsenklippen.',
        17: 'Denn Meine Augen sind auf allen ihren Wegen; sie können sich vor Meinem Angesichte nicht verbergen, und nicht ist verdeckt vor Meinen Augen ihre Missetat.',
        18: 'Und Ich vergelte vorerst zweifach ihre Missetat und ihre Sünde, darum, daß sie Mein Land entweiht haben mit dem Leichnam ihrer Scheusale, und mit ihren Greueln Mein Erbe angefüllt.',
        19: 'Jehovah, meine Stärke und meine Feste und meine Zuflucht am Tag der Drangsal! Zu Dir werden die Völkerschaften kommen vom Äußersten der Erde und sagen: Nur Lüge haben unsere Väter als Erbe gehabt, Nichtigkeit, und worin kein Nutzen ist.',
        20: 'Kann der Mensch sich Götter machen? Und Götter sind sie nicht.',
        21: 'Darum siehe, Ich tue ihnen zu wissen diesmal, Ich tue ihnen Meine Hand und Meine Macht zu wissen, auf daß sie wissen, daß Mein Name ist Jehovah.',
    },
    17: {
        1: 'Die Sünde Jehudahs ist geschrieben mit eisernem Griffel, mit der Spitze des Demants auf die Tafel ihres Herzens und auf die Hörner eurer Altäre eingegraben.',
        2: 'Gleichwie ihre Söhne gedenken ihrer Altäre und ihrer Ascheren bei grünem Baum auf den hohen Hügeln.',
        3: 'Mein Berg im Felde, dein Vermögen, all deine Schätze gebe Ich dem Raube hin, deine Opferhöhen, ob der Sünde in allen deinen Grenzen.',
        4: 'Und du wirst, und zwar von dir selbst, von deinem Erbe ablassen, das Ich dir gab, und Ich werde dich deinem Feinde dienen lassen in einem Land, das du nicht kennst; denn ihr habt in Meinem Zorn ein Feuer angefacht, das ewiglich wird lodern.',
        5: 'So spricht Jehovah: Verflucht der Mann, der auf den Menschen vertraut, und Fleisch zu seinem Arme setzt, und sein Herz abwendet von Jehovah;',
        6: 'Und wird sein wie ein bloßes Gesträuch in der Einöde, und nicht sehen, wenn Gutes kommt, und wird wohnen in versengten Orten in der Wüste in salzigem Land, da niemand wohnt.',
        7: 'Gesegnet ist der Mann, der vertraut auf Jehovah und dessen Vertrauen Jehovah ist.',
        8: 'Und er ist wie der Baum, gepflanzt am Wasser, der seine Wurzeln ausstreckt an die Wasserleitung, und sieht es nicht, wenn die Hitze kommt. Sein Blatt ist grün, und hat nichts zu sorgen in dem Jahr der Dürre und läßt nicht ab, Frucht zu tragen.',
        9: 'Hinterlistig ist das Herz über alles und ein verzweifelt Ding. Wer kennt es?',
        10: 'Ich, Jehovah, erforsche das Herz, Ich prüfe die Nieren, und gebe dem Mann nach seinen Wegen, nach der Frucht seines Tuns.',
        11: 'Ein Rebhuhn, das da sammelt, aber nicht legt, ist, wer Reichtum gewinnt nicht mit Recht. In der Hälfte seiner Tage wird er ihn verlassen, und zuletzt ist er ein Tor.',
        12: 'Der Thron der Herrlichkeit, die Höhe von Anbeginn ist der Ort unseres Heiligtums.',
        13: 'Jehovah, Hoffnung Israels, alle, die Dich verlassen, werden beschämt, Abtrünnige müssen in die Erde geschrieben werden; denn sie haben den Born lebendiger Wasser, Jehovah, verlassen.',
        14: 'Heile mich, Jehovah, so werde ich heil; rette Du mich, so bin ich gerettet; denn mein Lob bist Du!',
        15: 'Siehe, sie sprechen zu mir: Wo ist das Wort Jehovahs? O, so komme es doch!',
        16: 'Ich aber drängte mich nicht danach, daß ich nicht ein Hirte wäre hinter Dir her und ersehnte den Tag der Verzweiflung nicht. Du weißt es, was von meinen Lippen ausging, war vor Deinem Angesicht.',
        17: 'Sei Du mir nicht zum Entsetzen! Mein Verlaß bist Du am Tag des Übels.',
        18: 'Laß sie sich schämen, die mich verfolgen, und lasse mich nicht beschämt werden. Laß sie sich entsetzen, aber ich sei nicht entsetzt. Bringe über sie den Tag des Übels und zerbrich sie mit zweifacher Zerbrechung!',
        19: 'Also sprach zu mir Jehovah: Gehe hin und stehe im Tor der Söhne des Volkes, durch das die Könige Jehudahs eingehen und durch das sie ausgehen, und in allen Toren Jerusalems.',
        20: 'Und sprich zu ihnen: Höret das Wort Jehovahs, ihr Könige Jehudahs und ganz Jehudah und alle Bewohner Jerusalems, die zu diesen Toren eingehen!',
        21: 'So spricht Jehovah: Hütet euch für eure Seelen und tragt keine Last am Tage des Sabbaths, daß ihr sie einbringt durch die Tore Jerusalems.',
        22: 'Und bringt keine Last aus euren Häusern am Tage des Sabbaths und tut keine Arbeit und heiligt den Tag des Sabbaths, wie Ich geboten habe euren Vätern.',
        23: 'Und sie hörten nicht und neigten nicht ihr Ohr und sie verhärteten ihren Nacken, daß sie nicht hörten und keine Zucht annahmen.',
        24: 'Und es soll geschehen, so ihr hört auf Mich, spricht Jehovah, daß ihr keine Last einbringt zu den Toren dieser Stadt am Tage des Sabbaths und heiligt den Tag des Sabbaths, daß ihr an ihm keine Arbeit tut:',
        25: 'Dann sollen Könige und Oberste, sitzend auf Davids Thron, eingehen zu den Toren dieser Stadt, fahrend auf Streitwagen und auf Rossen, sie und ihre Obersten, der Mann Jehudahs und Jerusalems Bewohner, und diese Stadt soll ewiglich bewohnt werden.',
        26: 'Und sollen kommen die aus den Städten Jehudahs und den Umgebungen Jerusalems, und aus dem Lande Benjamins und aus der Niederung und vom Gebirge und vom Mittag, und hereinbringen Brandopfer und Schlachtopfer und Speiseopfer und Weihrauch, und bringen herein Dankopfer zum Haus Jehovahs.',
        27: 'Und wenn ihr nicht auf Mich hört, daß ihr den Tag des Sabbaths heiligt, und keine Last tragt und damit eingeht zu den Toren Jerusalems am Tage des Sabbaths, so will Ich ein Feuer anzünden in seinen Toren, und es wird die Paläste Jerusalems auffressen, und nicht erlöschen..',
    },
    18: {
        1: 'Das Wort, das an Jirmejahu von Jehovah geschah, sprechend:',
        2: 'Stehe auf und gehe in des Töpfers Haus hinab, und da will Ich dich Meine Worte hören lassen.',
        3: 'Und ich ging in des Töpfers Haus hinab, und siehe, er tat Arbeit auf der Scheibe.',
        4: 'Und das Gefäß, das er machte, verdarb, wie der Ton unter des Töpfers Hand; und er kehrte um und machte ein anderes Gefäß daraus, wie es in des Töpfers Augen recht war zu tun.',
        5: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        6: 'Vermag Ich nicht, wie der Töpfer da, mit euch zu tun, ihr vom Hause Israel? spricht Jehovah. Siehe, wie der Ton ist in des Töpfers Hand, so seid ihr in Meiner Hand, Haus Israel.',
        7: 'Im Augenblicke rede Ich über eine Völkerschaft und über ein Königreich, daß Ich es ausreißen und abbrechen und zerstören will.',
        8: 'Kehret aber diese Völkerschaft von ihrer Bosheit um, dawider Ich geredet, so gereut Mich des Bösen, das Ich ihm zu tun gedachte.',
        9: 'Und im Augenblick rede Ich über eine Völkerschaft und über ein Königreich, daß Ich es bauen und pflanzen will.',
        10: 'Und tut es, was böse in Meinen Augen ist, daß es nicht auf Meine Stimme hört, so reut Mich des Guten, davon Ich sprach ihm wohlzutun.',
        11: 'Und nun sprich doch zu dem Manne Jehudahs und zu Jerusalems Bewohnern, sprechend: Also spricht Jehovah: Siehe, Ich bilde Böses wider euch und denke einen Gedanken über euch. Kehre doch um, ein jeder Mann von seinem bösen Weg, und macht eure Wege und euer Tun gut.',
        12: 'Sie aber sprechen: Vergeblich! Denn nach unseren Gedanken wandeln wir, und tun ein jeder Mann nach der Verstocktheit seines bösen Herzens.',
        13: 'Darum spricht also Jehovah: Fragt doch unter den Völkerschaften: Wer hat solches gehört? Gar Schauerhaftes tut die Jungfrau Israels.',
        14: 'Verläßt auch der Schnee des Libanon vom Felsen Meine Felder? Werden auch die fremden, kalten, rieselnden Wasser ausgerottet?',
        15: 'Dennoch vergißt Meiner Mein Volk und räuchert dem Eitlen; und sie lassen sie straucheln auf ihren Wegen, den ewigen Fußpfaden, zu gehen auf Steigen, einen ungebahnten Weg.',
        16: 'Daß sie ihr Land zur Verwüstung machen, zum Gezische ewiglich, daß jeder, der vorüberzieht, erstaune und den Kopf schüttle.',
        17: 'Wie der Ostwind will Ich sie zerstreuen vor dem Feind. Mit dem Nacken und nicht dem Angesicht will Ich sie ansehen am Tage Not.',
        18: 'Sie aber sprechen: Gehet zu, laßt uns ratschlagen wider Jirmejahu; denn nicht wird das Gesetz dem Priester verlorengehen und dem Weisen der Rat und das Wort dem Propheten. Gehet zu, und laßt uns ihn schlagen mit der Zunge und nicht horchen auf alle seine Worte.',
        19: 'So horche Du auf mich, Jehovah, und höre auf die Stimme meiner Haderer.',
        20: 'Darf man Gutes mit Bösem vergelten, daß meiner Seele sie eine Fallgrube graben? Gedenke, wie ich vor Dir stand Gutes für sie zu reden, um Deinen Grimm von ihnen zurückzuwenden.',
        21: 'Darum gib ihre Söhne dem Hunger hin und reiße sie hin in die Macht des Schwertes, daß ihre Weiber kinderlos und Witwen seien, und ihre Männer in den Tod hingewürgt, ihre Jünglinge werden vom Schwert geschlagen im Streit.',
        22: 'Man höre Geschrei aus ihren Häusern, daß plötzlich Du über sie die Kriegshaufen hereingebracht, weil sie eine Fallgrube gegraben, mich zu fangen, und meinen Füßen hehlings Schlingen gelegt.',
        23: 'Und Du, Jehovah, weißt all ihren Rat wider mich zum Tode. Überdecke nicht ihre Missetat und wische nicht aus ihre Sünde vor Deinem Angesicht, laß sie straucheln vor Deinem Angesicht, zur Zeit Deines Zornes handle mit ihnen.',
    },
    19: {
        1: 'So sprach Jehovah: Gehe hin und kaufe einen Krug vom Töpfer des Geschirrs, und mit etlichen von den Ältesten des Volkes und von den Ältesten der Priester.',
        2: 'Und gehe hinaus nach der Schlucht Ben-Hinnoms, das am Eingang zum Tore der Scherben ist, und rufe aus allda die Worte, die Ich zu dir reden werde,',
        3: 'Und sprich: Höret das Wort Jehovahs, Könige Jehudahs und Bewohner Jerusalems! So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich bringe Böses über diesen Ort, daß jedem, der es hört, seine Ohren gellen werden.',
        4: 'Darum, daß sie Mich verließen und diesen Ort Mir entfremdeten und darin anderen Göttern räucherten, die sie nicht kannten, weder sie noch ihre Väter, noch Jehudahs Könige, und diesen Ort mit dem Blut Unschuldiger erfüllten;',
        5: 'Und dem Baal Opferhöhen bauten, um im Feuer ihre Söhne zu verbrennen als Brandopfer dem Baal, was Ich nicht geboten, noch geredet hatte: und was Mir nicht ins Herz aufgestiegen war.',
        6: 'Darum, seht, es kommen Tage, spricht Jehovah, daß diesen Ort man nicht mehr Topheth und die Schlucht Ben-Hinnom, sondern die Schlucht des Würgens nennen wird.',
        7: 'Und vereiteln will Ich an diesem Ort den Rat Jehudahs und Jerusalems, und sie durch das Schwert vor ihren Feinden fallen lassen, und durch die Hand derer, die nach ihrer Seele trachten und ihren Leichnam zum Fraß dem Gevögel des Himmels und dem Getier der Erde geben.',
        8: 'Und diese Stadt will Ich zur Verwüstung machen und zum Gezisch. Ein jeder, der an ihr vorübergeht, soll ob ihr erstaunen und zischen über alle ihre Schläge,',
        9: 'Und lasse sie essen das Fleisch ihrer Söhne und das Fleisch ihrer Töchter, und der Mann wird das Fleisch seines Genossen essen in der Belagerung und der Beängstigung, mit der sie ihre Feinde und die, so ihnen nach der Seele trachten, beängstigen.',
        10: 'Und du sollst den Krug zerbrechen vor der Männer Augen, die mit dir gegangen sind,',
        11: 'Und sollst zu ihnen sprechen: Also spricht Jehovah der Heerscharen: So zerbreche Ich dieses Volk und diese Stadt, wie einer des Töpfers Gefäß zerbricht, daß man es nicht wieder heilen kann. Und in Topheth werden sie begraben, weil sonst kein Ort mehr ist zu begraben.',
        12: 'So werde Ich, spricht Jehovah, diesem Ort und seinen Bewohnern tun, daß Ich diese Stadt wie Topheth mache.',
        13: 'Und es sollen die Häuser Jerusalems und die Häuser der Könige Jehudahs, die unreinen, werden wie der Ort Topheth, alle die Häuser, auf deren Dächern sie geräuchert allem Heer der Himmel, und Trankopfer gegossen anderen Göttern.',
        14: 'Und Jirmejahu kam von Topheth, wo Jehovah ihn hingesandt zu weissagen, und stand in dem Vorhof von Jehovahs Haus und sprach zu allem Volk:',
        15: 'So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich bringe herein über diese Stadt und über alle ihre Städte all das Böse, das Ich über sie geredet habe, weil sie ihren Nacken verhärten und auf Meine Worte nicht hören.',
    },
    20: {
        1: 'Und Paschchur, Immers Sohn, des Priesters, der zum Fürsten im Hause Jehovahs bestellt war, hörte Jirmejahu solche Worte weissagen.',
        2: 'Und Paschchur schlug den Propheten Jirmejahu und tat ihn in den Block, der im oberen Tore Benjamins, im Hause Jehovahs war.',
        3: 'Und am morgenden Tag geschah, daß Paschchur Jirmejahu aus dem Blocke herausbrachte, und Jirmejahu sprach zu ihm: Nicht Paschchur hat Jehovah deinen Namen genannt, sondern Magor ringsum.',
        4: 'Denn also hat Jehovah gesprochen: Siehe, Ich gebe dich dem Bangen hin, dich und alle deine Liebhaber, und fallen sollen sie durch das Schwert ihrer Feinde, und deine Augen es sehen, und ganz Jehudah gebe Ich in die Hand von Babels König, daß er sie gen Babel wegführe und mit dem Schwert sie schlage;',
        5: 'Und Ich gebe allen Reichtum dieser Stadt und all ihren Erwerb und alle ihre Kostbarkeit, und alle Schätze der Könige Jehudahs gebe Ich in ihrer Feinde Hand, daß sie sie berauben und nehmen und nach Babel bringen.',
        6: 'Und du, Paschchur, und alle Bewohner deines Hauses, ihr werdet in die Gefangenschaft gehen, und nach Babel wirst du kommen und dort sterben und dort begraben werden, du und alle deine Liebhaber, denen du mit Lüge geweissagt hast.',
        7: 'Und Du hast mich beredet, Jehovah, und ich ließ mich bereden, Du hast mich erfaßt und hast mich übermocht. Alltäglich werde ich zum Gelächter. Sie alle verlachen mich.',
        8: 'Denn sooft ich rede, muß ich schreien, Gewalttat und Verwüstung rufen; denn den ganzen Tag ist mir Jehovahs Wort zu Schmach und Schimpf geworden.',
        9: 'Und ich sprach: Ich will Seiner nicht gedenken, nicht mehr in Seinem Namen reden; und es ward in meinem Herzen wie ein brennend Feuer, zurückgehalten in meinem Gebein und ich mühte mich ab, an mich zu halten und ich vermochte es nicht.',
        10: 'Denn vieler Gerede höre ich, Bangen ringsum. Sagt an! wir wollen es ansagen! Alle Männer meines Friedens, Hüter meiner Seite: Vielleicht läßt er sich überreden, daß wir ihn übermögen und unsere Rache an ihm nehmen.',
        11: 'Aber Jehovah ist mit mir, wie ein gewaltiger Held, darum werden, die mich verfolgen, straucheln und nichts vermögen, sehr beschämt werden, daß sie nicht verständig handelten, zu ewiger Schande, die nie vergessen wird.',
        12: 'Und Du, Jehovah der Heerscharen, Der Du prüfst den Gerechten, Du siehst Nieren und Herz, laß Deine Rache mich an ihnen sehen; denn auf Dich habe meinen Hader ich gewälzt.',
        13: 'Singet Jehovah, lobet Jehovah, daß Er die Seele des Dürftigen aus der Hand der Boshaften errettet hat.',
        14: 'Verflucht sei der Tag, an dem ich geboren ward! der Tag, an dem mich meine Mutter gebar, sei nicht gesegnet!',
        15: 'Verflucht der Mann, der meinem Vater die Botschaft brachte und sprach: Dir ist ein Sohn, ein Männliches geboren, und ihn fröhlich machte!',
        16: 'Und selbiger Mann sei wie die Städte, die Jehovah umgekehrt und es nicht bereut hat. Und er höre Geschrei am Morgen und Feldgeschrei zur Mittagszeit!',
        17: 'O, daß man mich nicht tötete vom Mutterschoße an, und meine Mutter mir zum Grabe ward und ewig schwanger ging ihr Mutterschoß.',
        18: 'Wozu ging ich hervor aus dem Mutterschoß, zu sehen Mühsal und Gram und daß in Beschämung meine Tage alle werden!',
    },
    21: {
        1: 'Das Wort, das von Jehovah an Jirmejahu geschah, als König Zidkijahu Paschchur, Malchijahs Sohn, und Zephanjah, den Sohn Maasejahs, den Priester, zu ihm sandte und ihm sagen ließ:',
        2: 'Frage doch nach bei Jehovah für uns; denn Nebuchadrezzar, der König von Babel, streitet wider uns: Vielleicht tut Jehovah uns nach allen Seinen Wundern, daß Er von uns hinaufzöge.',
        3: 'Und Jirmejahu sprach zu ihnen: So sollt ihr zu Zidkijahu sagen:',
        4: 'So spricht Jehovah, der Gott Israels: Siehe, Ich will die Waffen des Krieges umwenden, die ihr in eurer Hand habt, damit ihr streitet wider Babels König und die Chaldäer, die euch belagern außerhalb der Mauer, und Ich will sie versammeln inmitten dieser Stadt.',
        5: 'Und Ich werde streiten wider euch mit ausgereckter Hand, und mit starkem Arm, und mit Zorn und mit Grimm, und mit großer Entrüstung.',
        6: 'Und werde schlagen die Bewohner dieser Stadt, beide, den Menschen und das Vieh, sie sollen sterben durch große Pest.',
        7: 'Und danach gebe Ich, spricht Jehovah, Zidkijahu, Jehudahs König, und seine Knechte und das Volk, und die von der Pestilenz, vom Schwert und vom Hunger verblieben in dieser Stadt, in die Hand von Nebuchadrezzar, Babels König, und in die Hand ihrer Feinde und in die Hand derer, die ihnen nach der Seele trachten, daß er sie schlage mit der Schärfe des Schwertes und sie nicht schone, und kein Mitleid mit ihnen und kein Erbarmen habe.',
        8: 'Und zu diesem Volke sollst du sagen: So spricht Jehovah: Siehe, Ich habe vor euch gegeben den Weg des Lebens und den Weg des Todes.',
        9: 'Wer in dieser Stadt wohnen bleibt, wird sterben durch das Schwert und vom Hunger und von der Pestilenz; wer aber hinausgeht und den Chaldäern zufällt, die euch belagern, wird leben und soll seine Seele zur Beute haben.',
        10: 'Denn Ich setze Mein Angesicht wider diese Stadt zum Bösen und nicht zum Guten, spricht Jehovah; in die Hand von Babels König soll sie gegeben werden, daß er sie mit Feuer verbrenne.',
        11: 'Und ihr vom Hause von Jehudahs König, höret das Wort Jehovahs!',
        12: 'Haus Davids, so spricht Jehovah: Rechtet im Gericht am Morgen und errettet den Ausgeplünderten aus der Hand des Erpressers, daß nicht wie Feuer ausgehe Mein Grimm und brenne, daß niemand lösche ob der Bosheit eures Tuns.',
        13: 'Siehe, Ich bin wider dich, Bewohnerin des Talgrundes, du Fels der Ebene, spricht Jehovah, die ihr sprechet: Wer fährt wider uns herab, und wer mag in unsere Wohnstätten kommen?',
        14: 'Ich aber will euch heimsuchen nach der Frucht eures Tuns, spricht Jehovah, und anzünden ein Feuer in ihrem Wald, daß es auffresse alles rings um sie her.',
    },
    22: {
        1: 'So spricht Jehovah: Gehe hinab in das Haus des Königs von Jehudah und rede allda dieses Wort',
        2: 'Und sprich: Höre das Wort Jehovahs, König Jehudahs, der du auf dem Throne Davids sitzest, du und deine Knechte und dein Volk, die eingehen zu diesen Toren.',
        3: 'So spricht Jehovah: Tuet Recht und Gerechtigkeit, und errettet den Ausgeplünderten aus der Hand des Erpressers, und den Fremdling, die Waise und die Witwe bedrücket nicht, übet nicht Gewalttat und vergießet kein unschuldig Blut an diesem Ort.',
        4: 'So ihr nach diesem Worte tut, dann werden durch dieses Hauses Tore Könige eingehen, die dem David auf seinem Throne sitzen, fahrend auf Streitwagen und auf Rossen, sie und ihre Knechte und ihr Volk.',
        5: 'So aber ihr nicht hört auf diese Worte, schwöre Ich bei Mir, spricht Jehovah, daß dieses Haus zur Verödung werden soll.',
        6: 'Denn also spricht Jehovah über das Haus des Königs von Jehudah: Ein Gilead warst du Mir, das Haupt des Libanons; werde Ich dich nicht zur Wüste setzen, zu Städten, die nicht bewohnt sind?',
        7: 'Und Ich heilige Verderber wider dich, den Mann und seine Waffen, daß sie die Auswahl deiner Zedern umhauen und sie fällen für das Feuer.',
        8: 'Und viele Völkerschaften werden an dieser Stadt vorübergehen und sprechen, der Mann zu seinen Genossen: Warum hat dieser großen Stadt Jehovah so getan?',
        9: 'Und werden sagen: Darum, daß sie den Bund Jehovahs, ihres Gottes, verließen, und andere Götter anbeteten und ihnen dienten.',
        10: 'Weint nicht über den Toten und tragt nicht Leid um ihn, weint vielmehr über den, der hingeht und nicht mehr zurückkehrt und sieht das Land seiner Geburt.',
        11: 'Denn also spricht Jehovah über Schallum, Joschijahus Sohn, Jehudahs König, der an seines Vaters Joschijahus Statt König ist, der von diesem Orte ausgezogen. Er wird nimmer dahin zurückkehren.',
        12: 'Denn an dem Orte, da sie ihn weggeführt, dort wird er sterben und dieses Land nicht mehr sehen.',
        13: 'Wehe dem, der sein Haus baut ohne Gerechtigkeit und seine Söller ohne Recht, der seines Genossen sich bedient umsonst und ihm seinen Arbeitslohn nicht gibt.',
        14: 'Der sagt: Ich will ein Haus mir bauen nach dem Maßstab, und luftige Söller! und Fenster sich aushaut und es mit Zedern täfelt, und mit Bergrot bestreicht.',
        15: 'Solltest du König sein, daß du in Zedern wetteiferst? Dein Vater, aß und trank er nicht auch, und tat Recht und Gerechtigkeit? Dann war es gut mit ihm.',
        16: 'Er rechtete dem Elenden und Dürftigen die Rechtssache, da war es gut. Heißt das nicht Mich erkennen? spricht Jehovah.',
        17: 'Denn deine Augen und dein Herz sind auf nichts aus, als auf deinen Gewinn, und auf unschuldig Blut, zu vergießen, und auf Erpressung und Plackerei, um es zu üben.',
        18: 'Darum, so spricht Jehovah zu Jehojakim, Joschijahus Sohn, dem Könige Jehudahs, sie werden nicht um ihn klagen: O weh, mein Bruder! Und wehe, Schwester! Sie werden nicht um ihn klagen: O weh dem Herrn, und wehe der Majestät!',
        19: 'Mit dem Begräbnis eines Esels wird er begraben, geschleift und hingeworfen au-ßerhalb der Tore Jerusalems.',
        20: 'Steige hinauf auf den Libanon und schreie, gib deine Stimme in Baschan hervor, und schreie von Abarim; denn alle, die dich liebten, sind zerbrochen.',
        21: 'Ich redete zu dir in deiner Behaglichkeit. Du sprachst: Ich will es nicht hören. Dies war dein Weg von deiner Jugend auf, daß du auf Meine Stimme nicht hörtest.',
        22: 'All deine Hirten weidet ab der Wind, und deine Liebhaber gehen in Gefangenschaft. Denn beschämt und zuschanden wirst du dann ob aller deiner Bosheit.',
        23: 'Die du wohntest auf dem Libanon, nistetest in den Zedern, wie wirst du begnadigt werden, wenn Geburtsnöten dich und ein Kreißen ankommen, wie die Gebärende.',
        24: 'Bei Meinem Leben, spricht Jehovah, wärst du auch Chonjahu, der Sohn Jojakims, der König von Jehudah, der Siegelring an Meiner rechten Hand, abreißen müßte Ich dich von da.',
        25: 'Und habe dich in die Hand derer gegeben, die dir nach der Seele trachten, und in die Hand derer, vor deren Angesicht du bangst, und in Nebuchadrezzars Hand, des Königs von Babel, und in die Hand der Chaldäer.',
        26: 'Und Ich schleudere dich und deine Mutter, die dich geboren hat, in ein anderes Land, da ihr nicht seid geboren; und allda sollt ihr sterben.',
        27: 'Und nach dem Lande, wohin sie erheben ihre Seele dahin zurückzukehren, dorthin sollen sie nicht zurückkehren.',
        28: 'Ist dieser Mann Chonjahu denn ein verachtetes, zerschelltes Gebilde, ein Gefäß, an dem man keine Lust hat? Warum schleudern sie ihn und seinen Samen hin und werfen ihn in ein Land, das sie nicht kannten?',
        29: 'O Land, Land, Land! Höre Jehovahs Wort!',
        30: 'So spricht Jehovah: Schreibet diesen Mann als kinderlos, als einen Mann, der kein Gelingen hat in seinen Tagen; denn nicht wird es einem Mann aus seinem Samen gelingen, daß er auf Davids Thron sitze und noch über Jehudah herrsche.',
    },
    23: {
        1: 'Wehe euch Hirten, die ihr die Herde Meiner Weide zerstört und zerstreut! spricht Jehovah.',
        2: 'Darum spricht also Jehovah, der Gott Israels, über die Hirten, die Mein Volk weiden: Ihr habt zerstreut Meine Herde und sie versto-ßen und sie nicht heimgesucht. Siehe, heimsuchen will Ich an euch die Bosheit eures Tuns, spricht Jehovah.',
        3: 'Und Ich will Meiner Herde Überrest zusammenbringen aus allen Ländern, wohin Ich sie verstoßen, und sie zurückbringen zu ihren Hürden, daß sie fruchtbar seien und sich mehren.',
        4: 'Und Ich will Hirten einsetzen über sie, daß sie sie weiden, und sie sich nicht mehr fürchten noch entsetzen und keine vermißt werden, spricht Jehovah.',
        5: 'Siehe, Tage kommen, spricht Jehovah, da Ich dem David einen gerechten Sproß erstehen lasse, daß Er als König regiere und klüglich handle, und tue Recht und Gerechtigkeit auf Erden.',
        6: 'In Seinen Tagen wird Jehudah gerettet werden, und Israel wohnen in Sicherheit, und dies ist Sein Name, womit man Ihn nennen wird: Jehovah, unsere Gerechtigkeit.',
        7: 'Darum siehe, Tage kommen, spricht Jehovah, da man nicht mehr sagen wird: Beim Leben Jehovahs, Der die Söhne Israels heraufgebracht hat aus dem Land Ägypten.',
        8: 'Vielmehr: Beim Leben Jehovahs, Der den Samen des Hauses Israels heraufgeführt und hereingebracht hat aus dem Land gen Mitternacht und aus allen Landen, wohin Ich sie verstoßen, auf daß sie auf ihrem Boden wohnen.',
        9: 'Ob den Propheten bricht mein Herz in meinem Inneren; all meine Gebeine sind durchschauert. Mir ist wie einem trunkenen Mann, und wie dem Menschen, den der Wein hat überkommen, vor Jehovah und vor den Worten Seiner Heiligkeit.',
        10: 'Denn voll von Ehebrechern ist das Land, denn wegen der Verwünschung trauert das Land, verdorren der Wüste Auen; und ihr Lauf ist böse und ihre Macht nicht richtig.',
        11: 'Denn Heuchler sind sowohl Prophet als auch Priester. Auch in Meinem Hause finde Ich ihre Bosheit, spricht Jehovah.',
        12: 'Darum ist ihr Weg für sie wie das Schlüpfrige in der Dunkelheit; sie werden gestoßen und fallen drin; denn Übel bringe Ich über sie im Jahr ihrer Heimsuchung, spricht Jehovah.',
        13: 'Und an Samariens Propheten sah Ich Torheit; sie weissagten durch den Baal und führten in die Irre Mein Volk Israel.',
        14: 'Aber bei den Propheten Jerusalems sah Ich Schauerliches, Ehebruch und Wandel in der Lüge, und sie stärkten der Bösen Hände, auf daß kein Mann von seiner Bosheit umkehre. Wie Sodom sind sie alle Mir geworden und ihre Bewohner wie Gomorrah.',
        15: 'Darum spricht Jehovah der Heerscharen also über die Propheten: Siehe, Ich lasse sie Wermut essen und Wasser der Galle trinken; denn von Jerusalems Propheten geht aus Heuchelei durch das ganze Land.',
        16: 'Also spricht Jehovah der Heerscharen: Höret nicht auf die Worte der Propheten, die euch weissagen; sie machen euch nichtig, sie reden das Gesichte ihres Herzens, nicht aus Jehovahs Mund.',
        17: 'Sie sprechen zu denen, die mich lästern: Jehovah hat geredet: Friede wird mit euch sein; und zu jedem, der in der Verstocktheit seines Herzens wandelt, sprechen sie: Kein Böses kommt über euch.',
        18: 'Denn wer steht im geheimen Rat Jehovahs, daß er sehe und höre Sein Wort? Wer horcht auf Sein Wort und hört darauf?',
        19: 'Siehe, ein Wetter Jehovahs, Grimm geht aus, und ein Wetter wälzt sich daher und kreist über der Ungerechten Haupt.',
        20: 'Der Zorn Jehovahs kehrt nicht zurück bis Er es getan, bis Er erstehen läßt die Beschlüsse Seines Herzens. In den letzten der Tage werdet ihr es mit Einsicht einsehen.',
        21: 'Ich sandte die Propheten nicht und doch liefen sie. Ich redete nicht zu ihnen und doch weissagten sie.',
        22: 'Und wären sie in Meinem geheimen Rat gestanden und ließen sie Mein Volk Meine Worte hören, so brächten sie sie zurück von ihrem bösen Weg und von der Bosheit ihres Tuns.',
        23: 'Bin Ich ein Gott von nahe, spricht Jehovah, und nicht ein Gott von ferne?',
        24: 'Kann sich ein Mann in Verborgenheit verbergen, daß Ich ihn nicht sähe? spricht Jehovah. Erfülle Ich nicht die Himmel und die Erde? spricht Jehovah.',
        25: 'Ich hörte was die Propheten sagen, die in Meinem Namen Lüge weissagen, sie sagen: Ich träumte, ich träumte.',
        26: 'Wie lange noch ist etwas in dem Herzen der Propheten, die Lüge weissagen und weissagen den Betrug ihres Herzens?',
        27: 'Die denken, daß sie Mein Volk Meinen Namen vergessen lassen mit ihren Träumen, die der Mann erzählt seinem Genossen, gleichwie ihre Väter Meinen Namen ob dem Baal vergaßen?',
        28: 'Ist einem Propheten ein Traum geworden, erzähle er den Traum; und bei dem Mein Wort ist, der rede Mein Wort der Wahrheit. Was soll das Stroh beim Getreide? spricht Jehovah.',
        29: 'Ist nicht Mein Wort gleich wie das Feuer? spricht Jehovah, und wie der Hammer, der die Felsenklippe zerschellen läßt?',
        30: 'Darum siehe, spricht Jehovah, Ich bin wider die Propheten, die Meine Worte stehlen, der Mann von seinem Genossen.',
        31: 'Siehe, Ich bin wider die Propheten, spricht Jehovah, die ihre Zunge nehmen und damit einen Spruch sprechen.',
        32: 'Siehe, Ich bin wider die, so Träume der Lüge weissagen, spricht Jehovah, und sie erzählen und Mein Volk mit ihren Lügen und ihrer Leichtfertigkeit irreführen, und Ich habe sie nicht gesandt, noch ihnen geboten und sie nützen keinen Nutzen diesem Volk, spricht Jehovah.',
        33: 'Und wenn dies Volk dich fragt, sei es ein Prophet oder ein Priester, und spricht: Was ist Jehovahs Last? so sage ihnen, was die Last ist: Ich gebe euch dahin! spricht Jehovah.',
        34: 'Und wo der Prophet und der Priester und das Volk spricht: eine Last Jehovahs, den Mann werde Ich samt seinem Haus heimsuchen.',
        35: 'So sollt ihr sprechen, ein Mann zu seinem Genossen und ein Mann zu seinem Bruder: Was hat geantwortet Jehovah, und was hat geredet Jehovah?',
        36: 'Und einer Last Jehovahs sollet ihr nicht mehr gedenken; denn zur Last soll einem Manne sein Wort werden. Und ihr kehret um die Worte des lebendigen Gottes, Jehovahs der Heerscharen, unseres Gottes.',
        37: 'Zu dem Propheten sollst du also sprechen: Was hat Jehovah dir geantwortet und was hat Jehovah geredet?',
        38: 'Und wenn ihr Last Jehovahs sprechet, darum, so spricht Jehovah, darum, daß ihr dies Wort Jehovahs Last gesprochen, und Ich zu euch sandte und euch sagte: Ihr sollt nicht sprechen: Jehovahs Last,',
        39: 'Darum, siehe, so vergesse Ich euch gänzlich und gebe euch dahin und die Stadt, die Ich euch und euren Vätern gegeben, hinweg von Meinem Angesicht.',
        40: 'Und lege ewige Schmach auf euch und ewige Schande, die nicht vergessen wird.',
    },
    24: {
        1: 'Jehovah ließ mich sehen und siehe, da waren zwei Körbe mit Feigen gestellt vor Jehovahs Tempel, nachdem Nebuchadrezzar, Babels König, Jechonjahu, den Sohn Jehojakims, Jehudahs König, und die Obersten Jehudahs, die Werkleute und Schlosser aus Jerusalem weggeführt und nach Babel hineingebracht hatte;',
        2: 'Der eine Korb hatte sehr gute Feigen, wie die Erstlinge der Feigen, und der andere Korb sehr schlechte Feigen, die man vor Schlechtigkeit nicht essen konnte.',
        3: 'Und Jehovah sprach zu mir: Was siehst du, Jirmejahu? Und ich sprach: Feigen. Die guten Feigen sind sehr gut und die schlechten sind sehr schlecht, so daß man sie vor Schlechtigkeit nicht ißt.',
        4: 'Und es geschah an mich das Wort Jehovahs und Er sprach:',
        5: 'So spricht Jehovah, der Gott Israels: Wie diese guten Feigen, so will Ich die Weggeführten Jehudahs zum Guten erkennen, die Ich aus diesem Orte nach der Chaldäer Land habe gesendet;',
        6: 'Und will Mein Auge auf sie richten zum Guten und sie in dieses Land zurückbringen, und sie aufbauen und nicht umreißen, und sie pflanzen und nicht ausrotten.',
        7: 'Und Ich will ihnen ein Herz geben, daß sie Mich kennen, daß Ich Jehovah bin, und sie sollen Mein Volk werden, und Ich werde ihnen Gott sein, wenn sie von ganzem Herzen zu Mir zurückkehren werden.',
        8: 'Aber wie die schlechten Feigen, die man nicht ißt vor Schlechtigkeit, fürwahr, so spricht Jehovah, also will Ich geben Zidkijahu, Jehudahs König, und seine Obersten und den Überrest Jerusalems, der verblieb in diesem Land, und die, so im Lande Ägypten wohnen.',
        9: 'Und will sie geben zur Aufregung, zum Übel für alle Reiche der Erde, zur Schmach und zum Sprichwort, zur Stachelrede und zum Fluch an allen Orten, dahin Ich sie verstoße;',
        10: 'Und Ich sende unter sie das Schwert, den Hunger und die Pestilenz, bis sie gar aus sind von dem Boden, den Ich ihnen und ihren Vätern gegeben hatte.',
    },
    25: {
        1: 'Das Wort, welches geschah an Jirmejahu über alles Volk Jehudahs im vierten Jahre Jehojakims, des Sohnes Joschijahus, König von Judah, welches ist das erste Jahr Nebuchadrezzars, des Königs von Babel;',
        2: 'Das Jirmejahu, der Prophet, redete zu allem Volk Jehudahs und zu allen Bewohnern Jerusalems, sprechend:',
        3: 'Von dem dreizehnten Jahre Joschijahus, des Sohnes Amons, König von Judah an und bis auf diesen Tag, diese dreiundzwanzig Jahre her ist das Wort Jehovahs an mich geschehen, und ich redete früh aufstehend und redend, und ihr habt nicht gehört.',
        4: 'Und Jehovah sandte an euch alle seine Knechte, die Propheten, früh aufstehend und sendend, ihr aber habt sie nicht gehört, und euer Ohr nicht geneigt, auf daß ihr hörtet.',
        5: 'Sie sprachen: Kehret doch zurück, jeder Mann von seinem bösen Wege und von der Bosheit eurer Taten, und ihr sollt auf dem Boden, den Jehovah euch und euren Vätern gegeben hat, von Ewigkeit und bis zu Ewigkeit wohnen.',
        6: 'Und gehet keinen anderen Göttern nach, ihnen zu dienen und sie anzubeten, daß ihr Mich nicht reizet durch eurer Hände Tun, euch Böses zu tun.',
        7: 'Ihr aber hörtet nicht auf Mich, spricht Jehovah, daß ihr Mich reiztet durch eurer Hände Tun, euch Böses zu tun.',
        8: 'Darum, so spricht Jehovah der Heerscharen: Weil ihr nicht auf Meine Worte hörtet,',
        9: 'Siehe, so sende Ich aus und nehme alle Familien der Mitternacht, spricht Jehovah, und Nebuchadrezzar, Babels König, Meinen Knecht, und bringe sie herein wider dieses Land und wider seine Bewohner, und wider alle diese Völkerschaften ringsumher; daß Ich sie verbanne und setze sie zur Wüstenei und zum Gezisch und zu ewigen Verödungen.',
        10: 'Und Ich will von ihnen vergehen lassen die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut, die Stimme der Mühle und das Licht der Lampe.',
        11: 'Und dieses ganze Land wird zur Öde und zur Wüstenei werden; und sollen diese Völkerschaften dem König Babels siebzig Jahre dienen.',
        12: 'Und es wird geschehen, wenn siebzig Jahre voll sind, daß Ich heimsuche an Babels König und an jener Völkerschaft, spricht Jehovah, ihre Missetat und an der Chaldäer Land, und Ich setze sie zu ewigen Wüsteneien.',
        13: 'Und Ich bringe über dieses Land herein alle Meine Worte, die Ich über dasselbe geredet, alles, was in diesem Buch geschrieben ist, das Jirmejahu über alle Völkerschaften geweissagt hat.',
        14: 'Denn die vielen Völkerschaften und großen Könige sollen sie dienstbar machen, auch sie, und nach ihrem Werke und ihrer Hände Tun vergelte Ich ihnen.',
        15: 'Denn also spricht zu mir Jehovah, der Gott Israels: Nimm diesen Becher Wein des Grimmes aus Meiner Hand, und lasse daraus trinken alle Völkerschaften, zu denen Ich dich senden werde;',
        16: 'Auf daß sie trinken und schwanken und rasen vor dem Schwerte, das Ich sende unter sie.',
        17: 'Und ich nahm den Becher aus der Hand Jehovahs und ließ trinken alle Völkerschaften, zu denen mich Jehovah sendete.',
        18: 'Jerusalem und Jehudahs Städte, und ihre Könige und ihre Obersten, sie zu geben zur Verödung, zur Wüstenei, zum Gezisch und zum Fluch, wie an diesem Tag;',
        19: 'Den Pharao, Ägyptens König, und seine Knechte und seine Obersten und all sein Volk:',
        20: 'Und alle gegen Abend und alle Könige des Landes Uz, und alle Könige des Landes der Philister, und Aschkalon und Gazah und Ekron und Aschdods Überrest;',
        21: 'Edom und Moab und Ammons Söhne;',
        22: 'Und alle Könige von Zor und alle Könige von Zidon, und die Könige der Inseln, die jenseits des Meeres sind;',
        23: 'Dedan und Thema und Bus und alle, welche die Ecke stutzen;',
        24: 'Und alle Könige Arabiens und alle Könige des Abends, die in der Wüste wohnen.',
        25: 'Und alle Könige von Simri und alle Könige von Elam und alle Könige Madais;',
        26: 'Und alle Könige von Mitternacht, die nahen und die fernen, den Mann zu seinem Bruder, und alle Königreiche der Erde, die auf der Oberfläche des Bodens sind, und nach ihnen soll König Scheschach trinken.',
        27: 'Und sprich zu ihnen: So spricht Jehovah der Heerscharen, der Gott Israels: Trinket und werdet trunken, und speiet und fallet und stehet nicht auf vor dem Schwerte, das Ich sende unter euch.',
        28: 'Und wenn geschieht, daß sie sich weigern, den Becher aus deiner Hand zu nehmen, zu trinken, so sprich zu ihnen: Also spricht Jehovah der Heerscharen: Ihr sollt gewißlich trinken.',
        29: 'Denn siehe, der Stadt, über der Mein Name genannt wird, fange Ich an, Übles anzutun. Und ihr, ihr wollt straflos sein? Ihr sollt nicht straflos sein! Denn Ich rufe ein Schwert über alle Bewohner der Erde, spricht Jehovah der Heerscharen.',
        30: 'Und du, weissage über sie alle diese Worte und sprich zu ihnen: Jehovah brüllt aus der Höhe und gibt Seine Stimme hervor aus der Wohnstätte Seiner Heiligkeit; Er brüllt wider Seinen Wohnort, antwortet im Kelterlied wie die Keltertreter, allen, so auf Erden wohnen.',
        31: 'Es kommt ein Tosen bis ans Ende der Erde; denn im Hader ist Jehovah mit den Völkerschaften. Er richtet alles Fleisch. Die Ungerechten - Er gibt sie dem Schwerte, spricht Jehovah.',
        32: 'So spricht Jehovah der Heerscharen: Siehe, Böses zieht aus von Völkerschaft zu Völkerschaft, ein großes Wetter wird erweckt von der Erde Seiten.',
        33: 'Und die Erschlagenen Jehovahs sind an jenem Tag von einem Ende der Erde bis zum anderen Ende der Erde; sie werden nicht beklagt, noch gesammelt, noch begraben, sie werden zu Dünger auf der Fläche des Bodens.',
        34: 'Heulet, ihr Hirten und schreiet, wälzet euch umher ihr Stattlichen der Herde, denn eure Tage zum Schlachten sind erfüllt, und Ich zerschelle euch und ihr fallet wie ein köstliches Gefäß.',
        35: 'Und die Zuflucht vergeht für die Hirten, und das Entkommen für die Stattlichen der Herde.',
        36: 'Die Stimme des Schreiens der Hirten! und ein Heulen von den Stattlichen der Herde; denn ihre Weide hat verheert Jehovah.',
        37: 'Und von der Glut des Zornes Jehovahs gehen unter die Hürden des Friedens.',
        38: 'Verlassen hat Er Seine Hütte wie der junge Löwe; denn eine Wüstenei ist ihr Land geworden vor der Glut des Bedrückers und vor der Glut seines Zornes.',
    },
    26: {
        1: 'Im Anfang der Regierung Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, geschah von Jehovah dieses Wort, sprechend:',
        2: 'So spricht Jehovah: Stehe in den Vorhof von Jehovahs Haus und rede zu allen Städten Jehudahs, die hereinkommen, im Haus Jehovahs anzubeten, all die Worte, die Ich dir gebiete, zu ihnen zu reden, und sollst kein Wort davontun.',
        3: 'Vielleicht hören sie darauf und der Mann kehrt von seinem bösen Wege zurück, daß Mich des Bösen gereue, das Ich dachte ihnen zu tun, ob der Bosheit ihrer Taten.',
        4: 'Und sprich zu ihnen: So spricht Jehovah: Wenn ihr nicht auf Mich hört, so daß ihr wandelt in Meinem Gesetz, das Ich vor euch gegeben habe;',
        5: 'So daß ihr hört auf die Worte Meiner Knechte, der Propheten, die Ich an euch sandte, früh aufstehend und sendend, aber ihr hörtet nicht.',
        6: 'So gebe Ich dieses Haus dahin wie Schiloh, und diese Stadt gebe Ich zum Fluch allen Völkerschaften auf der Erde.',
        7: 'Und die Priester und die Propheten und alles Volk hörten Jirmejahu diese Worte im Hause Jehovahs reden.',
        8: 'Und es geschah, wie Jirmejahu vollendet hatte, alles zu reden, was ihm Jehovah vor dem ganzen Volk zu reden geboten hatte, da faßten ihn an die Priester und die Propheten und alles Volk und sprachen: Du mußt des Todes sterben.',
        9: 'Warum weissagst du im Namen Jehovahs und sprichst: Wie Schiloh soll dies Haus werden, und diese Stadt soll verödet werden, so daß niemand darin wohne? Und alles Volk kam zusammen im Hause Jehovahs wider Jirmejahu.',
        10: 'Und als die Obersten Jehudahs hörten diese Dinge, kamen sie herauf vom Königshause zum Haus Jehovahs und setzen sich am Eingang des neuen Tores Jehovahs.',
        11: 'Und die Priester und die Propheten sprachen zu den Obersten und zu dem ganzen Volk und sagten: Ein Gericht des Todes für diesen Mann; denn er hat wider diese Stadt geweissagt, wie ihr mit euren Ohren hörtet!',
        12: 'Und Jirmejahu sprach zu all den Obersten und zu allem Volk und sagte: Jehovah hat mich gesandt über dieses Haus und über diese Stadt alle die Worte zu weissagen, die ihr gehört habt.',
        13: 'Und nun macht eure Wege gut und eure Taten und hört auf die Stimme Jehovahs eures Gottes, daß Jehovah gereue des Bösen, das Er wider euch geredet hat.',
        14: 'Und siehe, ich bin in eurer Hand, tut mit mir, wie es gut und recht in euren Augen ist.',
        15: 'Nur sollt ihr wissen, daß ihr, wenn ihr mich tötet, unschuldig Blut bringt über euch und über diese Stadt, und über die, so in ihr wohnen; denn in Wahrheit hat Jehovah mich zu euch gesandt, in euren Ohren zu reden alle diese Worte.',
        16: 'Und es sprachen die Obersten und das ganze Volk zu den Priestern und zu den Propheten: Für den Mann da gibt es kein Gericht des Todes; denn im Namen Jehovahs unseres Gottes, hat er zu uns geredet.',
        17: 'Und es standen Männer von den Ältesten des Landes auf und sprachen zur ganzen Versammlung des Volkes und sagten:',
        18: 'Michajah, der Moraschthite, war ein Prophet in den Tagen Chiskijahus, des Königs von Jehudah, und sprach zu allem Volk Jehudahs und sagte: So spricht Jehovah der Heerscharen: Zijon soll als Feld gepflügt und Jerusalem zu Trümmerhaufen und der Berg des Hauses zu Opferhöhen des Waldes werden.',
        19: 'Hat Chiskijahu, Jehudahs König, und ganz Jehudah ihn getötet? Hat er nicht Jehovah gefürchtet und angefleht das Angesicht Jehovahs? Und es reute Jehovah wegen des Bösen, das Er wider sie geredet. Wir aber tun großes Übel wider unsere Seelen.',
        20: 'Und es war auch ein Mann, der weissagte im Namen Jehovahs, Urijahu, Schemajahus Sohn, aus Kirjath-Jearim, und er weissagte wider diese Stadt und wider dieses Land nach allen Worten Jirmejahus.',
        21: 'Und König Jehojakim und alle seine Mächtigen und alle Obersten hörten seine Worte, und der König suchte ihn zu töten, und Urijahu hörte es und fürchtete sich und entwich, und kam nach Ägypten.',
        22: 'Und König Jehojakim sandte Männer nach Ägypten, Elnathan, Achbors Sohn, und Männer mit ihm nach Ägypten.',
        23: 'Und sie brachten Urijahu heraus aus Ägypten und brachten ihn herein zum König Jehojakim und er schlug ihn mit dem Schwerte, und warf seinen Leichnam hin bei den Gräbern der Söhne des Volkes.',
        24: 'Doch die Hand Achikams, des Sohnes Schaphans, war mit Jirmejahu, daß man ihn nicht in die Hand des Volkes gab, um ihn zu töten.',
    },
    27: {
        1: 'Im Anfang der Regierung Jehojakims, des Sohnes Joschijahus, König von Jehudah, geschah dies Wort an Jirmejahu von Jehovah, sprechend:',
        2: 'So spricht Jehovah zu mir: Mache dir Bande und Jochhölzer und gib sie auf deinen Hals.',
        3: 'Und sende sie an den König Edoms und an den König Moabs und an den König der Söhne Ammons und an den König Zors und an den König Zidons durch die Hand der Boten, die gen Jerusalem zu Zidkijahu, Jehudahs König, kamen.',
        4: 'Und gebiete ihnen an ihre Herren, zu sagen: So spricht Jehovah der Heerscharen, der Gott Israels: So sollt ihr euren Herren sagen:',
        5: 'Ich habe gemacht die Erde und den Menschen und das Vieh, die auf den Angesichten der Erde sind, durch Meine große Kraft und Meinen ausgestreckten Arm, und gebe sie, wem es recht in Meinen Augen ist.',
        6: 'Und nun habe Ich alle diese Länder in die Hand Nebuchadnezzars, des Königs von Babel, Meines Knechtes, gegeben; und auch das wilde Tier des Feldes habe Ich ihm gegeben, daß sie ihm dienen.',
        7: 'Und alle Völkerschaften sollen dienen ihm und seinem Sohn, und seines Sohnes Sohn, bis auch seines Landes Zeit kommt, und viele Völkerschaften und große Könige es dienstbar machen.',
        8: 'Und soll geschehen, daß die Völkerschaft und das Königreich, das ihm, Nebuchadnezzar, Babels König, nicht dienen und seinen Hals nicht in das Joch des Königs von Babel geben will, Ich solche Völkerschaft mit Schwert und mit Hunger und mit Pest heimsuche, spricht Jehovah, bis daß Ich es durch seine Hand umkommen lasse.',
        9: 'Und ihr sollt nicht hören auf eure Propheten und auf eure Wahrsager und auf eure Träume und auf eure Wolkendeuter und auf eure Zauberer, die zu euch sprechen und sagen: Ihr sollt Babels König nicht dienen!',
        10: 'Denn Lüge weissagen sie euch, von eurem Boden euch zu entfernen, und daß Ich euch verstoße und ihr vergeht.',
        11: 'Aber die Völkerschaft, die ihren Hals hineingibt in das Joch von Babels König und ihm dient, das lasse Ich auf seinem Boden, spricht Jehovah, daß es ihn baue und darauf wohne.',
        12: 'Und zu Zidkijah, Jehudahs König, habe ich geredet, nach allen diesen Worten und gesagt: Bringt euren Hals hinein in das Joch von Babels König, und dient ihm und seinem Volk, auf daß ihr lebt!',
        13: 'Warum doch wollt ihr sterben, du und dein Volk durch das Schwert, durch Hunger und durch Pest, wie Jehovah geredet hat über die Völkerschaft, die Babels König nicht dienen will.',
        14: 'Und hört nicht auf die Worte der Propheten, die zu euch sprechen und sagen: Dient Babels König nicht; denn Lüge weissagen sie euch.',
        15: 'Denn Ich habe sie nicht gesendet, spricht Jehovah, und Lügen weissagen sie in Meinem Namen; auf daß Ich euch verstoße und ihr vergeht, ihr und die Propheten, die euch weissagten.',
        16: 'Und zu den Priestern und zu all diesem Volk redete ich und sprach: So spricht Jehovah, hört nicht auf die Worte eurer Propheten, die euch weissagen und sprechen: Siehe, die Gefäße von Jehovahs Haus werden jetzt in Eile von Babel zurückgebracht; denn Lüge weissagen sie euch.',
        17: 'Hört nicht auf sie, dient dem König Babels, auf daß ihr lebet. Warum soll diese Stadt zur Öde werden?',
        18: 'Und wenn sie Propheten sind und Jehovahs Wort bei ihnen ist, so laßt sie doch bei Jehovah der Heerscharen vermitteln, daß die Gefäße, die noch übrig sind im Haus Jehovahs und im Haus des Königs von Jehudah und in Jerusalem, nicht auch nach Babel kommen!',
        19: 'Denn also spricht Jehovah der Heerscharen von den Säulen und von dem Meer und von den Gestellen und von den übrigen Gefäßen, die noch übriggeblieben sind in dieser Stadt,',
        20: 'Die Nebuchadnezzar, Babels König, nicht von Jerusalem nach Babel genommen hat, da er Jechonjah, Jehojakims Sohn, Jehudahs König mit allen Vornehmen Jehudahs und Jerusalems nach Babel wegführte.',
        21: 'Denn so spricht Jehovah der Heerscharen, der Gott Israels, über die Gefäße, die im Haus Jehovahs und im Haus des Königs von Jehudah und in Jerusalem übriggeblieben sind:',
        22: 'Nach Babel sollen sie gebracht werden und allda sein bis zu dem Tag, da Ich sie heimsuche, spricht Jehovah, und Ich sie heraufbringe und an diesen Ort zurückbringe.',
    },
    28: {
        1: 'Und es geschah im selbigen Jahr im Anfang der Regierung Zidkijahs, König von Jehudah, im vierten Jahr im fünften Monat, daß Chananjah, der Sohn Assurs, der Prophet, aus Gibeon zu mir sprach im Haus Jehovahs vor den Augen der Priester und vor allem Volke sprechend:',
        2: 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Zerbrochen habe Ich das Joch von Babels König.',
        3: 'Noch zwei Jahre der Tage, so bringe Ich zurück an diesen Ort alle Gefäße von Jehovahs Haus, die Nebuchadnezzar, Babels König, von diesem Orte genommen und nach Babel gebracht hat.',
        4: 'Und den Jechonjah, den Sohn Jehojakims, König von Jehudah und alle die Weggeführten Jehudahs, die nach Babel gekommen, bringe Ich zurück an diesen Ort, spricht Jehovah; denn Ich zerbreche das Joch des Königs von Babel.',
        5: 'Und Jirmejahu, der Prophet, sprach zu Chananjah, dem Propheten, vor den Augen der Priester und vor den Augen des ganzen Volkes, so im Haus Jehovahs standen;',
        6: 'Und Jirmejahu, der Prophet, sprach: Amen! So tue Jehovah! Jehovah bestätige deine Worte, die du geweissagt hast, daß Er die Gefäße des Hauses Jehovahs und alle die Weggeführten aus Babel nach diesem Ort zurückbringe.',
        7: 'Nur höre doch dies Wort, das ich in deine Ohren und in die Ohren des ganzen Volkes rede:',
        8: 'Die Propheten, die vor mir und vor dir waren, von der Urzeit her und haben über viele Länder und über große Königreiche geweissagt von Streit und von Bösem und von Pestilenz,',
        9: 'Der Prophet, der zum Frieden weissagt, wenn das Wort des Propheten kommt, wird der Prophet bezeugt, daß ihn Jehovah gesandt hat in Wahrheit.',
        10: 'Und Chananjah, der Prophet, nahm vom Nacken Jirmejahus, des Propheten, das Jochstück ab und zerbrach es.',
        11: 'Und Chananjah sprach vor den Augen des ganzen Volkes und sagte: So spricht Jehovah: Also zerbreche Ich das Joch Nebuchadnezzars, des Königs von Babel, in noch zwei Jahren der Tage von dem Halse aller Völkerschaften. Und der Prophet Jirmejahu ging seines Weges.',
        12: 'Und es geschah das Wort Jehovahs an Jirmejahu, nachdem Chananjah, der Prophet, das Jochstück vom Nacken Jirmejahus, des Propheten, zerbrochen und sprach:',
        13: 'Gehe und sprich zu Chananjah und sage: So spricht Jehovah: Die Jochstücke von Holz hast du zerbrochen; so mache nun an ihrer Statt Jochstücke von Eisen.',
        14: 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Ein Joch von Eisen gebe Ich auf den Hals all dieser Völkerschaften, Nebuchadnezzar, dem Könige von Babel, zu dienen, und sie müssen dienen ihm, und auch das wilde Tier des Feldes habe Ich ihm gegeben.',
        15: 'Und Jirmejahu, der Prophet, sprach zu Chananjah, dem Propheten: Höre doch, Chananjah, Jehovah hat dich nicht gesandt, und du hast dieses Volk auf Lügen vertrauen lassen.',
        16: 'Darum spricht Jehovah also: Siehe, Ich sende dich fort von den Angesichten des Bodens; in diesem Jahre stirbst du; denn Abfall von Jehovah hast du geredet.',
        17: 'Und Chananjah, der Prophet, starb desselbigen Jahres im siebten Monat.',
    },
    29: {
        1: 'Und dies sind die Worte des Schreibens, das Jirmejahu, der Prophet, von Jerusalem sandte an die übergebliebenen Ältesten der Weggeführten und an die Priester und an die Propheten und an alles Volk, das Nebuchadnezzar von Jerusalem nach Babel wegführte;',
        2: 'Nachdem Jechonjah, der König, und die Gebieterin und die Hofbeamten, die Obersten Judahs und Jerusalems, und der Werkmann und der Schlosser von Jerusalem ausgezogen waren,',
        3: 'Durch die Hand Eleasahs, des Sohnes Schaphans, und Gemarjahs, des Sohnes Chilkijahs, die Zidkijah, der König Jehudahs, an Nebuchadnezzar, Babels König, nach Babel gesandt hatte, und sprach:',
        4: 'So spricht Jehovah der Heerscharen, der Gott Israels, zu allen Weggeführten, die Ich von Jerusalem nach Babel weggeführt habe:',
        5: 'Baut Häuser und wohnet und pflanzet Gärten und esset ihre Frucht.',
        6: 'Nehmt Weiber und zeugt Söhne und Töchter, und nehmt euren Söhnen Weiber und eure Töchter gebet Männern, daß Söhne und Töchter sie gebären, und ihr euch allda mehret und nicht weniger werdet.',
        7: 'Und sucht nach dem Frieden der Stadt, dahin Ich euch wegführte, und betet für sie zu Jehovah: denn in ihrem Frieden wird auch für euch Friede werden.',
        8: 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Lasset euch nicht verführen von Propheten in eurer Mitte, noch von euren Wahrsagern, und hört nicht auf eure Träume, die ihr euch träumen lasset.',
        9: 'Denn mit Lüge weissagen sie euch in Meinem Namen, Ich habe sie nicht gesandt, spricht Jehovah.',
        10: 'Denn also spricht Jehovah: Wenn siebzig Jahre voll sind für Babel, werde Ich euch heimsuchen und über euch Mein gutes Wort bestätigen, daß Ich euch zurückbringe an diesen Ort.',
        11: 'Denn Ich weiß die Gedanken, die Ich denke über euch, spricht Jehovah, Gedanken des Friedens und nicht zum Bösen, euch zu geben eine Zukunft und Hoffnung.',
        12: 'Und rufet ihr Mich und wandelt und betet zu Mir, so werde Ich auf euch hören.',
        13: 'Und ihr werdet Mich suchen und finden, wenn ihr nach Mir sucht von ganzem Herzen.',
        14: 'Und Ich werde Mich von euch finden lassen, spricht Jehovah, und werde zurückwenden eure Gefangenschaft und euch zusammenbringen aus allen Völkerschaften und aus allen Orten, wohin Ich euch verstoßen habe, spricht Jehovah. Und Ich will euch zurückbringen an den Ort, von wo Ich euch weggeführt habe.',
        15: 'Wenn ihr sagt: Jehovah hat uns in Babel Propheten auferstehen lassen:',
        16: 'Nun so sprach Jehovah zu dem König, der auf dem Throne Davids sitzt, und zu allem Volk, das in dieser Stadt wohnt, euren Brüdern, die nicht in die Wegführung mit euch sind ausgezogen;',
        17: 'So spricht Jehovah der Heerscharen: Siehe, Ich sende gegen sie das Schwert, den Hunger und die Pest, und gebe sie wie die herben Feigen, die man nicht essen mag vor Schlechtigkeit.',
        18: 'Und setze hinter ihnen nach mit dem Schwert, mit Hunger und mit Pest, und mache sie zum Grauen für alle Königreiche der Erde, zur Verwünschung und zur Verwüstung und zum Gezisch und zur Schmach für alle Völkerschaften, wohin Ich sie verstoßen habe.',
        19: 'Dafür, daß sie auf Meine Worte nicht gehört, spricht Jehovah, während Ich zu ihnen sandte Meine Knechte, die Propheten, früh aufstehend und sendend, aber ihr hörtet nicht, spricht Jehovah.',
        20: 'So hört denn ihr das Wort Jehovahs, ihr alle, die ihr weggeführt worden, die Ich von Jerusalem gen Babel habe gesandt.',
        21: 'So spricht Jehovah der Heerscharen, der Gott Israels, wider Achab, den Sohn Kolajahs, und wider Zidkijahu, Maasejahs Sohn, die euch in Meinem Namen Lüge weissagten: Siehe, Ich gebe sie in die Hand Nebuchadrezzars, des Königs von Babel, und er schlägt sie vor euren Augen.',
        22: 'Und wird genommen werden von ihnen her ein Fluch bei allen Weggeführten Jehudahs in Babel, sprechend: Jehovah mache dich wie Zidkijahu und wie Achab, die Babels König am Feuer gebraten.',
        23: 'Weil sie Torheit in Israel taten und Ehebruch trieben mit den Weibern ihrer Genossen, und in Meinem Namen das Wort der Lüge redeten, welches Ich ihnen nicht geboten hatte. Und Ich, Ich weiß es und bin Zeuge, spricht Jehovah.',
        24: 'Und sprich zu Schemajahu aus Nechalam, sprechend:',
        25: 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Darum, daß du unter deinem Namen Briefe an alles Volk, das in Jerusalem ist, und an Zephanjah, Maasejahs Sohn, den Priester, und an alle Priester gesandt hast und gesagt:',
        26: 'Jehovah hat dich zum Priester gegeben anstatt des Priesters Jehojada, auf daß ihr sollt Aufseher sein des Hauses Jehovahs, über jeden Mann, der wahnsinnig ist und weissagen will, daß du ihn in Block und Stock legest.',
        27: 'Und nun, warum hast du den Jirmejahu von Anathoth nicht bedroht, der euch weissagt?',
        28: 'So hat er denn an uns nach Babel gesendet und gesagt: Es ist noch lange. Bauet Häuser und wohnet und pflanzet Gärten und esset ihre Frucht!',
        29: 'Und Zephanjah, der Priester, las diesen Brief vor den Ohren Jirmejahus, des Propheten.',
        30: 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:',
        31: 'Sende an alle Weggeführten, sprechend: So spricht Jehovah zu Schemajah von Nechalam: Weil Schemajah euch geweissagt und Ich ihn nicht gesendet habe; und er euch auf Lüge vertrauen läßt,',
        32: 'Darum spricht also Jehovah: Siehe, Ich suche heim Schemajah aus Nechalam und seinen Samen. Kein Mann sei ihm, der in der Mitte dieses Volkes wohne, und er soll nicht das Gute sehen, das Ich Meinem Volke tue, spricht Jehovah, weil er zum Abfall von Jehovah hat geredet.',
    },
    30: {
        1: 'Das Wort, das von Jehovah an Jirmejahu geschah, sprechend:',
        2: 'So spricht Jehovah, der Gott Israels, und sagt: Schreibe dir alle Worte, die Ich zu dir geredet habe, in ein Buch.',
        3: 'Denn siehe, Tage kommen, spricht Jehovah, daß Ich die Gefangenschaft Meines Volkes Israel und Jehudah zurückwende, spricht Jehovah, und sie zurückbringe in das Land, das ihren Vätern Ich gegeben hatte, und sie als Erbe es besitzen.',
        4: 'Und dies sind die Worte, die Jehovah hat geredet an Israel und Jehudah:',
        5: 'Denn also spricht Jehovah: Die Stimme des Erzitterns hörten wir, des Schauers, und keinen Frieden.',
        6: 'Fragt doch und sehet, ob das Männliche gebären kann! Warum sehe Ich jeglichen Mann seine Hände an seinen Hüften, wie ein Gebärerin, und alle Angesichte in Blässe verwandelt?',
        7: 'Wehe! Denn groß ist dieser Tag, keiner wie er! Und eine Zeit der Drangsal ist er für Jakob. Aber er soll daraus gerettet werden.',
        8: 'Und an selbigem Tage soll geschehen, spricht Jehovah der Heerscharen, daß Ich sein Joch von deinem Hals zerbreche und abreiße deine Bande und Fremde nicht mehr damit ihn dienstbar machen.',
        9: 'Und dienen sollen sie Jehovah, ihrem Gott, und David, ihrem König, den Ich ihnen erstehen lasse.',
        10: 'Du aber fürchte dich nicht, Mein Knecht Jakob, spricht Jehovah, und entsetze dich nicht, Israel; denn siehe Ich rette dich aus der Ferne, und deinen Samen aus dem Lande ihrer Gefangenschaft, daß Jakob wiederkehre, ruhig und sorglos sei, und niemand ihn aufscheuche.',
        11: 'Denn Ich werde mit dir sein, spricht Jehovah, dich zu retten; wenn Ich Vollendung mache mit allen Völkerschaften, unter die Ich dich zerstreute, will Ich nur mit dir keine Vollendung machen, sondern dich züchtigen nach Recht und dich nicht ungestraft lassen.',
        12: 'Denn also spricht Jehovah: Verzweifelt ist dein Bruch, schmerzhaft dein Schlag.',
        13: 'Niemand rechtet deine Rechtssache; Heilmittel zum Aufkommen hast du nicht.',
        14: 'Alle deine Liebhaber vergessen dich, sie fragen nicht nach dir. Mit einem Schlage des Feindes schlug Ich dich in grausamer Züchtigung ob der Menge deiner Missetat, zahlreich sind deine Sünden.',
        15: 'Was schreist du über deinen Bruch, daß verzweifelt dein Schmerz ist? Ob der Menge deiner Missetat, weil deine Sünden zahlreich sind, habe Ich dir das getan.',
        16: 'Darum werden alle, die dich auffraßen, aufgefressen, und alle deine Dränger, sie alle ziehen in die Gefangenschaft, und die dich plünderten werden zur Plünderung, und alle, die dich beraubten, gebe Ich dem Raube hin.',
        17: 'Dir aber bringe Ich Genesung herauf, und heile dich von deinen Schlägen, spricht Jehovah. Denn die Verstoßene nannte man dich, Zijon, nach der niemand fragt.',
        18: 'So spricht Jehovah: Siehe, Ich wende die Gefangenschaft der Zelte Jakobs zurück, und seiner Wohnungen erbarme Ich Mich, und aufgebaut wird die Stadt auf ihrem Schutthaufen und der Palast wird nach seiner Weise bewohnt werden.',
        19: 'Und von ihnen aus geht Bekenntnis und die Stimme der Spielenden, und Ich will sie mehren und nicht sollen sie sich mindern, und Ich verherrliche sie und sie sollen sich nicht verringern.',
        20: 'Und seine Söhne sollen sein wie vordem, und seine Gemeinde soll vor Mir befestigt werden, und heimsuchen werde Ich all seine Unterdrücker.',
        21: 'Und sein Stattlicher wird aus ihm sein, und sein Herrscher geht aus seiner Mitte hervor, und Ich lasse ihn nahen, und er wird zu Mir herzutreten; denn wer ist es, der sein Herz verbürgt, herzutreten zu Mir, spricht Jehovah.',
        22: 'Und ihr sollt Mein Volk sein, und Ich will euch Gott sein.',
        23: 'Siehe ein Wetter Jehovahs, ein Grimm geht aus, ein Wetter rottet sich zusammen und kreist über dem Haupt der Ungerechten.',
        24: 'Die Glut des Zornes Jehovahs geht nicht zurück, bis Er es getan und die Beschlüsse Seines Herzens erstehen läßt. In den letzten Tagen werdet ihr es einsehen.',
    },
    31: {
        1: 'Zur selben Zeit, spricht Jehovah, will Ich allen Familien Israels Gott sein und sie sollen Mir zum Volk sein.',
        2: 'So spricht Jehovah: Gnade hat in der Wüste das Volk, der Rest vom Schwert, gefunden, da Er hinging, ihm, Israel, Ruhe zu verschaffen.',
        3: 'Von Ferne ist Jehovah mir erschienen: Und mit ewiger Liebe habe Ich dich geliebt, darum habe Ich dich hergezogen aus Barmherzigkeit.',
        4: 'Ich baue dich noch, und du sollst erbaut werden, Jungfrau Israel, daß du dich schmückst mit deinen Pauken und im Reigen der Spielenden ausziehst.',
        5: 'Weinberge sollst du noch pflanzen auf den Bergen Samariens, und die Pflanzer, die sie pflanzten, sollen sie genießen.',
        6: 'Denn der Tag ist da! rufen die Wächter auf dem Gebirge Ephraim. Steht auf und laßt uns hinauf gen Zijon, zu Jehovah unserem Gotte, ziehen.',
        7: 'Denn also spricht Jehovah: Jubelt dem Jakob zu in Fröhlichkeit, und laßt es ertönen dem Haupte der Völkerschaften! Laßt es hören, lobet und sprechet: Rette dein Volk, Jehovah, den Überrest von Israel!',
        8: 'Siehe, Ich bringe sie vom Land der Mitternacht, und lasse sie zusammenkommen von den Seiten der Erde, mit ihnen den Blinden und den Lahmen, die Schwangere und die Gebärende allzumal; eine große Versammlung kommen sie hierher zurück.',
        9: 'Mit Weinen kommen sie, und unter Flehen geleite Ich sie und lasse sie zu Wasserbächen gehen auf geradem Weg, da sie nicht straucheln; denn Ich bin Israel zum Vater geworden, und Ephraim, er ist Mein Erst- geborener.',
        10: 'Höret das Wort Jehovahs, Völkerschaften, und sagt es auf den Inseln aus der Ferne an und sprechet: Der Israel zersprengte, bringt es zusammen und hütet es wie ein Hirt seine Herde.',
        11: 'Denn Jehovah hat eingelöst Jakob und ihn erlöst aus der Hand des Stärkeren denn er.',
        12: 'Und sie werden kommen und lobpreisen auf Zijons Höhe, und zusammenströmen zum Guten Jehovahs, zum Korn und zum Most und zum Öl und zu dem jungen Kleinvieh und Rind, und ihre Seele wird wie ein bewässerter Garten sein, und sie werden fürder nicht mehr sich betrüben.',
        13: 'Dann ist fröhlich die Jungfrau im Reigentanz, und die Jünglinge und die Alten allzumal; und ihre Trauer verwandle Ich in Freude und tröste sie und mache sie fröhlich aus ihrem Gram.',
        14: 'Und will die Seele der Priester laben mit Fettigkeit, und Mein Volk soll sich an Meinem Guten sättigen, spricht Jehovah.',
        15: 'So spricht Jehovah: Eine Stimme hört man in Ramah, eine Klage, bitterliches Weinen: Rachel weint über ihre Söhne. Sie weigert sich, sich trösten zu lassen über ihre Söhne; denn sie sind nicht da.',
        16: 'So spricht Jehovah: Halt ab deine Stimme vom Weinen, deine Augen von Tränen! Denn ein Lohn wird dir für dein Werk, spricht Jehovah, und sie kommen zurück aus dem Lande des Feindes.',
        17: 'Und Hoffnung ist da für deine Zukunft, spricht Jehovah; und die Söhne werden zurück in ihre Grenze kehren.',
        18: 'Ich hörte wohl Ephraim sich beklagen: Du hast gezüchtigt mich; und wie ein ungelehriges Kalb ward ich gezüchtigt. Wende mich zurück, so will ich zurückkehren; denn Du, Jehovah, bist mein Gott.',
        19: 'Denn, nachdem ich zurückgekehrt bin, fühle ich Reue, und nachdem ich erkenne, schlage ich auf meine Hüfte, fühle ich Scham und Schande; denn ich trage die Schmach meiner Jugend.',
        20: 'Ist nicht ein köstlicher Sohn Mir Ephraim, ein Kind des Ergötzens? Denn obschon Ich wider ihn geredet habe, gedenke Ich noch sein. Darum sind Meine Eingeweide rege für ihn, mit Erbarmen will Ich sein Mich erbarmen, spricht Jehovah.',
        21: 'Stelle dir Malzeichen auf, setze dir Pfeiler, richte dein Herz auf die Landstraße, den Weg, den du gegangen bist, kehre zurück, Jungfrau Israel, kehre zurück zu diesen deinen Städten.',
        22: 'Wie lange willst du umherstreifen, du abwendige Tochter? Denn Jehovah schafft Neues im Lande. Das Weib soll den Mann umgeben.',
        23: 'So spricht Jehovah der Heerscharen, der Gott Israels: Sie werden noch sagen dieses Wort im Land Jehudahs und in seinen Städten, wenn Ich ihre Gefangenschaft zurückwende: Es segne Jehovah dich, den Wohnort der Gerechtigkeit, den Berg der Heiligkeit!',
        24: 'Und wohnen werden darin Jehudah und all seine Städte allzumal, die Ackersleute und die, so mit der Herde ausziehen.',
        25: 'Denn Ich erquicke die matte Seele und erfülle jede Seele, die Leid trägt.',
        26: 'Darob erwachte ich und ich sah, und süß war mir mein Schlaf gewesen.',
        27: 'Siehe, Tage kommen, spricht Jehovah, da Ich besäen werde das Haus Israels und das Haus Jehudahs mit Samen des Menschen und mit Samen des Viehs.',
        28: 'Und es soll geschehen, wie Ich wachsam war über sie, auszuroden und abzubrechen und niederzureißen und zu zerstören und übel zu tun: so will Ich wachsam sein über sie, sie zu bauen und zu pflanzen, spricht Jehovah.',
        29: 'In selbigen Tagen werden sie nicht mehr sagen: Die Väter haben Herlinge gegessen und den Söhnen sind die Zähne stumpf geworden.',
        30: 'Sondern ein jeder Mann wird sterben in seiner Missetat. Einem jeden Menschen, der Herlinge ißt, sollen seine Zähne stumpf werden.',
        31: 'Siehe, Tage kommen, spricht Jehovah, da Ich mit dem Haus Israel und dem Haus Jehudah einen neuen Bund schließen werde.',
        32: 'Nicht wie der Bund, den Ich mit ihren Vätern schloß, am Tag, da Ich sie an der Hand faßte, sie aus dem Lande Ägypten herauszubringen; weil sie Meinen Bund zunichte gemacht haben, und Ich ward Meister über sie, spricht Jehovah.',
        33: 'Sondern dies wird sein der Bund, den Ich nach jenen Tagen mit dem Hause Israels schließen werde, spricht Jehovah: In ihre Mitte will Ich geben Mein Gesetz und auf ihr Herz es schreiben; und Ich will ihnen zum Gott sein, und sie sollen Mir zum Volke werden.',
        34: 'Und nicht mehr werden sie lehren, ein Mann seinen Genossen und ein Mann seinen Bruder, und sagen: Erkennet Jehovah; denn sie alle werden Mich kennen vom Kleinsten unter ihnen bis zu ihrem Größten, spricht Jehovah; denn Ich vergebe ihre Missetat und ihrer Sünde werde Ich nicht mehr gedenken.',
        35: 'So spricht Jehovah, Der die Sonne gibt zum Licht bei Tag, die Satzungen des Mondes und der Sterne zum Lichte bei Nacht, Der das Meer aufregt, daß seine Wogen toben. - Jehovah der Heerscharen ist Sein Name:',
        36: 'Wenn diese Satzungen vor Mir weichen, spricht Jehovah, soll auch der Same Israels aufhören, alle die Tage eine Völkerschaft vor Mir zu sein.',
        37: 'So spricht Jehovah: Wenn die Himmel oben werden gemessen und der Erde Grundfesten unten erforscht, will auch Ich verschmähen all den Samen Israels wegen alles dessen, was sie getan, spricht Jehovah.',
        38: 'Siehe, Tage kommen, spricht Jehovah, daß die Stadt wird gebaut für Jehovah vom Turm Chananeel bis zum Tore der Ecke.',
        39: 'Und ausgehen soll noch die Meßschnur gegenüber über den Hügel Gareb weg und sich gen Goath herumwenden.',
        40: 'Und aller Talgrund der Leichen und der Fettasche, und all die Äcker, bis zum Bache Kidron, bis zur Ecke des Tores der Rosse gen Aufgang sollen Jehovah heilig sein, nichts soll da ausgerodet noch niedergerissen werden ewiglich.',
    },
    32: {
        1: 'Das Wort, das zu Jirmejahu geschah, von Jehovah, im zehnten Jahr Zidkijahus, des Königs von Jehudah; dieses Jahr war das achtzehnte Jahr Nebuchadrezzars.',
        2: 'Und dazumal belagerte die Streitmacht des Königs zu Babel Jerusalem, und Jirmejahu, der Prophet, war eingesperrt im Vorhof der Wacht am Hause des Königs von Judah.',
        3: 'Ihn hatte Zidkijahu, Jehudahs König, eingesperrt und sagte: Warum weissagst du und sagst: So spricht Jehovah: Siehe, Ich gebe diese Stadt in die Hand des Königs von Babel und er wird sie erobern?',
        4: 'Und Zidkijahu, Jehudahs König, wird nicht entrinnen aus der Chaldäer Hand; denn gewißlich wird er gegeben in die Hand des Königs von Babel, daß sein Mund zu seinem Munde rede, und seine Augen sehen seine Augen.',
        5: 'Und nach Babel wird er den Zidkijahu führen; und dort soll er sein, bis Ich ihn heimsuche, spricht Jehovah. Wenn ihr mit den Chaldäern streitet, wird es euch nicht gelingen.',
        6: 'Und Jirmejahu sprach: Das Wort Jehovahs ist an Mich geschehen, sprechend:',
        7: 'Siehe, Chanameel, der Sohn des Schallum, deines Oheims, kommt zu dir und spricht: Kaufe für dich mein Feld in Anathoth; denn dein ist das Recht der Einlösung, es zu kaufen.',
        8: 'Und Chanameel, meines Oheims Sohn, kam zu mir nach dem Wort Jehovahs in den Vorhof der Wacht und sprach zu mir: Kaufe doch mein Feld zu Anathoth im Lande Benjamin; denn du hast das Recht des Erbbesitzes und dein ist die Einlösung. Kaufe es für dich. Und ich erkannte, daß es das Wort Jehovahs war.',
        9: 'Und ich kaufte das Feld von Chanameel, dem Sohne meines Oheims, in Anathoth, und wog ihm dar das Silber, sieben Schekel und zehn des Silbers.',
        10: 'Und ich schrieb es in einen Brief und siegelte ihn und bezeugte es mit Zeugen und wog das Silber auf einer Waage;',
        11: 'Und nahm den Kaufbrief, den versiegelten, mit dem Gebot und den Satzungen und den offenen;',
        12: 'Und gab den Kaufbrief an Baruch, den Sohn Nerijahs, Sohn Machsejahs, vor den Augen Chanameels, meines Oheims, und vor den Augen der Zeugen, die in dem Kaufbrief geschrieben waren, und vor den Augen aller Juden, die in dem Vorhof der Wacht saßen.',
        13: 'Und ich gebot dem Baruch vor ihren Augen, sprechend:',
        14: 'So spricht Jehovah der Heerscharen, der Gott Israels: Nimm diese Briefe, den Kaufbrief da und das Versiegelte, und diesen offenen Brief, und gib sie in ein irdenes Gefäß, auf daß sie auf viele Tage bestehen.',
        15: 'Denn so spricht Jehovah der Heerscharen, der Gott Israels: Noch wird man Häuser und Felder und Weinberge kaufen in diesem Land.',
        16: 'Und ich betete zu Jehovah, nachdem ich den Kaufbrief dem Baruch, Nerijahs Sohn, gegeben hatte und ich sprach:',
        17: 'O Herr, Jehovah, siehe, Du hast die Himmel und die Erde durch Deine große Kraft und Deinen ausgereckten Arm gemacht. Nichts ist Dir zu wunderbar.',
        18: 'Der Barmherzigkeit tut an Tausenden, und der Väter Missetat vergilt in ihrer Söhne Busen nach ihnen, der große, mächtige Gott, Jehovah der Heerscharen ist Sein Name.',
        19: 'Du, groß an Rat und viel an Tat, Dessen Augen aufgetan sind über alle Wege der Söhne des Menschen, dem Manne zu geben nach seinen Wegen und nach seiner Taten Frucht.',
        20: 'Der Du Zeichen setztest und Wahrzeichen im Lande Ägypten bis auf diesen Tag an Israel, und am Menschen gesetzt hast, und Dir einen Namen gemacht, wie es an diesem Tage ist.',
        21: 'Und hast Dein Volk Israel aus dem Land Ägypten mit Zeichen herausgebracht und mit Wahrzeichen und mit starker Hand und mit ausgerecktem Arm und mit großer Furcht;',
        22: 'Und ihnen dieses Land gegeben, das Du ihren Vätern geschworen hattest ihnen zu geben, ein Land, da Milch und Honig fließt.',
        23: 'Und sie kamen und nahmen es in Besitz, aber sie hörten nicht auf Deine Stimme und wandelten nicht nach Deinem Gesetz; alles, was Du ihnen zu tun geboten hattest, taten sie nicht; und Du ließest ihnen all dies Übel begegnen.',
        24: 'Siehe, die Wälle sind bis an die Stadt gekommen, sie zu erobern; und die Stadt wird in der Chaldäer Hand, die wider sie streiten, gegeben, Angesichts des Schwertes und des Hungers und der Pest. Und es geschieht, was Du geredet und siehe da, Du siehst es.',
        25: 'Und Du hast zu mir gesprochen, Herr Jehovah: Kaufe dir das Feld mit Silber und laß Zeugen es bezeugen; und die Stadt wird in der Chaldäer Hand gegeben.',
        26: 'Und es geschah Jehovahs Wort an Jirmejahu, sprechend:',
        27: 'Siehe, Ich bin Jehovah, der Gott alles Fleisches. Sollte irgendein Ding vor Mir zu wunderbar sein?',
        28: 'Darum spricht also Jehovah: Siehe, Ich gebe diese Stadt in der Chaldäer Hand und in die Hand Nebuchadrezzars, des Königs von Babel, daß er sie erobere.',
        29: 'Und die Chaldäer, die wider diese Stadt streiten, werden kommen und diese Stadt mit Feuer anzünden und sie verbrennen samt den Häusern, auf deren Dächern sie dem Baal räucherten und anderen Göttern Trankopfer gossen, um Mich zu reizen.',
        30: 'Denn die Söhne Israels und die Söhne Jehudahs taten von Jugend auf nur, was böse war in Meinen Augen. Denn die Söhne Israels reizten Mich nur durch ihrer Hände Tun, spricht Jehovah.',
        31: 'Denn diese Stadt ward Mir zum Zorne und zum Grimme von dem Tage an, da sie sie bauten und bis auf diesen Tag, daß Ich sie von Meinem Angesicht wegtue.',
        32: 'Ob all dem Bösen der Söhne Israels und der Söhne Jehudahs, das sie taten, Mich zu reizen, sie, ihre Könige, ihre Obersten, ihre Priester und ihre Propheten und der Mann Jehudahs und die da wohnen in Jerusalem.',
        33: 'Und sie wandten Mir den Nacken zu und nicht das Angesicht, und man belehrte sie, früh aufstehend und lehrend, aber sie hörten es nicht, um Zucht anzunehmen.',
        34: 'Und setzten ihre Scheusale in das Haus, über dem Mein Name ist genannt, es zu verunreinigen.',
        35: 'Und sie bauten die Opferhöhen des Baal im Tal Ben-Hinnoms, um ihre Söhne und ihre Töchter dem Molech durchzuführen, was Ich ihnen nicht geboten und Mir nicht in das Herz aufgekommen ist, daß solchen Greuel sie tun sollten, und Jehudah sündig machten.',
        36: 'Und nun um dessentwillen spricht also Jehovah, der Gott Israels, von dieser Stadt, von der ihr sprechet: Sie ist gegeben in die Hand des Königs von Babel durch das Schwert und durch Hunger und durch die Pest.',
        37: 'Siehe, Ich bringe sie zusammen aus allen Ländern, wohin Ich sie in Meinem Zorn und in Meinem Grimm und in großer Entrüstung verstoßen habe, und bringe sie zurück an diesen Ort und lasse sie wohnen in Sicherheit.',
        38: 'Daß sie Mir zum Volk seien, und Ich will ihnen zum Gott sein.',
        39: 'Und Ich gebe ihnen ein Herz und einen Weg, zu fürchten Mich alle Tage, ihnen und ihren Söhnen nach ihnen zum Guten.',
        40: 'Und einen ewigen Bund schließe Ich mit ihnen, daß Ich Mich nicht von ihnen zurückwende, ihnen Gutes zu tun; und in ihr Herz gebe Ich Furcht vor Mir, daß sie von Mir sich nicht abwenden.',
        41: 'Und werde Mich freuen über sie, um ihnen Gutes zu tun, und werde sie in diesem Lande pflanzen in Wahrheit, mit Meinem ganzen Herzen und mit Meiner ganzen Seele.',
        42: 'Denn also spricht Jehovah: Wie Ich all dies große Übel über dies Volk gebracht, so bringe Ich über sie alles das Gute, das Ich über sie redete.',
        43: 'Und das Feld soll gekauft werden in diesem Land, von dem ihr sagtet: Eine Verwüstung ist es, ohne Mensch und Vieh; in der Chaldäer Hand ist es gegeben.',
        44: 'Felder werden sie um Silber kaufen und den Brief schreiben und besiegeln und dafür Zeugen zeugen lassen im Lande Benjamin, und in Jerusalems Umgebungen und in den Städten Jehudahs, und in den Städten des Gebirges, und in den Städten der Niederung, und in den Städten des Mittagslandes; denn Ich wende zurück ihre Gefangenschaft, spricht Jehovah.',
    },
    33: {
        1: 'Und zum zweitenmal geschah Jehovahs Wort an Jirmejahu, und er war noch im Vorhof der Wacht eingesperrt, sprechend:',
        2: 'So spricht Jehovah, Der es tut, Jehovah, Der es bildet, um es zu festigen, Jehovah ist Sein Name.',
        3: 'Rufe Mich an und Ich antworte dir und sage dir große und sichere Dinge an, die du nicht weißt.',
        4: 'Denn also spricht Jehovah, der Gott Israels, über die Häuser dieser Stadt und über die Häuser der Könige Jehudahs, die abgebrochen werden wider die Wälle und wider das Schwert:',
        5: 'Sie sind gekommen, um zu streiten mit den Chaldäern, um sie zu füllen mit den Leichen des Menschen, die Ich in Meinem Zorn und in Meinem Grimm geschlagen; und ob all ihrer Bosheit habe Ich Mein Angesicht verborgen von dieser Stadt.',
        6: 'Siehe, Ich bringe ihr herauf Genesung und Heilung, und heile sie und offenbare ihnen einen Überfluß des Friedens und der Wahrheit.',
        7: 'Und bringe wieder die Gefangenschaft Jehudahs und die Gefangenschaft Israels, und baue sie wie zuerst.',
        8: 'Und mache sie rein von aller ihrer Missetat, womit sie wider Mich gesündigt, und vergebe alle ihre Missetaten, womit sie wider Mich gesündigt und womit sie von Mir abgefallen sind.',
        9: 'Und sie wird Mir zum Namen der Freude, zum Lob und zum Schmuck bei allen Völkerschaften der Erde werden, wenn sie von all dem Guten hören, das Ich ihnen tue, und werden schauen und zittern ob all dem Guten und ob all dem Frieden, den Ich ihr bereite.',
        10: 'So spricht Jehovah: Man wird noch hören an diesem Ort, - von dem ihr sprechet: Er ist verödet, so daß kein Mensch und kein Vieh da ist; in den Städten Jehudahs und in den Gassen Jerusalems, die verwüstet ist, so daß kein Mensch und kein Bewohner und kein Vieh da ist, -',
        11: 'Die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut, die Stimme derer, die da sagen: Bekennet Jehovah der Heerscharen, denn gut ist Jehovah, denn ewig ist Seine Barmherzigkeit; derer, die da Dankopfer hereinbringen in das Haus Jehovahs; denn Ich wende zurück die Gefangenschaft des Landes, wie zuerst, spricht Jehovah.',
        12: 'So spricht Jehovah der Heerscharen: Wieder werden an diesem Orte, dem verödeten, da weder Mensch noch Vieh war, und in allen seinen Städten Wohnorte für Hirten sein, die das Kleinvieh lagern lassen.',
        13: 'Im des Gebirges Städten, in den Städten der Niederung und in den Städten des Mittagslandes und dem Lande Benjamin und in Jerusalems Umgebungen und in den Städten Jehudahs wird vorüberziehen das Kleinvieh unter des Zählers Händen, spricht Jehovah.',
        14: 'Siehe, Tage kommen, spricht Jehovah, da Ich bestätige das gute Wort, das Ich geredet habe zum Hause Israel und über das Haus Jehudahs.',
        15: 'In jenen Tagen und zu jener Zeit will Ich sprossen lassen für David einen gerechten Sproß, und Er soll Recht und Gerechtigkeit tun auf Erden.',
        16: 'In jenen Tagen wird Jehudah gerettet werden und Jerusalem in Sicherheit wohnen, und so wird man Ihn nennen: Jehovah, unsere Gerechtigkeit.',
        17: 'Denn also spricht Jehovah: Dem David soll nicht ausgerottet werden ein Mann, der da sitze auf dem Thron des Hauses Israel.',
        18: 'Und den Priestern, den Leviten, soll nicht ausgerottet werden ein Mann vor Meinem Angesicht, der Brandopfer aufopfere und Speiseopfer anzünde und Schlachtopfer bereite alle Tage.',
        19: 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:',
        20: 'So spricht Jehovah: Wenn ihr zunichte macht Meinen Bund des Tages und Meinen Bund der Nacht, daß Tag und Nacht nicht sei zu seiner Zeit,',
        21: 'Soll auch Mein Bund mit David, Meinem Knecht, zunichte sein, daß er nicht einen Sohn habe, der König sei auf seinem Thron, und mit den Leviten, den Priestern, die Mir Dienst tun.',
        22: 'Wie man der Himmel Heer nicht zählen und den Sand des Meeres nicht messen kann, so will Ich mehren den Samen Davids, Meines Knechtes, und die Leviten, die Mir Dienst tun.',
        23: 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:',
        24: 'Sahst du nicht, was dieses Volk geredet und gesagt hat? Die zwei Familien, die Jehovah auserwählt hatte, hat Er verschmäht. Und sie lästern Mein Volk, als sollte es eine Völkerschaft nicht fürder vor ihnen sein.',
        25: 'So spricht Jehovah: Wenn Ich Meinen Bund des Tages und der Nacht, die Satzungen der Himmel und der Erde nicht gesetzt:',
        26: 'Dann werde Ich auch den Samen Jakobs und Davids, Meines Knechtes, verschmähen, daß Ich nicht nehme von seinem Samen Herrscher über den Samen Abrahams, Isaaks und Jakobs, wenn Ich ihre Gefangenschaft zurückbringe und ihrer Mich erbarme.',
    },
    34: {
        1: 'Das Wort, das von Jehovah geschah an Jirmejahu, während Nebuchadnezzar, der König Babels, und all seine Streitmacht und alle Königreiche der Erde unter der Herrschaft seiner Hand, und alle Völker stritten wider Jerusalem und wider alle seine Städte, sprechend:',
        2: 'So spricht Jehovah, der Gott Israels: Gehe hin und sprich zu Zidkijahu, dem König Jehudahs, und sprich zu ihm: So spricht Jehovah: Siehe, Ich gebe diese Stadt in die Hand des Königs von Babel, daß er sie mit Feuer verbrenne.',
        3: 'Und du wirst nicht aus seiner Hand entrinnen, sondern erfaßt und in seine Hand gegeben werden, und deine Augen sollen die Augen des Königs von Babel sehen, und sein Mund soll zu deinem Munde reden, und du sollst gen Babel kommen.',
        4: 'Höre nur das Wort Jehovahs, Zidkijahu, König von Jehudah! So spricht Jehovah über dich: Du sollst nicht sterben durch das Schwert;',
        5: 'In Frieden sollst du sterben und mit dem Brande deiner Väter, den früheren Königen, die vor dir waren, so werden sie auch dir einen verbrennen und um dich klagen: Wehe, Herr! Denn ein Wort habe Ich geredet, spricht Jehovah.',
        6: 'Und Jirmejahu, der Prophet, redete zu Zidkijahu, dem König Judahs, alle diese Worte in Jerusalem;',
        7: 'Und die Streitmacht des Königs von Babel stritt wider Jerusalem und wider alle die übrigen Städte Jehudahs, wider Lachisch und wider Asekah, denn sie waren als feste Städte verblieben unter Jehudahs Städten.',
        8: 'Das Wort, das an Jirmejahu von Jehovah geschah, nachdem der König Zidkijahu mit allem Volk in Jerusalem einen Bund geschlossen, daß sie Freilassung wollten ausrufen:',
        9: 'Daß jeder Mann seinen Knecht und jeder Mann seine Dienstmagd, Hebräer und Hebräerin, frei entsende, so daß kein Mann unter ihnen einen Juden, seinen Bruder, knechte.',
        10: 'Und alle Obersten und alles Volk, so den Bund eingegangen waren, gehorchten, daß jeder Mann seinen Knecht und jeder Mann seine Dienstmagd frei entsandte, daß sie sie nicht mehr knechteten. Und sie gehorchten und entsandten sie.',
        11: 'Und hernach wandten sie sich zurück und brachten die Knechte und die Dienstmägde, die sie frei entsandt hatten, zurück; und unterwarfen sie sich zu Knechten und Dienstmägden.',
        12: 'Und es geschah das Wort Jehovahs an Jirmejahu von Jehovah, sprechend:',
        13: 'So spricht Jehovah, der Gott Israels: Ich hatte mit euren Vätern einen Bund geschlossen am Tage, da Ich sie herausbrachte aus dem Lande Ägypten, aus dem Hause der Knechte, und gesprochen:',
        14: 'Am Ende von sieben Jahren sollt ihr entsenden jeder Mann seinen Bruder, den Hebräer, der sich dir verkauft hat und dir sechs Jahre diente, und ihn frei von dir entsenden; aber eure Väter hörten nicht auf Mich und neigten nicht ihr Ohr.',
        15: 'Und ihr waret diesen Tag zurückgekehrt, und hattet getan, was recht in Meinen Augen ist, daß ihr Freilassung jeder Mann seinem Genossen ausrufen ließet, und vor Mir in dem Hause, über dem Mein Name genannt wird, einen Bund geschlossen habt.',
        16: 'Ihr aber seid zurückgekehrt und habt entweiht Meinen Namen, und habt jeder Mann seinen Knecht und jeder Mann seine Dienstmagd, die ihr frei entsandt hattet, nach ihrem Wunsche, zu euch zurückgebracht und euch unterworfen, daß sie euch Knechte und Dienstmägde wären.',
        17: 'Darum spricht also Jehovah: Ihr habt nicht auf Mich gehört, daß ihr Freilassung, jeder Mann für seinen Bruder und jeder Mann für seinen Genossen, ließet ausrufen. Siehe, Ich rufe euch Freilassung aus, spricht Jehovah, für das Schwert, für Pest und für Hungersnot; und mache euch zum Schrecknis für alle Königreiche der Erde.',
        18: 'Und mache die Männer, die überschritten Meinen Bund, weil sie nicht bestätigten die Worte des Bundes, den sie vor Mir geschlossen, wie das Kalb, das sie entzweischnitten und zwischen seinen Stücken durchgegangen.',
        19: 'Die Obersten Jehudahs und die Obersten Jerusalems, die Verschnittenen und die Priester und alles Volk des Landes, die zwischen des Kalbes Stücken durchgegangen,',
        20: 'Und gebe sie in ihrer Feinde Hand und in die Hand derer, die ihnen nach der Seele trachten, daß ihre Leichname den Vögeln des Himmels und dem Getier der Erde zur Speise werden.',
        21: 'Und Zidkijahu, Jehudahs König, und seine Obersten gebe Ich in ihrer Feinde Hand und in die Hand derer, die ihnen nach der Seele trachten und in die Hand der Streitmacht des Königs von Babel, die von euch hinaufgezogen ist.',
        22: 'Siehe, Ich gebiete, spricht Jehovah, und bringe sie zurück zu dieser Stadt, auf daß sie streiten wider sie und sie erobern und mit Feuer verbrennen, und Jehudahs Städte gebe Ich zur Verwüstung, daß niemand darinnen wohnt.',
    },
    35: {
        1: 'Das Wort, das an Jirmejahu geschah von Jehovah in den Tagen Jehojakims, des Sohnes von Joschijahu, dem Könige Jehudahs, sprechend:',
        2: 'Gehe zum Haus der Rechabiter und rede mit ihnen und bringe sie herein in das Haus Jehovahs in eine der Zellen und gib ihnen Wein zu trinken.',
        3: 'Und ich nahm Jaasanjah, Jirmejahus Sohn, des Sohnes Chabazzinjahs und seine Brüder und alle seine Söhne und das ganze Haus der Rechabiter.',
        4: 'Und brachte sie herein zum Hause Jehovahs, zur Zelle der Söhne Chanans, des Sohnes Jigdaljahus, des Mannes Gottes, die neben der Zelle des Obersten ist, die über der Zelle Maasejahus, des Sohnes Schallums, ist, der die Schwelle hütete.',
        5: 'Und vor die Söhne des Hauses der Rechabiter gab ich Kelche voll von Wein und Becher, und sprach zu ihnen: Trinket Wein!',
        6: 'Und sie sprachen: Wir trinken keinen Wein; denn Jonadab, der Sohn Rechabs, unser Vater, hat über uns geboten und gesagt: Ihr sollt keinen Wein trinken, ihr und eure Söhne ewiglich!',
        7: 'Und ein Haus sollt ihr nicht bauen, noch Samen säen und keinen Weinberg pflanzen, noch einen haben, sondern in Zelten wohnen alle eure Tage, daß ihr lebet viele Tage auf dem Boden, darauf ihr Fremdlinge seid.',
        8: 'Und wir haben gehört auf die Stimme, Jehonadabs, des Sohnes Rechabs, unseres Vaters, nach allem, was er uns geboten, daß keinen Wein wir trinken all unsere Tage, wir, unsere Weiber, unsere Söhne und unsere Töchter.',
        9: 'Und daß wir keine Häuser bauen, darin zu wohnen, und Weinberg und Feld und Samen haben wir nicht;',
        10: 'Und wir wohnen in Zelten, und gehorchen und tun nach allem, was uns Jonadab, unser Vater, geboten hat.',
        11: 'Und es geschah, da Nebuchadrezzar, Babels König, heraufzog wider das Land, da sprachen wir: Kommt, und laßt uns kommen gen Jerusalem vor der Chaldäer Streitmacht und vor der Streitmacht Arams, und wir wohnen in Jerusalem.',
        12: 'Und es geschah Jehovahs Wort an Jirmejahu, sprechend:',
        13: 'So spricht Jehovah der Heerscharen, der Gott Israels: Gehe hin und sprich zum Manne Jehudahs und zu Jerusalems Bewohnern: Nehmet ihr nicht Zucht an, daß ihr auf Meine Worte hört? spricht Jehovah.',
        14: 'Es erstehen die Worte Jehonadabs, des Sohnes Rechabs, die er seinen Söhnen gebot, nicht Wein zu trinken; und sie trinken keinen bis auf diesen Tag; denn sie hören auf das Gebot ihres Vaters; und Ich redete zu euch, früh aufstehend und redend, und ihr höret nicht auf Mich.',
        15: 'Und Ich sandte zu euch all Meine Knechte, die Propheten, früh aufstehend und sendend, und sprach: Kehret doch zurück, jeder Mann von seinem bösen Wege, und machet eure Taten gut, und geht nicht anderen Göttern nach, ihnen zu dienen, auf daß ihr wohnet auf dem Boden, den Ich euch gab und euren Vätern; ihr aber neigtet nicht euer Ohr und hörtet nicht auf Mich.',
        16: 'Die Söhne Jehonadabs, des Sohnes Rechabs, bestätigen das Gebot ihres Vaters, das er ihnen geboten, aber dieses Volk hört nicht auf Mich.',
        17: 'Darum, so spricht Jehovah, der Gott der Heerscharen, der Gott Israels: Siehe, Ich bringe über Jehudah und über alle Bewohner Jerusalems all das Böse, das Ich über sie geredet habe: weil Ich zu ihnen redete und sie hörten nicht, und Ich ihnen rief und sie antworteten nicht.',
        18: 'Und zu dem Haus der Rechabiter sprach Jirmejahu: Also spricht Jehovah der Heerscharen, der Gott Israels: Weil ihr gehört habt auf das Gebot Jehonadabs, eures Vaters, und hieltet alle seine Gebote und tatet nach allem, was er euch geboten hat:',
        19: 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels, soll dem Jonadab, dem Sohne Rechabs, nicht ausgerottet werden ein Mann, der vor Mir stehe alle Tage.',
    },
    36: {
        1: 'Und es geschah im vierten Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah: Da geschah dieses Wort an Jirmejahu von Jehovah, sprechend:',
        2: 'Nimm dir die Rolle eines Buches und schreibe darauf alle die Worte, die Ich zu dir geredet habe über Israel und über Jehudah und über alle Völkerschaften von dem Tag an, da Ich zu dir geredet, seit den Tagen Joschijahus und bis auf diesen Tag.',
        3: 'Vielleicht daß die vom Hause Jehudah all das Böse hören, das Ich denke ihnen zu tun, daß sie zurückkehren jeder Mann von seinem bösen Weg, und Ich vergebe ihrer Missetat und ihrer Sünde.',
        4: 'Und Jirmejahu rief Baruch, den Sohn Nerijahs, und Baruch schrieb vom Munde Jirmejahus alle Worte Jehovahs, die Er zu ihm geredet hatte, auf die Rolle eines Buches.',
        5: 'Und Jirmejahu gebot Baruch und sprach: Ich bin eingesperrt, vermag nicht in das Haus Jehovahs zu kommen.',
        6: 'So gehe du und lies aus der Rolle, in der du aus Meinem Mund die Worte Jehovahs hast geschrieben, vor den Ohren des Volkes, im Hause Jehovahs am Tage des Fastens; und auch vor den Ohren derer von ganz Jehudah, die da von ihren Städten kommen, sollst du sie lesen.',
        7: 'Vielleicht fällt ihr Flehen vor dem Angesichte Jehovahs, daß sie zurückkehren jeder Mann von seinem bösen Wege; denn groß ist der Zorn und Grimm, den Jehovah geredet zu diesem Volk.',
        8: 'Und Baruch, der Sohn Nerijahs, tat nach allem, das Jirmejahu, der Prophet, ihm gebot, zu lesen Jehovahs Worte in dem Buch am Haus Jehovahs.',
        9: 'Und es geschah im fünften Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, im neunten Monat, riefen sie ein Fasten aus vor dem Angesichte Jehovahs für alles Volk in Jerusalem und alles Volk, das aus den Städten Jehudahs kommt nach Jerusalem.',
        10: 'Und Baruch las in dem Buche die Worte Jirmejahus an Jehovahs Hause in der Zelle Gemarjahus, des Sohnes Schaphans, des Schreibers, am oberen Vorhof, am Eingang des neuen Tores zum Haus Jehovahs in den Ohren alles Volkes.',
        11: 'Und Michajehu, der Sohn Gemarjahus, Sohn von Schaphan, hörte alle Worte Jehovahs aus dem Buche.',
        12: 'Und er ging hinab in das Haus des Königs zur Zelle des Schreibers und siehe, da saßen alle Obersten: Elischama, der Schreiber, und Delajahu, Schemajahus Sohn, und Elnathan, Achbors Sohn, und Gemarjahu, Schaphans Sohn, und Zidkijahu, Chananjahus Sohn, und alle Obersten;',
        13: 'Und Michajehu sagte ihnen alle Worte an, die er gehört hatte, als Baruch in dem Buche las vor den Ohren des Volkes.',
        14: 'Und alle Obersten sandten an Baruch Jehudi, den Sohn Nethanjahus, des Sohnes Schelemjahus, des Sohnes Kuschis und sagten: Die Rolle, in der du hast gelesen vor des Volkes Ohren, - nimm sie in deine Hand und komm! Und Baruch, der Sohn Nerijahus, nahm die Rolle in seine Hand und kam zu ihnen.',
        15: 'Und sie sprachen zu ihm: Setze dich doch und lies es vor unseren Ohren. Und Baruch las es vor ihren Ohren.',
        16: 'Und es geschah, wie sie alle die Worte gehört hatten, schauderten sie, jeder Mann gegen seinen Genossen und sprachen zu Baruch: Wir müssen dem König alle diese Worte ansagen.',
        17: 'Und den Baruch fragten sie und sagten: Sage uns doch an, wie du alle diese Worte aus seinem Mund geschrieben hast.',
        18: 'Und Baruch sprach zu ihnen: Mit seinem Munde las er mir alle diese Worte vor, und ich schrieb sie mit Tinte in das Buch.',
        19: 'Und die Obersten sprachen zu Baruch: Gehe und verbirg dich, du und Jirmejahu, daß kein Mann wisse, wo ihr seid.',
        20: 'Und sie kamen zum König in den Vorhof, und die Rolle hatten sie in der Zelle Elischamas, des Schreibers aufgehoben, und sagten vor den Ohren des Königs all die Worte an.',
        21: 'Und der König sandte den Jehudi, daß er die Rolle hole, und er holte sie aus der Zelle Elischamas, des Schreibers, und Jehudi las sie vor den Ohren des Königs und vor den Ohren aller Obersten, die bei dem König standen.',
        22: 'Und der König saß in dem Winterhaus, im neunten Monat, und das Feuerbecken brannte vor ihm.',
        23: 'Und es geschah, wenn Jehudi drei oder vier Blätter gelesen hatte, schnitt er sie mit dem Messer des Schreibers aus und warf sie auf das Feuer im Feuerbecken, bis die ganze Rolle über dem Feuer in dem Feuerbekken verzehrt ward.',
        24: 'Und sie schauerten nicht, noch zerrissen sie ihre Kleider, der König und alle seine Knechte, die alle diese Worte gehört hatten.',
        25: 'Doch aber vermittelten Elnathan und Delajahu und Gemarjahu bei dem König, daß er die Rolle nicht verbrennen sollte; er hörte aber nicht auf sie.',
        26: 'Und der König gebot Jerachmeel, dem Sohne des Königs, und Serajahu, dem Sohne Asriels, und Schelemjahu, dem Sohne Abdeels, Baruch, den Schreiber, und Jirmejahu, den Propheten, zu holen, aber Jehovah hatte sie verborgen.',
        27: 'Und es geschah Jehovahs Wort an Jirmejahu, nachdem der König die Rolle und die Worte, die Baruch aus dem Munde Jirmejahus geschrieben, verbrannt hatte, sprechend:',
        28: 'Nimm dir wiederum eine andere Rolle und schreibe darauf alle die früheren Worte, die auf der früheren Rolle waren, die Jehojakim, der König Jehudahs, hat verbrannt.',
        29: 'Und über Jehojakim, den König Jehudahs, sollst du sagen: Also spricht Jehovah: Du hast diese Rolle verbrannt und gesagt: Warum hast du darauf geschrieben und gesagt: Der König Babels kommt und verdirbt dieses Land und läßt daraus aufhören Mensch und Vieh.',
        30: 'Darum, so spricht Jehovah über Jehojakim, den König Jehudahs: Er soll keinen haben, der auf dem Throne Davids sitze, und sein Leichnam soll der Hitze am Tag und dem Frost bei Nacht hingeworfen werden.',
        31: 'Und heimsuchen werde Ich an ihm und seinem Samen und an seinen Knechten ihre Missetat und bringen über sie und über Jerusalems Bewohner und über den Mann Jehudahs all das Böse, das Ich über sie geredet habe, und sie hörten nicht.',
        32: 'Und Jirmejahu nahm eine andere Rolle und gab sie Baruch, dem Sohne Nerijahus, dem Schreiber, und er schrieb darauf aus Jirmejahus Mund alle die Worte des Buches, das Jehojakim, der König Jehudahs, im Feuer verbrannte, und wurden noch viele Worte, gleich jenen, dazugetan.',
    },
    37: {
        1: 'Und es regierte als König Zidkijahu, der Sohn Joschijahus, anstatt Chonjahus, des Sohnes Jehojakims, den Nebuchadrezzar, König von Babel, zum König im Land Jehudah hatte gemacht.',
        2: 'Er aber und seine Knechte und das Volk des Landes hörten nicht auf Jehovahs Worte, die Er durch die Hand Jirmejahus, des Propheten, redete.',
        3: 'Und es sandte der König Zidkijahu Jehuchal, Schelemjahs Sohn, und Zephanjahu, Maasejahs Sohn, den Priester, zu Jirmejahu, dem Propheten, und sprach: Bete doch für uns zu Jehovah, unserem Gott.',
        4: 'Und Jirmejahu ging ein und ging aus inmitten des Volkes und sie hatten ihn nicht in das Haus des Kerkers gesetzt.',
        5: 'Und eine Streitmacht Pharaos war von Ägypten ausgezogen, und die Chaldäer, die Jerusalem belagerten, hörten das Gerücht von ihnen und zogen hinauf von Jerusalem.',
        6: 'Und es geschah Jehovahs Wort an Jirmejahu, den Propheten, sprechend:',
        7: 'Also spricht Jehovah, der Gott Israels: So sprechet zu dem König Jehudahs, der euch zu Mir sendet, Mich zu befragen: Siehe, die Streitmacht des Pharao, die euch zum Beistand ausgezogen, kehrt in ihr Land Ägypten zurück.',
        8: 'Und die Chaldäer kehren zurück und streiten gegen diese Stadt und erobern sie und verbrennen sie mit Feuer.',
        9: 'So spricht Jehovah: Laßt eure Seelen nicht verführen und sprechet: Die Chaldäer sind von uns gezogen, - denn sie werden nicht gehen.',
        10: 'Ja, schlüget ihr die ganze Streitmacht der Chaldäer, die mit euch streiten und es verblieben unter ihnen nur durchstochene Männer, sie würden aufstehen, jeder Mann in seinem Zelte und diese Stadt mit Feuer verbrennen.',
        11: 'Und es geschah, als der Chaldäer Heeresmacht von Jerusalem hinaufgezogen war vor der Streitmacht Pharaos,',
        12: 'Da ging Jirmejahu aus Jerusalem hinaus, um nach dem Lande Benjamin zu gehen, um dort inmitten des Volkes seinen Teil zu nehmen.',
        13: 'Und er war an dem Tor Benjamins und es war dort ein Hauptmann der Wache und sein Name war Jirijah, ein Sohn Schelemjahs, des Sohnes Chananjahs, und er erfaßte Jirmejahu, den Propheten, und sprach: Zu den Chaldäern willst du abfallen!',
        14: 'Jirmejahu aber sprach: Lüge ist es, ich falle nicht zu den Chaldäern ab. Er aber hörte nicht auf ihn, und Jirijah erfaßte den Jirmejahu und brachte ihn hinein zu den Obersten.',
        15: 'Und die Obersten waren entrüstet über Jirmejahu und schlugen ihn und taten ihn in das Haus der Gebundenen, in das Haus Jehonathans, des Schreibers; denn dieses Haus hatten sie zum Haus des Kerkers gemacht.',
        16: 'So kam Jirmejahu in das Haus der Grube und in die Gewölbe; und Jirmejahu saß dort viele Tage.',
        17: 'Und König Zidkijahu sandte und ließ ihn holen, und der König fragte ihn in seinem Hause insgeheim und sprach: Ist ein Wort von Jehovah da? Und Jirmejahu sprach: Ja, und er sprach: Du wirst in die Hand des Königs zu Babel gegeben werden.',
        18: 'Und Jirmejahu sprach zum König Zidkijahu: Was habe ich wider dich und wider deine Knechte und wider dieses Volk gesündigt, daß ihr mich in das Haus des Kerkers gegeben habt?',
        19: 'Und wo sind eure Propheten, die euch weissagten und sprachen: Der König Babels kommt nicht wider euch und wider dieses Land?',
        20: 'Und nun, mein Herr König, höre doch und laß mein Flehen vor dich kommen, und laß mich nicht in Jehonathans, des Schreibers Haus zurückkehren, daß ich daselbst nicht sterbe.',
        21: 'Und König Zidkijahu gebot, daß man Jirmejahu im Vorhof der Wache behalte, und gebe ihm einen Laib Brot des Tages aus der Gasse der Bäcker, bis alles Brot aus der Stadt gar aus wäre. Und Jirmejahu blieb im Vorhof der Wacht.',
    },
    38: {
        1: 'Es hörten aber Schephatjah, Mathans Sohn, und Gedaljahu, Paschchurs Sohn, und Juchal, der Sohn Schelemjahus, und Paschchur, Malchijahs Sohn, die Worte, die Jirmejehu zu allem Volke redete und sprach:',
        2: 'So spricht Jehovah: Wer bleibt in dieser Stadt, wird sterben durch das Schwert, durch Hunger und durch Pest, und wer hinaus zu den Chaldäern geht, der wird leben, und hat als Beute seine Seele, daß er lebe.',
        3: 'So spricht Jehovah: Diese Stadt wird in die Hand der Streitmacht des Königs von Babel gegeben, daß er sie erobere.',
        4: 'Und die Obersten sprachen zu dem König: Es sterbe doch dieser Mann, weil er läßt erschlaffen die Hände aller Männer des Streites, die in dieser Stadt verbleiben, und die Hände alles Volkes, da er zu ihnen Worte wie diese redet; denn dieser Mann fragt nicht nach dem Frieden dieses Volkes, sondern nach dem Bösen.',
        5: 'Und König Zidkijahu sprach: Siehe, er ist in eurer Hand; denn nichts vermag der König mit euch.',
        6: 'Und sie nahmen Jirmejahu und warfen ihn in die Grube Malchijahus, des Sohnes des Königs, die im Vorhof der Wacht war, und ließen Jirmejahu an Stricken hinab, und in der Grube war kein Wasser, sondern Schlamm, und Jirmejahu sank in den Schlamm.',
        7: 'Und Ebedmelech, der Kuschite, ein Mann, ein Verschnittener, der im Hause des Königs war, hörte, daß sie Jirmejahu in die Grube taten, und der König saß im Tore Benjamins.',
        8: 'Und Ebedmelech ging hinaus aus des Königs Hause und redete mit dem König und sprach:',
        9: 'Herr König, Böses taten diese Männer in allem, das sie an Jirmejahu, dem Propheten, getan, daß sie ihn in die Grube warfen, so daß er auf der Stelle vor Hunger sterben müßte; denn es ist kein Brot mehr in der Stadt.',
        10: 'Und der König gebot Ebedmelech, dem Kuschiten, und sprach: Nimm unter deine Hand von hinnen dreißig Männer und bringe Jirmejahu, den Propheten, herauf aus der Grube, ehe denn er stirbt.',
        11: 'Und Ebedmelech nahm die Männer unter seine Hand und ging in das Haus des Königs unter die Schatzkammer und nahm von da altes Abgetragenes und altes Zerlumptes, und warf sie dem Jirmejahu an Stricken in die Grube zu.',
        12: 'Und Ebedmelech, der Kuschite, sprach zu Jirmejahu: Lege doch das alte Abgetragene und Zerlumpte unter die Achselhöhlen deiner Hände unter die Stricke. Und Jirmejahu tat also.',
        13: 'Und sie zogen Jirmejahu mit den Strikken empor und brachten ihn aus der Grube herauf, und Jirmejahu blieb im Vorhof der Wacht.',
        14: 'Und König Zidkijahu sandte und ließ Jirmejahu, den Propheten, zu sich holen in den dritten Eingang an Jehovahs Haus. Und der König sprach zu Jirmejahu: Ich frage dich ein Wort, verhehle kein Wort!',
        15: 'Und Jirmejahu sprach zu Zidkijahu: Wenn ich es dir ansage, läßt du mich nicht töten? Und wenn ich dir rate, hörst du nicht auf mich.',
        16: 'Und König Zidkijahu schwur dem Jirmejahu insgeheim und sprach: Beim Leben Jehovahs, Der diese Seele uns gemacht hat, ich lasse dich nicht töten, und gebe dich nicht in dieser Männer Hand, die dir nach der Seele trachten.',
        17: 'Und Jirmejahu sprach zu Zidkijahu: So spricht Jehovah, der Gott der Heerscharen, der Gott Israels: Wenn du hinausgehst zu den Obersten des Königs von Babel, so wird deine Seele leben und diese Stadt wird nicht verbrannt mit Feuer und du lebst und dein Haus.',
        18: 'Und wenn du nicht hinausgehst zu den Obersten des Königs von Babel, so wird diese Stadt in der Chaldäer Hand gegeben, und sie verbrennen sie mit Feuer, und du wirst nicht aus ihrer Hand entrinnen.',
        19: 'Und König Zidkijahu sprach zu Jirmejahu: Ich besorge die Juden, die zu den Chaldäern abgefallen sind, daß sie mich in ihre Hand geben und sie mich mißhandeln.',
        20: 'Und Jirmejahu sprach: Man gibt dich nicht hin. Höre doch auf Jehovahs Stimme, auf das, was ich rede mit dir, auf daß es gut mit dir sei, und deine Seele lebe.',
        21: 'Und wenn du dich weigerst, hinauszugehen, so ist dies das Wort, das mir Jehovah zeigte:',
        22: 'Und siehe, alle Weiber, die im Haus von Jehudahs König verblieben, werden zu den Obersten des Königs von Babel hinausgebracht; und siehe, sie sprechen nun: Angetrieben und übermocht haben dich die Männer deines Friedens, gesunken in den Sumpf sind deine Füße; sie sind hinter sich zurückgewichen.',
        23: 'Und alle deine Weiber und deine Söhne bringen sie hinaus zu den Chaldäern, und du wirst nicht aus ihrer Hand entrinnen, sondern durch die Hand des Königs von Babel erfaßt werden, und diese Stadt wird mit Feuer verbrannt.',
        24: 'Und Zidkijahu sprach zu Jirmejahu: Kein Mann soll von diesen Worten wissen, auf daß du nicht sterbest.',
        25: 'Und wenn die Obersten hören, daß ich mit dir redete, und zu dir kommen und zu dir sprechen: Sage uns doch an, was du zum König geredet, verhehle nichts von uns, daß wir dich nicht töten; und was hat der König zu dir geredet?',
        26: 'So sprich zu ihnen: Ich legte mein Flehen vor dem König nieder, daß man mich nicht in das Haus Jonathans zurückbringe, daß ich dort stürbe.',
        27: 'Und alle Obersten kamen zu Jirmejahu und fragten ihn, und er sagte ihnen an nach allen diesen Worten, die der König gebot, und sie schwiegen von ihm; denn es ward nichts gehört von der Sache.',
        28: 'Und Jirmejahu blieb im Vorhof der Wacht bis zu dem Tage, da Jerusalem ward erobert. Und es geschah also, da Jerusalem erobert ward.',
    },
    39: {
        1: 'Im neunten Jahr Zidkijahus, des Königs von Jehudah, im zehnten Monat, kam Nebuchadrezzar, Babels König, und seine ganze Streitmacht wider Jerusalem und belagerten dasselbe.',
        2: 'Im elften Jahre Zidkijahus, im vierten Monat, im neunten des Monats, ward in die Stadt gebrochen.',
        3: 'Und alle Obersten des Königs von Babel kamen und saßen am Mitteltor: Nergal Scharezer, Samgar, Nebu Sarsechim, der Hauptmann der Verschnittenen, Nergal Scharezer, der Hauptmann der Magier, und alle die übrigen Obersten des Königs von Babel.',
        4: 'Und es geschah, daß Zidkijahu, der König Jehudahs, und alle Kriegsleute sie sahen, so entwichen sie und gingen hinaus bei Nacht aus der Stadt auf dem Weg nach dem Garten des Königs durch das Tor zwischen den zwei Mauern und gingen auf dem Wege nach dem Blachfelde hinaus.',
        5: 'Und der Chaldäer Streitmacht setzte hinter ihnen nach, und sie erreichten Zidkijahu auf dem Blachfelde Jerichos, und nahmen ihn und brachten ihn hinauf zu Nebuchadnezzar, dem König Babels, nach Riblah im Lande Chamath, und er redete mit ihm im Gericht.',
        6: 'Und Babels König schlachtete die Söhne Zidkijahus in Riblah vor seinen Augen, und alle Vornehmen Jehudahs schlachtete der König Babels.',
        7: 'Und die Augen Zidkijahus blendete er und band ihn mit Ketten, ihn nach Babel zu bringen.',
        8: 'Und des Königs Haus und die Häuser des Volkes verbrannten die Chaldäer mit Feuer und rissen die Mauern Jerusalems ein.',
        9: 'Und das übrige Volk, die so in der Stadt verblieben, und die Abgefallenen, die zu ihm abgefallen, und das übrige Volk, die Verbliebenen, führte Nebusaradan, der Hauptmann der Leibwachen, nach Babel weg.',
        10: 'Und vom Volke die Armen, die gar nichts hatten, ließ Nebusaradan, der Hauptmann der Leibwachen, im Lande Jehudah verbleiben, und gab ihnen an jenem Tage Weinberge und Grundstücke.',
        11: 'Und Nebuchadrezzar, der König von Babel, gebot über Jirmejahu, durch die Hand des Nebusaradan, des Hauptmanns der Leibwachen, und sprach:',
        12: 'Nimm ihn und setze deine Augen auf ihn und tue ihm nichts Böses, sondern wie er zu dir reden wird, so tue mit ihm.',
        13: 'Und Nebusaradan, der Hauptmann der Leibwachen, und Nebuschasban, der Hauptmann der Verschnittenen, und Nergal Scharezer, der Hauptmann der Magier, und alle Hauptleute des Königs von Babel, sandten hin.',
        14: 'Und sie sandten und ließen Jirmejahu aus dem Vorhof der Wache holen und übergaben ihn Gedaljahu, dem Sohne Achikams, des Sohnes Schaphans, ihn hinauszubringen in das Haus und er wohnte in des Volkes Mitte.',
        15: 'Und an Jirmejahu geschah das Wort Jehovahs, da er noch im Vorhof der Wache eingesperrt war, sprechend:',
        16: 'Gehe hin und sprich zu Ebedmelech, dem Kuschiten, sprechend: So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich lasse Meine Worte über diese Stadt kommen zum Bösen, und nicht zum Guten, und sie werden an jenem Tage geschehen vor deinem Angesicht.',
        17: 'Und Ich errette dich an jenem Tage, spricht Jehovah, und du wirst nicht in die Hand der Männer, vor denen dir bangt, gegeben werden.',
        18: 'Denn Ich lasse dich entrinnen und du sollst nicht fallen durch das Schwert, und deine Seele soll dir zur Beute sein, weil du auf Mich vertraut hast, spricht Jehovah.',
    },
    40: {
        1: 'Das Wort, welches geschah an Jirmejahu von Jehovah, nachdem Nebusaradan, der Hauptmann der Leibwachen, ihn aus Ramah entsandt hatte. Als man ihn holte, da war er in Ketten gebunden inmitten all der Weggeführten Jerusalems und Jehudahs, die nach Babel weggeführt wurden.',
        2: 'Und der Hauptmann der Leibwachen nahm Jirmejahu und sprach zu ihm: Jehovah, dein Gott, hat dieses Böse über diesen Ort geredet;',
        3: 'Und Jehovah hat es kommen lassen und getan, wie Er geredet; denn ihr habt gesündigt wider Jehovah und nicht gehört auf Seine Stimme, und es geschah euch nach diesem Wort.',
        4: 'Und nun siehe, ich mache dir heute die Ketten an deiner Hand auf. Wenn es in deinen Augen gut ist, mit mir nach Babel zu kommen, komm, und ich will mein Auge auf dich setzen. Wenn es aber in deinen Augen böse ist, mit mir nach Babel zu kommen, unterlaß es. Siehe, das ganze Land ist vor dir. Wohin es gut und recht ist in deinen Augen zu gehen, dahin gehe!',
        5: 'Und noch hatte er nicht erwidert - Und kehre zu Gedaljah, dem Sohne Achikams, dem Sohne Schaphans, zurück, den der König von Babel über die Städte Jehudahs bestellt, und wohne mit ihm inmitten des Volkes, oder gehe irgendwohin, wohin zu gehen in deinen Augen recht ist. Und der Hauptmann der Leibwachen gab ihm Unterhalt und eine Ehrengabe und entsandte ihn.',
        6: 'Und Jirmejahu kam zu Gedaljah, dem Sohne Achikams nach Mizpah und wohnte mit ihm inmitten des Volkes, das im Land verblieben war.',
        7: 'Und alle Obersten der Streitmächte, so auf dem Felde waren, sie und ihre Männer, hörten, daß der König von Babel, Gedaljahu, Achikams Sohn, im Land bestellt und ihm anvertraut hatte Männer und Weiber und Kindlein und die Armen des Landes, die nicht nach Babel weggeführt worden.',
        8: 'Und sie kamen zu Gedaljah nach Mizpah, und Jischmael, Sohn Nethanjahus und Jochanan und Jonathan, die Söhne Kareachs, und Serajah, Sohn des Tanchumeth, und Ephais Söhne, des Netophathiters, und Jesanjahu, Maachathis Sohn und ihre Männer.',
        9: 'Und Gedaljahu, der Sohn Achikams, des Sohnes Schaphans, schwur ihnen und ihren Leuten und sprach: Fürchtet euch nicht den Chaldäern zu dienen; wohnet im Lande und dient dem König Babels, so wird es gut mit euch sein.',
        10: 'Und siehe, ich bleibe in Mizpah, zu stehen vor den Chaldäern, die werden zu uns kommen. Und ihr sammelt Wein und Obst und Öl ein und tut sie in eure Gefäße, und wohnt in euren Städten, die ihr eingenommen habt.',
        11: 'Und auch alle Juden, die in Moab und unter den Söhnen Ammons und in Edom und in allen Ländern waren, hörten, daß der König Babels Jehudah einen Überrest gegeben und über sie Gedaljahu, den Sohn Achikams, des Sohnes Schaphans, bestellt hatte.',
        12: 'Und alle Juden kehrten zurück von allen Orten, wohin sie verstoßen waren, und kamen in das Land Jehudah zu Gedaljah nach Mizpah, und sammelten Wein und Obst sehr viel.',
        13: 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die auf dem Felde waren, kamen zu Gedaljahu nach Mizpah,',
        14: 'Und sprachen zu ihm: Weißt du, daß Baalis, der König der Söhne Ammons, Jischmael, Nethanjahs Sohn, gesandt, dir die Seele zu erschlagen? Und Gedaljah, Achikams Sohn, glaubte ihnen nicht.',
        15: 'Und Jochanan, der Sohn Kareachs, sprach zu Gedaljah insgeheim in Mizpah und sprach: Laß mich doch gehen und Jischmael, den Sohn Nethanjahs schlagen, und kein Mann soll es wissen. Warum doch soll er dir die Seele schlagen und wir zerstreut werden, ganz Jehudah, die wir zu dir zusammengekommen sind, und der Überrest Jehudahs verlorengehen?',
        16: 'Und Gedaljah, der Sohn Achikams, sprach zu Jochanan, Kareachs Sohn: Tue nicht nach diesem Wort; denn Lügen redest du wider Jischmael.',
    },
    41: {
        1: 'Und es geschah im siebenten Monat, da kam Jischmael, der Sohn Nethanjahs, des Sohnes Elischamas, vom Samen des Königtums, und die Hauptleute des Königs und zehn Männer mit ihm zu Gedaljahu, dem Sohne Achikams, nach Mizpah, und sie aßen das Brot allzumal in Mizpah.',
        2: 'Und Jischmael, Nethanjahs Sohn, stand auf und die zehn Männer, die mit ihm waren, und schlugen Gedaljahu, den Sohn Achikams, des Sohnes Schaphans, mit dem Schwert, und er tötete ihn, den Babels König im Lande bestellt hatte;',
        3: 'Und alle Juden, die mit ihm, mit Gedaljahu, in Mizpah waren, und die Chaldäer, die dort sich fanden, die Kriegsleute, schlug Jischmael.',
        4: 'Und es geschah am zweiten Tage, da er Gedaljahu getötet hatte und kein Mann es wußte,',
        5: 'Daß achtzig Männer von Schichem, von Schilo und von Schomron kamen mit geschorenem Barte und zerrissenen Kleidern und hatten sich geritzt und hatten Speiseopfer und Weihrauch in ihrer Hand, daß sie sie brächten in Jehovahs Haus.',
        6: 'Und Jischmael, der Sohn Nethanjahs, ging heraus von Mizpah ihnen entgegen, ging daher und weinte, und als er auf sie traf, so sprach er zu ihnen: Kommt herein, zu Gedaljahu, dem Sohne Achikams.',
        7: 'Und es geschah, da sie mitten in die Stadt kamen, schlachtete sie Jischmael, der Sohn Nethanjahs mitten in die Grube, er und die Männer, die mit ihm waren.',
        8: 'Zehn Männer aber fanden sich unter ihnen, und die sprachen zu Jischmael: Töte uns nicht. Wir haben Verheimlichtes in dem Feld, Weizen und Gerste und Öl und Honig. Und er hörte auf und tötete sie nicht inmitten ihrer Brüder.',
        9: 'Und die Grube, worein Jischmael all die Leichen der Männer, die er zur Seite Gedaljahus geschlagen, warf, war die, welche König Asa wider Baascha, den König Israels, gemacht hatte; sie füllte Jischmael, der Sohn Nethanjahus, mit Erschlagenen.',
        10: 'Und Jischmael nahm gefangen all den Überrest des Volkes, das in Mizpah war, die Töchter des Königs und alles Volk, das verblieb in Mizpah, über welche Nebusaradan, der Hauptmann der Leibwachen, Gedaljahu, den Sohn Achikams, bestellt hatte. Und Jischmael, der Sohn Nethanjahs, führte sie gefangen und ging dahin, um zu den Söhnen Ammons hinüberzuziehen.',
        11: 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, hörten alles das Böse, das Jischmael, Nethanjahs Sohn, getan.',
        12: 'Und sie nahmen alle Männer und zogen hin, mit Jischmael, dem Sohn Nethanjahs, zu streiten, und fanden ihn bei dem großen Wasser zu Gibeon.',
        13: 'Und es geschah, wie alles Volk, das mit Jischmael war, Jochanan sah, den Sohn des Kareach, und alle Obersten der Streitmächte, die mit ihm waren, da wurden sie fröhlich.',
        14: 'Und alles Volk, das Jischmael aus Mizpah gefangen führte, wandte sich um und kehrten zurück, und gingen zu Jochanan, dem Sohn Kareachs.',
        15: 'Und Jischmael, der Sohn Nethanjahs, entrann mit acht Männern vor Jochanan und ging zu den Söhnen Ammons.',
        16: 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, nahmen all den Überrest des Volkes, das er zurückgebracht von Jischmael, dem Sohne Nethanjahs, aus Mizpah, nachdem derselbe geschlagen den Gedaljah, den Sohn des Achikam, die Leute, die Kriegsleute und die Weiber und die Kindlein, und die Verschnittenen, die er von Gibeon zurückgebracht.',
        17: 'Und sie gingen hin und blieben in der Herberge Kimham, die neben Bethlehem ist, um hinzuziehen, um nach Ägypten zu kommen,',
        18: 'Vor den Chaldäern; denn sie fürchteten sich vor ihnen, weil Jischmael, der Sohn Nethanjahs, Gedaljah, den Sohn Achikams, geschlagen, den der König von Babel im Lande bestellt hatte.',
    },
    42: {
        1: 'Und alle Obersten der Streitmächte und Jochanan, Kareachs Sohn, und Jesanjah, Hoschajahs Sohn, und alles Volk vom Kleinen bis zum Großen traten herzu,',
        2: 'Und sprachen zu Jirmejahu, dem Propheten: Laß unser Flehen doch vor dich fallen und bete für uns zu Jehovah, deinem Gott, für allen diesen Überrest, denn wenige sind von den Vielen verblieben, wie deine Augen uns sehen.',
        3: 'Daß Jehovah, dein Gott, uns ansage den Weg, auf dem wir gehen, und das, was wir tun sollen.',
        4: 'Und Jirmejahu, der Prophet, sprach zu ihnen: Ich habe gehört, seht, ich bete zu Jehovah, eurem Gott, nach euren Worten, und es soll geschehen, daß all das Wort, das Jehovah euch antwortet, ich euch ansage und euch kein Wort vorenthalte.',
        5: 'Und sie sprachen zu Jirmejahu: Es sei Jehovah ein wahrhafter und treuer Zeuge unter uns, wenn wir nicht nach all dem Wort, womit Jehovah, dein Gott, dich zu uns sendet, also tun.',
        6: 'Es sei gut oder böse, auf die Stimme Jehovahs, unseres Gottes, zu Dem wir dich senden, auf Ihn hören wir, auf daß es gut für uns sei, wenn auf die Stimme Jehovahs, unseres Gottes, wir hören.',
        7: 'Und es geschah am Ende von zehn Tagen, daß Jehovahs Wort an Jirmejahu geschah.',
        8: 'Und er rief Jochanan, den Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, und alles Volk vom Kleinen und bis zum Großen,',
        9: 'Und sprach zu ihnen: Also spricht Jehovah der Gott Israels, an Den ihr mich gesandt, daß euer Flehen ich fallen lasse vor Sein Angesicht.',
        10: 'Wenn ihr in diesem Lande wohnen bleibt, so will Ich euch bauen und nicht niederreißen, und euch pflanzen und nicht ausroden; denn Mich gereut des Bösen, das Ich euch getan.',
        11: 'Fürchtet euch nicht vor Babels König, vor dem ihr euch fürchtet! Fürchtet euch nicht vor ihm, spricht Jehovah, denn Ich bin mit euch, euch zu helfen und euch aus seiner Hand zu erretten.',
        12: 'Und Ich will euch Erbarmen geben, und er wird euer sich erbarmen und euch auf euren Boden zurückkehren lassen.',
        13: 'Und wenn ihr sprechet: Wir werden nicht in diesem Lande wohnen, so daß ihr nicht hört auf die Stimme Jehovahs, eures Gottes,',
        14: 'Wenn ihr sagt: Nein, laßt uns in das Land Ägypten eingehen, daß wir nicht Streit sehen und nicht hören die Stimme der Posaune, und nicht nach Brot hungern. Und lasset uns dort wohnen;',
        15: 'So hört nun darum das Wort Jehovahs, ihr Überrest Jehudahs: So spricht Jehovah der Heerscharen, der Gott Israels: Setzet ihr euer Angesicht, einzugehen nach Ägypten, und ihr kommt hinein, als Fremdlinge allda zu weilen;',
        16: 'So soll geschehen, daß das Schwert, vor dem ihr euch fürchtet, euch dort erreicht in dem Land Ägypten, und der Hunger, dessen ihr euch besorgtet, soll dort hinter euch her sich an euch hängen in Ägypten, daß dort ihr sterbet.',
        17: 'Und wird geschehen, daß alle Männer, die ihre Angesichte setzen, nach Ägypten zu kommen, daß sie dort als Fremdlinge weileten, daselbst sterben durch das Schwert, durch Hunger und durch Pest, und wird kein Rest unter ihnen sein und keiner entkommen vor dem Bösen, das Ich kommen lasse über sie.',
        18: 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Wie sich ergoß Mein Zorn und Grimm über Jerusalems Bewohner, so wird Mein Grimm sich ergießen über euch, wenn ihr nach Ägypten kommt, und sollt zur Verwünschung, zum Erstaunen und zum Fluch und zur Schmach werden, und diesen Ort nicht wieder sehen.',
        19: 'Geredet hat Jehovah über euch, ihr Überrest Jehudahs: Geht nicht ein nach Ägypten! Ihr sollt wissen, daß heute ich unter euch gezeugt habe.',
        20: 'Denn ihr seid in euren Seelen abgeirrt, da ihr mich an Jehovah, euren Gott, sandtet und sprachet: Bete für uns zu Jehovah, unserem Gotte; und nach allem, was Jehovah, unser Gott, spricht, also sage uns an, und wir wollen es tun.',
        21: 'Und ich sagte es heute euch an, ihr aber höret nicht auf Jehovahs, eures Gottes, Stimme, und auf alles, was Er euch durch mich sendet.',
        22: 'Und nun sollet ihr wissen, daß ihr durch das Schwert, durch Hunger und Pestilenz an dem Orte sterben werdet, dahin ihr Lust habt zu gehen, um allda als Fremdlinge zu weilen.',
    },
    43: {
        1: 'Und es geschah, als Jirmejahu vollendet hatte zu reden zu allem Volk alle Worte Jehovahs, ihres Gottes, die Jehovah, ihr Gott, an sie durch ihn gesandt hatte, alle diese Worte,',
        2: 'Da sprach Asarjah, Hoschajahs Sohn, und Jochanan, Kareachs Sohn, und alle vermessenen Männer, und sprachen zu Jirmejahu: Lüge redest du. Jehovah, unser Gott, hat dich nicht gesandt zu sprechen: Kommt nicht nach Ägypten, als Fremdlinge dort zu weilen;',
        3: 'Denn Baruch, der Sohn Nerijahs, hat dich angetrieben wider uns, damit er uns in der Chaldäer Hand gebe, daß sie uns töten und uns nach Babel wegführen.',
        4: 'Und Jochanan, Kareachs Sohn, und alle Obersten der Streitmächte und das ganze Volk hörten nicht auf Jehovahs Stimme, daß sie im Lande Jehudah wohnen sollten.',
        5: 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte nahmen allen Überrest von Jehudah, die, so von allen Völkerschaften, dahin sie verstoßen worden, zurückgekommen waren, um im Lande Jehudah zu weilen,',
        6: 'Die Männer und die Weiber und die Kindlein und die Töchter des Königs und jede Seele, die Nebusaradan, der Hauptmann der Leibwachen bei Gedaljahu, dem Sohne Achikams, des Sohnes von Schaphan, und bei Jirmejahu, dem Propheten, und bei Baruch, Nerijahs Sohn, gelassen hatte,',
        7: 'Und sie gingen ein in das Land Ägypten, weil sie nicht auf die Stimme Jehovahs hörten, und kamen bis Thachpanches.',
        8: 'Und es geschah das Wort Jehovahs an Jirmejahu in Thachpanches, sprechend:',
        9: 'Nimm in deine Hand große Steine und lege sie hehlings in den Lehm im Ziegelofen an den Eingang in das Haus Pharos, in Thachpanches vor den Augen der jüdischen Männer,',
        10: 'Und sprich zu ihnen: Also spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich sende und hole Nebuchadrezzar, Babels König, meinen Knecht, und setze seinen Thron über diese Steine, die Ich hehlings hingelegt habe, und er spanne sein Gezelt aus über sie.',
        11: 'Und er kommt und schlägt das Land Ägypten: mit dem Tode die, so des Todes sind, mit Gefangenschaft die, so für Gefangenschaft sind, mit dem Schwert, die für das Schwert sind.',
        12: 'Und Feuer zünde Ich an in den Häusern der Götter Ägyptens, daß er sie verbrenne, und sie gefangen führe und sich umhülle mit dem Lande Ägypten, wie der Hirt sich mit seinem Kleid umhüllt und geht aus davon im Frieden.',
        13: 'Und soll die Bildsäulen des Sonnenhauses im Lande Ägypten zerbrechen und die Häuser der Götter Ägyptens mit Feuer verbrennen.',
    },
    44: {
        1: 'Das Wort, das an Jirmejahu geschah, über alle Juden, so im Lande Ägypten wohnen, die so in Migdol und in Thachpanches und in Noph und im Lande Pathros wohnen, sprechend:',
        2: 'So spricht Jehovah der Heerscharen, der Gott Israels: Ihr habt gesehen all das Böse, das Ich über Jerusalem und über alle Städte Jehudahs kommen ließ und seht, eine Öde sind sie dieses Tages und niemand wohnt darin;',
        3: 'Ob ihrer Bosheit, die sie taten, daß sie Mich reizten, daß sie hingingen zu räuchern, zu dienen anderen Göttern, die sie nicht kannten, weder sie, noch ihr, noch eure Väter.',
        4: 'Und Ich sandte zu euch alle Meine Knechte, die Propheten, fing früh an und sandte sie und sprach: Tut doch solchen Greuel nicht, den Ich hasse.',
        5: 'Aber sie hörten nicht und sie neigten nicht ihr Ohr, daß sie umkehrten von ihrer Bosheit, daß sie anderen Göttern nicht räucherten.',
        6: 'Und es ergoß sich Mein Grimm und Mein Zorn und brannte in den Städten Jehudahs und in den Gassen Jerusalems, und sie wurden zur Öde, zur Verwüstung, wie an diesem Tag.',
        7: 'Und nun spricht also Jehovah, der Gott der Heerscharen, der Gott Israels: Warum tut ihr großes Böse wider eure Seelen, daß ihr für euch ausrottet, Mann und Weib, Kindlein und Säugling, aus Jehudahs Mitte, daß euch kein Überrest mehr übrigbleibt?',
        8: 'Daß ihr Mich reizet durch eurer Hände Werk, da ihr anderen Göttern räuchert im Lande Ägypten, in das ihr kamt, um allda zu weilen, daß ihr euch ausrottet, und daß ihr zum Fluch und zur Schmach unter allen Völkerschaften der Erde werdet?',
        9: 'Habt ihr vergessen die Bosheiten eurer Väter, und die Bosheiten der Könige Jehudahs, und die Bosheiten ihrer Weiber und eure Bosheiten, und die Bosheiten eurer Weiber, die sie im Lande Jehudahs taten, und auf den Gassen Jerusalems?',
        10: 'Noch sind sie nicht zerknirscht bis auf diesen Tag, und fürchten sich nicht und wandeln nicht in Meinem Gesetz und in Meinen Satzungen, die Ich vor euch und eure Väter gegeben habe!',
        11: 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich setze Mein Angesicht wieder euch zum Bösen, und zur Ausrottung von ganz Jehudah.',
        12: 'Und Ich werde den Überrest von Jehudah nehmen, die, so ihr Angesicht gesetzt haben in das Land Ägypten einzuziehen, da zu weilen; sie alle sollen umkommen im Lande Ägypten, sie sollen fallen durch das Schwert und durch Hunger umkommen, vom Kleinen bis zum Großen. Durch das Schwert und durch Hunger sollen sie sterben und zur Verwünschung, zum Erstaunen und zum Fluch und zur Schmach werden.',
        13: 'Und die so im Lande Ägypten wohnen, will Ich heimsuchen, wie Ich Jerusalem durch das Schwert, durch Hunger und durch Pest habe heimgesucht.',
        14: 'Und soll kein Entkommen noch Rest sein für den Überrest Jehudahs, die gekommen sind, dort im Land Ägypten zu weilen, und um in das Land Jehudah zurückzukehren, wohin sie ihre Seele erhoben, dahin zurückzukehren, um allda zu wohnen; denn sie werden nicht zurückkehren, es sei denn die Entkommenen.',
        15: 'Und es antworteten dem Jirmejahu alle Männer, die da wußten, daß ihre Weiber anderen Göttern räucherten und alle Weiber, die in großer Versammlung standen, und alles Volk, die, so im Land Ägypten, in Pathros wohnten und sprachen:',
        16: 'Das Wort, das du zu uns im Namen Jehovahs geredet hast, darin hören wir nicht auf dich.',
        17: 'Sondern lasset uns tun jedes Wort, das aus unserem Munde ausging, der Königin der Himmel räuchern und ihr Trankopfer ausgießen, wie wir getan, wir und unsere Väter, unsere Könige und unsere Obersten in Jehudahs Städten und in den Gassen Jerusalems. Und wir wurden satt am Brot und hatten es gut und sahen nichts Böses.',
        18: 'Und seit wir aufhörten, der Königin der Himmel zu räuchern und ihr Trankopfer auszugießen, mangelt es uns an allem, und wir kamen um durch das Schwert und durch den Hunger.',
        19: 'Und wenn wir der Königin der Himmel räuchern und ihr Trankopfer ausgießen, machen wir ihr ohne unsere Männer Kuchen, sie zu verehren, und gießen ihr Trankopfer aus.',
        20: 'Und Jirmejahu sprach zum ganzen Volke, zu den Männern und zu den Weibern und zu allem Volke, zu denen, die ihm das Wort antworteten, sprechend:',
        21: 'Hat nicht eurer Räucherungen, mit denen ihr in Jehudahs Städten und in den Gassen Jerusalems, ihr und eure Väter, eure Könige und eure Obersten und das Volk des Landes räucherten, hat nicht ihrer Jehovah gedacht, und stieg es nicht auf in Sein Herz?',
        22: 'Und Jehovah vermochte es nicht mehr zu tragen vor der Bosheit eurer Handlungen, vor den Greueln, die ihr tatet, so daß euer Land zur Öde und zum Erstaunen und zum Fluche ward, daß niemand wohnt darin, wie an diesem Tag?',
        23: 'Davor, daß ihr geräuchert und daß ihr wider Jehovah gesündigt und auf Jehovahs Stimme nicht gehört habt, und in Seinem Gesetz und in Seinen Satzungen und in Seinen Zeugnissen nicht wandeltet, darum ist euch dieses Böse begegnet, wie an diesem Tage.',
        24: 'Und Jirmejahu sprach zu allem Volk und zu allen Weibern: Hört das Wort Jehovahs, ganz Jehudah, die ihr im Land Ägypten seid.',
        25: 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Ihr und eure Weiber habt mit eurem Mund geredet und erfüllt mit euren Händen was ihr sprachet: Wir wollen nach unseren Gelübden, die wir gelobt, tun, daß wir räuchern der Königin der Himmel und ihr Trankopfer ausgießen. Bestätigt eure Gelübde und tut eure Gelübde!',
        26: 'Darum höret das Wort Jehovahs, ganz Jehudah, die ihr im Land Ägypten wohnt: Siehe, Ich schwöre es bei Meinem großen Namen, spricht Jehovah: Nie mehr soll Mein Name angerufen werden mit dem Munde irgendeines Mannes aus Jehudah, daß er spreche: Es lebt der Herr Jehovah! im ganzen Land Ägypten.',
        27: 'Siehe, Ich wache über sie zum Bösen und nicht zum Guten, daß jeder Mann aus Jehudah im Land Ägypten umkomme, durch das Schwert und durch den Hunger, bis sie alle sind.',
        28: 'Und die dem Schwert entkommen, werden aus dem Lande Ägypten in das Land Jehudah zurückkommen, in geringer Zahl; und wird erkennen aller Überrest Jehudahs, so zum Lande Ägypten gekommen war, dort zu weilen, wessen Wort besteht, das von Mir oder das ihrige.',
        29: 'Und dies sei euch das Zeichen, spricht Jehovah, daß Ich euch heimsuche an diesem Ort, auf daß ihr erkennt, daß Ich Meine Worte über euch bestätige zum Bösen.',
        30: 'So spricht Jehovah: Siehe, Ich gebe den Pharao Chophra, Ägyptens König, in seiner Feinde Hand und in die Hand derer, die ihm nach der Seele trachten, wie Ich Zidkijahu, Jehudahs König, gab in die Hand Nebuchadrezzars, des Königs von Babel, seines Feindes, und dessen, der ihm nach der Seele trachtete.',
    },
    45: {
        1: 'Das Wort, das Jirmejahu, der Prophet, zu Baruch, Nerijahs Sohn, redete, da er diese Worte in ein Buch schrieb aus Jirmejahus Mund im vierten Jahre Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, sprechend:',
        2: 'So spricht Jehovah, der Gott Israels, über dich, Baruch:',
        3: 'Du sprachst: Wehe mir doch, daß Jehovah Gram zu meinem Schmerz hinzutut. Ich bin müde von meinem Seufzen, und Ruhe finde ich nicht.',
        4: 'So sollst du zu ihm sagen: So spricht Jehovah: Siehe, was Ich baute, reiße Ich nieder, und was Ich pflanzte, rode Ich aus, und dieses ganze Land ist es;',
        5: 'Und du trachtest für dich nach Großem. Trachte nicht danach; denn siehe, Ich lasse Böses kommen über alles Fleisch, spricht Jehovah; dir aber gebe Ich deine Seele zur Beute an allen Orten, dahin du gehen wirst.',
    },
    46: {
        1: 'Das Wort Jehovahs, das an Jirmejahu, den Propheten, geschah über die Völkerschaften,',
        2: 'Wider Ägypten, wider die Streitmacht des Pharao Necho, des Königs von Ägypten, die am Flusse Phrath in Charchemisch war, die Nebuchadrezzar, Babels König, schlug im vierten Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah:',
        3: 'Richtet her Tartsche und Schild, und tretet herzu zum Streit!',
        4: 'Spannet die Rosse ein, steigt auf, ihr Reiter, und stellt euch auf in Helmen, scheuert die Speere, zieht die Panzer an!',
        5: 'Warum sehe Ich sie entsetzt hinter sich zurückweichen, und ihre Helden zerstoßen? In Flucht fliehen sie und wenden sich nicht; Bangen ringsum! spricht Jehovah.',
        6: 'Der Schnelle soll nicht entfliehen, und nicht entrinnen der Held; gegen Mitternacht, entlang dem Ufer des Flusses Phrath straucheln und fallen sie.',
        7: 'Wer ist es, der aufsteigt wie der Strom, dessen Wasser wie Flüsse wogen?',
        8: 'Ägypten, wie der Strom steigt es auf, und die Wasser wogen wie die Flüsse. Und es spricht: Ich steige auf und bedecke das Land, ich zerstöre die Stadt und die darin wohnen.',
        9: 'Steiget herauf, ihr Rosse, rast ihr Streitwagen; und lasset die Helden ausziehen, Kusch und Put, so die Tartsche erfassen, und die Ludim, so erfassen, spannen den Bogen.',
        10: 'Und dies ist der Tag für den Herrn Jehovah der Heerscharen, ein Tag der Rache, daß Er Sich an Seinen Drängern räche; und das Schwert fresse und werde satt und schwelge in ihrem Blut; denn ein Schlachtopfer sind sie dem Herrn Jehovah der Heerscharen im Lande der Mitternacht, am Flusse Phrath.',
        11: 'Steige hinauf, Gilead und hole Balsam, Jungfrau, Tochter Ägyptens. Vergeblich machst du viel der Heilmittel. Da ist für dich kein Aufkommen.',
        12: 'Die Völkerschaften hörten deine Unehre, deines Klageschreis ist voll die Erde; denn der Held strauchelt über den Helden, miteinander fallen sie beide.',
        13: 'Das Wort, welches Jehovah zu Jirmejahu, dem Propheten, redete, da Nebuchadrezzar, der König von Babel, kam, das Land Ägypten zu schlagen:',
        14: 'Sagt es in Ägypten an, und laßt es in Migdol hören, und laßt es hören in Noph und in Thachpanches; sprechet: Stelle dich auf und bereite dich; denn das Schwert frißt rings um dich her.',
        15: 'Warum ist weggefegt dein Gewaltiger? steht er nicht? denn Jehovah hat ihn fortgetrieben;',
        16: 'Er macht viel der Strauchelnden, auch fällt der Mann über seinen Genossen. Und sie sprechen: Stehe auf, laßt uns zu unserem Volk zurückkehren, und zum Land unserer Geburt vor dem bedrückenden Schwerte.',
        17: 'Sie rufen da: Zertrümmert ist Pharao, Ägyptens König. Seine bestimmte Zeit hat er vorbeigelassen.',
        18: 'Bei meinem Leben, spricht der König, Jehovah der Heerscharen ist Sein Name: denn wie der Thabor unter den Bergen und wie der Karmel an dem Meer kommt Er.',
        19: 'Mache dir Geräte der Wegführung, du Einwohnerin, Tochter Ägyptens, denn verwüstet wird Noph werden und wird angezündet, daß niemand darin wohnt.',
        20: 'Ägypten ist eine gar schöne Färse, Zerrüttung kommt von Mitternacht, sie kommt.',
        21: 'Auch ihre Söldlinge in ihrer Mitte sind wie gemästete Kälber; denn auch sie wenden sich, sie fliehen allzumal, sie stehen nicht; denn gekommen ist über sie der Tag ihrer Not, die Zeit ihrer Heimsuchung.',
        22: 'Ihre Stimme geht wie einer Schlange; denn sie gehen mit Gewalt, und mit Äxten kommen sie zu ihr, wie die Holzhauer.',
        23: 'Sie hauen ihren Wald um, spricht Jehovah; denn er wird nicht ergründet, denn mehr sind ihrer, als der Heuschrecken, und ihrer ist keine Zahl.',
        24: 'Die Tochter Ägyptens ist beschämt; sie ist in die Hand des Volks der Mitternacht gegeben.',
        25: 'Jehovah der Heerscharen, der Gott Israels, spricht: Siehe, Ich werde heimsuchen über Amon von No, und über Pharao und über Ägypten und über seine Götter und über seine Könige, und über Pharao und über die, so auf ihn vertrauen.',
        26: 'Und gebe sie in derer Hand, die ihnen nach der Seele trachten, und in die Hand Nebuchadrezzars, des Königs von Babel, und in seiner Knechte Hand, aber nachher soll es wohnen, wie in der Vorzeit Tagen, spricht Jehovah.',
        27: 'Du aber fürchte dich nicht, Mein Knecht Jakob, und entsetze dich nicht, Israel; denn siehe, Ich rette dich aus der Ferne, und deinen Samen aus dem Land ihrer Gefangenschaft, und Jakob soll zurückkehren und ruhig und sorglos sein, und niemand soll ihn aufscheuchen.',
        28: 'Du, fürchte dich nicht, Mein Knecht Jakob, spricht Jehovah; denn Ich bin mit dir. Wenn Ich Vollendung mache mit allen Völkerschaften, dahin Ich dich verstoßen hatte, so mache Ich doch mit dir keine Vollendung, aber züchtige dich nach dem Recht, und lasse dich nicht ungestraft.',
    },
    47: {
        1: 'Das Wort Jehovahs, das an den Propheten Jirmejahu geschah wider die Philister, ehe denn Pharao Gazah schlug.',
        2: 'So spricht Jehovah: Siehe, Wasser steigen auf von Mitternacht und werden zu einem überflutenden Bache, und sie überfluten das Land und seine Fülle, die Stadt und die darin wohnen; und schreien werden die Menschen und heulen wird alles, was im Lande wohnt.',
        3: 'Ob dem Lärm des Stampfens der Hufe ihrer Gewaltigen, ob dem Gerassel ihrer Streitwagen und dem Getümmel ihrer Räder wenden sich Väter nicht zu den Söhnen vor Erschlaffung ihrer Hände.',
        4: 'Ob dem Tag, der da kommen wird, alle Philister zu verheeren, auszurotten Zor und Zidon, und allen Rest, der beisteht, denn Jehovah verheert die Philister, den Überrest der Insel Kaphthor.',
        5: 'Kahlheit kommt über Gazah, Aschkalon geht unter, der Überrest ihres Talgrundes. Bis wann wirst du dich ritzen?',
        6: 'O Schwert Jehovahs, bis wann wirst du nicht rasten? Ziehe dich zurück in deine Scheide. Ruhe dich aus und sei stille.',
        7: 'Wie kannst du rasten? Und Jehovah hat ihm wider Aschkalon geboten und an des Meeres Gestade es beschieden.',
    },
    48: {
        1: 'Über Moab. So spricht Jehovah der Heerscharen, der Gott Israels. Wehe über Nebo! Denn es ist verheert worden, beschämt und erobert ist Kirjathaim; Misgab ist beschämt und entsetzt.',
        2: 'Nichts mehr ist es mit dem Lobe Moabs. In Cheschbon gedenkt man Böses wider dasselbe. Kommt, lasset uns es ausrotten, daß es keine Völkerschaft mehr ist. Auch Madmen geht unter. Hinter dir geht das Schwert.',
        3: 'Die Stimme des Geschreis von Choronajim: Verheerung und großes Zerbrechen.',
        4: 'Zerbrochen ist Moab. Ein Geschrei lassen seine Jüngeren hören.',
        5: 'Denn Weinen steigt die Steige von Luchith herauf mit Weinen; denn beim Herabsteigen von Choronaim hören die Dränger das Geschrei des Zerbrechens.',
        6: 'Fliehet, laßt entrinnen eure Seele, und sie seien wie ein bloßer Strauch der Wüste.',
        7: 'Darum, daß du vertraust auf deine Werke und auf deine Schätze, wirst auch du erobert werden: und Chemosch wird in Verbannung ausziehen, seine Priester und seine Obersten allzumal.',
        8: 'Und der Verheerer kommt über jegliche Stadt, und keine Stadt entrinnt, und verloren ist der Talgrund, und die Ebene vernichtet, so spricht Jehovah.',
        9: 'Gebet Moab Flügel, denn im Ausflug wird es ausfliegen, und seine Städte werden zur Verwüstung, daß niemand darin wohnt.',
        10: 'Verflucht sei, wer das Werk Jehovahs trüglich tut, und verflucht, wer abhält sein Schwert vom Blut.',
        11: 'Sorglos war Moab von Jugend auf und rastete auf seinen Hefen, es ward nicht ausgeleert von Gefäß zu Gefäß; und es ging nicht zur Wegführung. Darum ist sein Geschmack ihm stehengeblieben, und sein Geruch ward nicht umgewandelt.',
        12: 'Darum siehe, Tage kommen, spricht Jehovah, daß Ich Umleerer sende, die es umleeren, und seine Gefäße umleeren und zerschmeißen seine Schläuche.',
        13: 'Und Moab soll beschämt werden ob dem Chemosch, wie das Haus Israel beschämt ward ob Bethel, auf das es vertraute.',
        14: 'Wie sprechet ihr: Wir sind Helden und tapfere Männer zum Streit.',
        15: 'Verheert ist Moab, und seine Städte gehen auf. Und die Auswahl seiner Jünglinge geht hinab zur Schlachtbank, spricht der König, Jehovah der Heerscharen ist Sein Name.',
        16: 'Nah, daß es komme, ist Moabs Not. Und sein Übel eilt sehr.',
        17: 'Zeiget ihm Beileid, alle ringsum und alle, die ihr seinen Namen kennt, sprechet: Wie ist doch der Stab der Stärke zerbrochen, der Stock des Schmuckes!',
        18: 'Steige herab von der Herrlichkeit, sitze im Durste, Einwohnerin, Tochter von Dibon; denn der Verheerer Moabs steigt wider dich herauf, verdirbt deine Festungen.',
        19: 'Stehe an den Weg und spähe aus, Einwohnerin von Aroer, frage den Flüchtigen und was entronnen ist, sprich: Was ist geschehen?',
        20: 'Beschämt ist Moab, ja entsetzt. Heulet und schreit! Sagt es am Arnon an, daß Moab verheert ist.',
        21: 'Und ein Gericht ist über das Land der Ebene gekommen, über Cholon und über Jahzah und über Mephaath,',
        22: 'Und über Dibon und über Nebo und über Beth-Diblathajim,',
        23: 'Und über Kirjathajim und über BethGamul und über Beth-Meon,',
        24: 'Und über Kerijoth und über Bozrah und über alle Städte des Landes Moab, die fernen und die nahen.',
        25: 'Das Horn Moabs ist zerhauen und sein Arm gebrochen, spricht Jehovah.',
        26: 'Berauschet es; denn über Jehovah machte es sich groß, und es patsche Moab in sein Gespei, und werde selbst auch zum Gelächter!',
        27: 'Und war dir Israel nicht zum Gelächter oder war es unter den Dieben gefunden, daß du, sooft du von ihm redetest, dich geschüttelt hast?',
        28: 'Verlasset die Städte und wohnet auf der Felsenklippe, die ihr in Moab wohnet, und seiet wie die Taube, die an den Seiten der Mündung der Höhle nistet.',
        29: 'Wir haben von dem Stolze Moabs gehört, es ist sehr hochmütig von seiner Hoffart und seinem Stolz und seinem Übermut, und der Überhebung seines Herzens.',
        30: 'Ich kenne, spricht Jehovah, sein Wüten, daß es nicht recht ist, seine Unwahrheiten, daß sie, was nicht recht ist, getan.',
        31: 'Darum heule Ich über Moab und schreie über ganz Moab, über die Männer von Kir-Cheres muß man stöhnen.',
        32: 'Mehr als man weinte über Jaeser, weine Ich über dich, du Weinstock Sibmahs. Deine Ranken gingen über das Meer, bis zum Meer Jaesers reichten sie. In deine Obsternte und deine Weinlese fällt der Verheerer ein.',
        33: 'Fröhlichkeit und Frohlocken ist weggenommen von dem Fruchtgefilde und von dem Lande Moabs, und den Wein laß von den Kufen Ich zu Ende kommen. Man keltert nimmer bei dem Kelterlied. Das Hedad ist kein Hedad.',
        34: 'Vom Geschrei Cheschbons an bis Elealeh, bis Jahaz erheben sie ihre Stimme; von Zoar bis Choronajim, eine dreijährige Färse; denn auch die Wasser Nimrims werden verwüstet werden.',
        35: 'Und Ich lasse zu Ende kommen für Moab, spricht Jehovah, das Opfern auf den Opferhöhen und das Räuchern für seine Götter.',
        36: 'Darum dröhnt mein Herz um Moab wie Flöten, um die Männer von Kir-Cheres dröhnt mein Herz wie Flöten, weil das übrige, das es gemacht, verloren ist.',
        37: 'Denn auf jedem Haupt ist Kahlheit und jeder Bart ist abgeschoren, auf allen Händen Ritze und auf den Lenden Säcke,',
        38: 'Auf allen Dächern Moabs und in seinen Straßen ist alles Klagen; denn zerbrochen habe Ich Moab, wie ein Gefäß, an dem man keine Lust hat, spricht Jehovah.',
        39: 'Wie ist es entsetzt! Heulet! Wie hat Moab den Nacken gewendet! Schäme dich! Und Moab ist zum Gelächter und zum Entsetzen allen ringsumher geworden.',
        40: 'Denn so spricht Jehovah: Siehe, wie der Adler schwebt er daher und breitet seine Flügel über Moab aus.',
        41: 'Kerioth wird erobert und die Festen, sie wird eingenommen. Und an selbigem Tage wird das Herz der Helden Moabs wie das Herz des Weibes, das am Kreißen ist.',
        42: 'Und Moab wird vernichtet, daß es kein Volk ist; denn wider Jehovah hat es sich groß gemacht.',
        43: 'Schauer und Fallgrube und Schlinge über dich, der du in Moab wohnst, spricht Jehovah.',
        44: 'Wer vor dem Schauer flieht, fällt in die Fallgrube, und wer heraufkommt aus der Fallgrube, wird in der Schlinge gefangen; denn Ich lasse über dasselbe, über Moab, das Jahr ihrer Heimsuchung kommen, spricht Jehovah.',
        45: 'Im Schatten Cheschbons stehen die, so aus Kräften flohen; jedoch ein Feuer geht von Cheschbon aus und eine Flamme zwischen Sichon hervor und frißt die Ecke Moabs und den Scheitel der Söhne des Tosens.',
        46: 'Wehe dir, Moab, verloren ist das Volk des Chemosch, denn man hat deine Söhne in Gefangenschaft genommen und deine Töchter in Gefangenschaft.',
        47: 'Doch will Ich die Gefangenschaft Moabs in den letzten der Tage zurückwenden, spricht Jehovah. Bis hierher das Gericht Moabs.',
    },
    49: {
        1: 'Wider die Söhne Ammons: So spricht Jehovah: Hat Israel keine Söhne? Hat es keinen Erbbesitzer? Warum beerbet ihr König Gad und wohnt sein Volk in dessen Städten?',
        2: 'Darum seht, kommen Tage, spricht Jehovah, da Ich hören lasse über Rabbah der Söhne Ammon Feldgeschrei des Streites, und da es zum wüsten Schutthaufen wird, und seine Töchter mit Feuer angezündet werden, und Israel beerben wird die, so ihn beerbt hatten, spricht Jehovah.',
        3: 'Heule, Cheschbon; denn verheert ist Ai. Schreit, ihr Töchter Rabbahs, gürtet euch mit Säcken, klaget und rennet zwischen den Mauern umher, denn ihr König geht hin, weggeführt, seine Priester und seine Obersten allzumal.',
        4: 'Was rühmst du dich der Talgründe? dein Talgrund, der fließt dahin, abwendige Tochter, die vertraut auf ihre Schätze: Wer kommt an mich?',
        5: 'Siehe, Ich bringe Schauder über dich, spricht der Herr, Jehovah der Heerscharen, von allen rings um dich her; und ihr werdet verstoßen, jeder Mann vor sich hin, und niemand bringt die Flüchtigen zusammen.',
        6: 'Doch hernach wende Ich zurück die Gefangenschaft der Söhne Ammons, spricht Jehovah.',
        7: 'Wider Edom spricht also Jehovah der Heerscharen: Ist keine Weisheit mehr in Theman? Ist der Rat der Einsichtsvollen verlorengegangen? Ist ihre Weisheit stinkend geworden?',
        8: 'Fliehet! Sie sind abgewandt, sie machten tief ihren Wohnsitz, die Bewohner Dedans; denn Esaus Not bringe Ich über ihn, die Zeit, da Ich ihn heimsuche.',
        9: 'Wenn über dich Weinleser kommen, würden sie dir nicht Nachlese überlassen? wenn Diebe in der Nacht, verderben sie nach ihrer Genüge?',
        10: 'Denn Ich entblöße Esau, decke auf sein Verborgenes. Nicht kann er sich verstecken. Verheert ist sein Same und seine Brüder und seine Nachbarn, und er ist nicht mehr.',
        11: 'Verlaß deine Waisen! Ich erhalte sie am Leben. Und deine Witwen sollen Mir vertrauen.',
        12: 'Denn so spricht Jehovah: Siehe, deren Gericht nicht war den Becher zu trinken, die tranken. Und du sollst ungestraft bleiben? Du sollst nicht ungestraft bleiben, du sollst trinken.',
        13: 'Denn Ich habe bei Mir geschworen, spricht Jehovah, daß zur Verwüstung, zur Schmach, zur Öde und zum Fluch Bozrah soll werden, und alle seine Städte zu ewigen Öden.',
        14: 'Ein Gerücht habe Ich gehört von Jehovah und eine Gesandtschaft wird an die Völkerschaften gesandt: Ziehet euch zusammen und kommt wider es und stehet auf zum Streit.',
        15: 'Denn siehe, klein habe Ich dich hingegeben unter den Völkerschaften, verachtet unter den Menschen.',
        16: 'Dein Trotz hat dich verführt und deines Herzens Vermessenheit, der du in Klüften der Felsenklippe wohnst und die Höhe der Hügel eingenommen hast. Ob du hoch wie der Adler machst dein Nest, Ich bringe dich von da herab, spricht Jehovah.',
        17: 'Und Edom wird zur Verwüstung sein, jeder, der an ihm vorübergeht, erstaunt sich und zischt ob allen seinen Schlägen.',
        18: 'Gleichwie in der Umkehrung Sodoms und Gomorrahs und ihrer Nachbarn, spricht Jehovah, soll allda kein Mann wohnen, nicht sich in ihm aufhalten ein Sohn des Menschen.',
        19: 'Siehe, wie der Löwe von dem Anschwellen des Jordans aufsteigt nach dem Wohnorte Ethans. Aber im Augenblick lasse Ich ihn von dannen laufen. Und wer ist der Auserwählte, den Ich über sie bestellt? Denn wer ist wie Ich? Und wer ruft Mich zum Zeugen vor, und wer ist der Hirte, der vor Meinem Angesicht steht?',
        20: 'Darum hört den Ratschluß Jehovahs, den Er über Edom beschlossen hat, und Seine Gedanken, die Er wider Themans Bewohner denkt: Schleppen sie nicht davon die Geringen der Herde; verwüsten sie nicht ihren Wohnort?',
        21: 'Die Erde bebt von dem Getöse ihres Falls, am Schilfmeere hört man die Stimme seines Geschreis.',
        22: 'Siehe, wie der Adler steigt er auf und schwebt und breitet seine Flügel über Bozrah, und das Herz der Helden Edoms wird an dem Tage wie das Herz des Weibes im Kreißen.',
        23: 'Wider Damask. Beschämt ist Chamath und Arpad; denn ein böses Gerücht hören sie, sie zerfließen. Am Meer ist Besorgnis, sie vermögen nicht zu rasten.',
        24: 'Damask erschlafft, hat sich zur Flucht gewandt, und grauen hat sie gefaßt, Drangsal und Geburtsnöten sie ergriffen, wie die Gebärerin.',
        25: 'Wie ist sie nicht verlassen, die Stadt des Lobes, Meiner Freude Stadt.',
        26: 'Darum fallen sie auf ihren Straßen ihre Jünglinge, und alle Männer des Streites gehen unter an jenem Tage, spricht Jehovah der Heerscharen.',
        27: 'Und in der Mauer von Damask zünde Ich Feuer an, daß es Benhadads Paläste auffresse.',
        28: 'Wider Kedar und wider die Königreiche Chazors, die Nebuchadrezzar, Babels König, schlug. So spricht Jehovah: Steht auf und ziehet wider Kedar hinauf und verheeret die Söhne des Ostens.',
        29: 'Und ihre Zelte und ihr Kleinvieh nehmen sie, ihre Teppiche und all ihre Geräte und ihre Kamele nehmen sie für sich fort, und rufen über sie: Bangen ringsum.',
        30: 'Fliehet, schweifet sehr umher! Gehet in die Tiefe zu wohnen Chazors Bewohner, spricht Jehovah; denn Nebuchadrezzar, der König Babels, hat einen Ratschluß wider euch beschlossen; und er denkt einen Gedanken wider sie.',
        31: 'Steht auf, zieht hinauf zu einer zufriedenen Völkerschaft, die da wohnt in Sicherheit, spricht Jehovah, keine Türflügel und keine Riegel hat sie, einsam wohnen sie.',
        32: 'Und ihre Kamele sollen zum Raube werden, und ihrer Viehherden Menge zur Beute, und Ich zersprenge in alle Winde die im Winkel Abgeschnittenen, und lasse ihre Not von allen Seiten kommen, spricht Jehovah.',
        33: 'Und Chazor soll werden zur Behausung der Drachen, zur Verwüstung ewiglich. Nicht wird ein Mann darin wohnen, und nicht in ihr sich aufhalten ein Menschensohn.',
        34: 'Das Wort Jehovahs, das geschah an Jirmejahu, den Propheten, wider Elam im Anfang der Regierung Zidkijahus, des Königs von Jehudah, sprechend:',
        35: 'So spricht Jehovah der Heerscharen: Siehe, Ich breche Elams Bogen, den Erstling seiner Macht.',
        36: 'Und Ich lasse kommen über Elam vier Winde von den vier Enden der Himmel, und zersprenge sie nach allen diesen Winden, und keine Völkerschaft soll sein, wohin nicht kämen Verstoßene von Elam.',
        37: 'Und Ich lasse Elam sich entsetzen vor seinen Feinden und vor denen, die nach seiner Seele trachten, und werde Böses über sie bringen, Meines Zornes Entbrennen, spricht Jehovah, und hinter ihnen her das Schwert senden, bis daß Ich sie alle gemacht habe.',
        38: 'Und Meinen Thron will Ich in Elam setzen und von da König und Oberste zerstören, spricht Jehovah.',
        39: 'Und in den letzten der Tage wird geschehen, daß Ich zurückwende Elams Gefangenschaft, spricht Jehovah.',
    },
    50: {
        1: 'Das Wort, welches Jehovah wider Babel, wider das Land der Chaldäer, durch die Hand Jirmejahus, des Propheten, geredet hat:',
        2: 'Sagt an unter den Völkerschaften und laßt hören, und erhebt ein Panier, laßt hören, verhehlet nicht, sprechet: Babel ist eingenommen, Bel ist beschämt, Merodach ist entsetzt, beschämt sind seine Götzenbilder, entsetzt seine Götzen.',
        3: 'Denn wider dasselbe zieht herauf eine Völkerschaft von Mitternacht. Sie wird ihr Land zur Verwüstung setzen, und kein Bewohner wird darinnen sein. Vom Menschen und bis zum Vieh entfliehen sie und gehen davon.',
        4: 'In jenen Tagen und zu jener Zeit, spricht Jehovah, werden die Söhne Israels kommen, sie und die Söhne Jehudahs allzumal, gehend und weinend gehen sie, Jehovah, ihren Gott, zu suchen.',
        5: 'Nach Zijon fragen sie den Weg, dahin ist ihr Angesicht: Kommt und laßt uns Jehovah anhangen, in ewigem Bunde, der nicht soll vergessen werden.',
        6: 'Eine verlorene Herde ist Mein Volk, ihre Hirten führten es irre, abwendige Berge, von Berg zu Hügel gingen sie, vergaßen ihrer Lagerstätte.',
        7: 'Alle die, so sie fanden, fraßen sie auf, und ihre Dränger sprachen: Wir verschulden uns nicht, darum, daß sie sich wider Jehovah, den Wohnort der Gerechtigkeit, und ihrer Väter Hoffnung, wider Jehovah, versündigt haben.',
        8: 'Entfliehet aus Babels Mitte, und vom Lande der Chaldäer gehet aus, und seiet als die Böcke, vor den Schafen her.',
        9: 'Denn siehe, Ich errege und bringe herauf wider Babel eine Versammlung großer Völkerschaften aus dem Lande der Mitternacht, und sie ordnen sich wider sie; von dorther soll es erobert werden; seine Pfeile sind wie die des klugen Helden, sie kehren nicht leer zurück.',
        10: 'Und Chaldäa wird zur Beute; alle, die sie erbeuten, sollen satt werden, spricht Jehovah.',
        11: 'Denn ihr seid fröhlich, denn ihr jauchzet, ihr Plünderer Meines Erbes, wachset heran wie die Färse, die drischt, und wiehert wie die Gewaltigen.',
        12: 'Sehr beschämt ist eure Mutter, sie errötet, die euch gebar. Siehe, die letzte der Völkerschaften, eine Wüste, eine Dürre, und eine Einöde.',
        13: 'Ob der Entrüstung Jehovahs wird sie nicht bewohnt, und wird ganz zur Verwüstung werden. Ein jeder, der vorübergeht an Babel, wird erstaunen, und wird ob allen ihren Schlägen zischen.',
        14: 'Ordnet euch wider Babel ringsumher, all ihr Spanner des Bogens, schießt auf sie, schont des Pfeiles nicht; denn wider Jehovah hat sie gesündigt.',
        15: 'Erhebet ringsum wider sie das Feldgeschrei. Ihre Hand gibt sie, ihre Grundfesten fallen, ihre Mauern reißt man nieder; denn Jehovahs Rache ist es. Rächt euch an ihr! Wie sie getan hat, tuet ihr!',
        16: 'Rottet den Sämann aus von Babel, und den, so die Sichel faßt zur Zeit der Ernte. Vor dem bedrückenden Schwerte wendet sich jeder Mann zu seinem Volk, und jeder Mann flieht in sein Land.',
        17: 'Ein verscheuchtes Schaf ist Israel, Löwen verjagten es. Zuerst fraß es der König Aschurs, und hernach zerdrückte ihm das Gebein Nebuchadrezzar, Babels König.',
        18: 'Darum spricht also Jehovah der Heerscharen, der Gott Israels: Siehe, Ich suche heim den König Babels und sein Land, wie Ich den König Aschurs heimgesucht habe,',
        19: 'Und bringe Israel zurück in seinen Wohnort, so daß es auf Karmel und in Baschan weidet, und auf dem Gebirge Ephraim und Gilead sich seine Seele sättige.',
        20: 'In jenen Tagen und zu jener Zeit, spricht Jehovah, wird man die Missetat Israels suchen, und wird keine da sein, und Jehudahs Sünde, und man wird keine finden; denn Ich werde dem vergeben, den Ich verbleiben ließ.',
        21: 'Wider das Land der zweifachen Widerspenstigkeit: Ziehe hinauf wider dasselbe und wider die, so in Pekod wohnen, veröde und banne ihre Nachkommen, spricht Jehovah, und tue nach allem, was Ich dir gebiete.',
        22: 'Des Streites Stimme ist im Lande, und großes Zerbrechen.',
        23: 'Wie ist der Hammer doch des ganzen Landes zerhauen und zerbrochen! Wie ward Babel zur Verwüstung unter den Völkerschaften!',
        24: 'Ich legte dir Fallstricke, Babel, und du fingst dich auch, und du wußtest es nicht. Du wardst gefunden und auch erfaßt, denn Jehovah hast du befehdet.',
        25: 'Jehovah hat Seine Schatzkammer geöffnet und die Geräte Seines Unwillens herausgebracht, denn ein Geschäft hat der Herr Jehovah der Heerscharen im Lande der Chaldäer.',
        26: 'Kommt wider sie vom Ende, öffnet ihre Scheunen, schichtet sie auf wie Kornhaufen und verbannt sie, daß ihr kein Überrest sei.',
        27: 'Würgt alle ihre Farren, laßt sie zur Schlachtbank herabkommen. Wehe über sie, denn ihr Tag ist gekommen, die Zeit ihrer Heimsuchung.',
        28: 'Die Stimme der Flüchtenden und der Entrinnenden aus Babels Land! anzusagen in Zijon die Rache Jehovahs, unseres Gottes, die Rache für Seinen Tempel.',
        29: 'Rufet Schützen auf wider Babel, alle die den Bogen spannen; lagert euch ringsumher, daß kein Entkommen ist. Vergeltet ihr nach ihren Werken, tut ihr nach allem, was sie tat; denn wider Jehovah, den Heiligen Israels, vermaß sie sich.',
        30: 'Darum sollen ihre Jünglinge auf ihren Straßen fallen, und alle ihre Männer des Streites an jenem Tage untergehen, spricht Jehovah.',
        31: 'Siehe, Ich bin wider dich, Vermessene, spricht der Herr Jehovah der Heerscharen; denn gekommen ist dein Tag, die Zeit deiner Heimsuchung.',
        32: 'Und straucheln wird der Vermessene und fallen, und keiner richtet ihn auf; und Ich zünde ein Feuer an in seinen Städten, das alles um ihn her auffresse.',
        33: 'So spricht Jehovah der Heerscharen: Unterdrückt sind die Söhne Israels und Jehudahs Söhne allzumal, und alle, die sie gefangenführten, halten sie fest, sie weigern sich, sie zu entsenden.',
        34: 'Stark ist ihr Erlöser! Jehovah der Heerscharen ist Sein Name. Er hadert ihren Hader, auf daß Er das Land ausruhen lasse, und zittern lasse, die in Babel wohnen.',
        35: 'Das Schwert ist wider die Chaldäer, spricht Jehovah, und wider die Einwohner Babels und wider seine Obersten und wider seine Weisen.',
        36: 'Das Schwert ist wider die Unwahren, und zu Narren werden sie; das Schwert ist wider seine Helden, daß sie sich entsetzen.',
        37: 'Das Schwert ist wider seine Rosse und wider seine Streitwagen und wider allen Troß in seiner Mitte, daß sie zu Weibern werden; das Schwert ist wider seine Schätze, daß sie geraubt werden.',
        38: 'Dürre kommt über ihre Wasser, daß sie vertrocknen; denn ein Land der Schnitzbilder ist es, und sie rühmen sich ihrer Schreckbilder.',
        39: 'Darum sollen Zijim mit Ijim und Käuzlein darin wohnen. Und man soll nimmermehr darin wohnen, noch soll man dort wohnen zu Geschlecht und Geschlecht.',
        40: 'Und wie Gott Sodom und Gomorrah und deren Nachbarn umkehrte, spricht Jehovah, soll allda kein Mann wohnen, noch darin sich aufhalten ein Sohn des Menschen.',
        41: 'Siehe, ein Volk kommt von Mitternacht, und eine große Völkerschaft und viele Könige werden auferweckt von den Seiten der Erde.',
        42: 'Bogen und Wurfspieß fassen sie, sind grausam und erbarmen sich nicht, ihre Stimme ist wie ein tobend Meer, und auf Rossen reiten sie, geordnet wie der Mann zum Streite, wider dich, Tochter Babels.',
        43: 'Der König Babels hört ihr Gerücht und seine Hände werden schlaff, Angst ergreift ihn, Wehen, wie die Gebärerin.',
        44: 'Siehe, wie der Löwe von dem Anschwellen des Jordan aufsteigt nach dem Wohnorte Ethans! Aber im Augenblick lasse Ich ihn von ihr laufen. Und wer ist der Auserwählte, den Ich über sie bestellte? Denn wer ist wie Ich? Und wer ruft Mich zum Zeugen vor, und wer ist der Hirte, der vor Meinem Angesichte steht?',
        45: 'Darum hört Jehovahs Ratschluß, den Er über Babel beschlossen hat, und Seine Gedanken, die Er denkt wider der Chaldäer Land. Denn schleppen sie nicht davon die Geringen der Herde? Verwüsten sie nicht ihren Wohnort über ihnen?',
        46: 'Von der Stimme: Babel ist eingenommen! erbebt die Erde, und das Geschrei wird gehört unter den Völkerschaften.',
    },
    51: {
        1: 'So spricht Jehovah: Siehe, Ich errege wider Babel, und wider die Bewohner, die im Herzen wider Mich aufstanden, einen verderblichen Geist.',
        2: 'Und Ich sende Worfler gen Babel, daß sie dasselbe worfeln und sein Land ausleeren; denn sie werden am Tag des Bösen rings um sie her sein.',
        3: 'Dawider spanne, spanne, der spannet seinen Bogen, und dawider steige er herauf in seinem Panzer. Und bemitleidet nicht ihre Jünglinge, verbannet all ihr Heer.',
        4: 'Daß Erschlagene fallen im Land der Chaldäer und Durchstochene in ihren Gassen.',
        5: 'Denn Israel und Jehudah sollen nicht verwitwet sein von ihrem Gotte, von Jehovah der Heerscharen, denn ihr Land ist voller Schuld am Heiligen Israels.',
        6: 'Fliehet aus Babels Mitte und es lasse entrinnen jeder Mann seine Seele, daß er nicht untergehe in seiner Missetat; denn der Rache Zeit ist für Jehovah, nach Verdienst vergilt Er ihm.',
        7: 'Ein Becher von Gold war Babel in der Hand Jehovahs, der berauschte die ganze Erde. Von seinem Wein tranken die Völkerschaften, darum rasen die Völkerschaften.',
        8: 'Plötzlich ist gefallen Babel und zerbrochen. Heulet über sie. Holt Balsam für ihre Schmerzen, vielleicht wird sie geheilt.',
        9: 'Wir heilten an Babel, aber sie ließ sich nicht heilen. Verlasset sie und laßt uns gehen, jeder Mann in sein Land; denn zum Himmel reicht ihr Gericht, und hat bis an den Wolkenhimmel sich erhoben.',
        10: 'Jehovah ließ unsere Gerechtigkeit hervorgehen; kommt und laßt in Zijon uns erzählen das Tun Jehovahs, unseres Gottes.',
        11: 'Feget die Pfeile, füllt die Schilde. Jehovah hat den Geist der Könige Madais auferweckt, denn Sein Sinnen ist wider Babel, es zu verderben; denn dies ist Jehovahs Rache, die Rache Seines Tempels.',
        12: 'Wider die Mauern Babels erhebet ein Panier, macht stark die Hut, stellt Hüter auf, bereitet einen Hinterhalt; denn Jehovah ersinnt sowohl als Er auch tut, was Er wider die, so in Babel wohnen, geredet hat.',
        13: 'Die du auf vielen Wassern wohnst, groß an Schätzen, gekommen ist dein Ende, das Maß deines Gewinns.',
        14: 'Geschworen hat bei Seiner Seele Jehovah der Heerscharen: Fürwahr, Ich fülle dich an mit Menschen, wie mit Heuschrecken, und sie antworteten ob dir mit einem Kelterlied.',
        15: 'Er hat die Erde gemacht durch Seine Kraft, die Welt bereitet durch Seine Weisheit, und durch Seine Einsicht die Himmel ausge- spannt.',
        16: 'Gibt Seine Stimme Er dahin, so ist Wasser die Menge an den Himmeln, und Er läßt Dünste aufsteigen von der Erde Ende, macht Blitze für den Regen, und bringt den Wind heraus aus Seinen Schatzkammern.',
        17: 'Tierisch ist jeder Mensch durch das Wissen, beschämt wird jeder Goldschmied durch sein Schnitzbild, denn Lüge ist sein Gußbild, und kein Hauch in ihnen.',
        18: 'Nichtigkeit sind sie, ein Machwerk der Irrtümer. Sie vergehen zur Zeit ihrer Heimsuchung.',
        19: 'Nicht wie sie ist Jakobs Teil; denn Er ist der Bildner des Ganzen, und die Rute Seines Erbes. Jehovah der Heerscharen ist Sein Name.',
        20: 'Ein Hammer bist du Mir, ein Gerät des Streites; und mit dir zerschmeiße Ich Völkerschaften, und mit dir verderbe Ich Königreiche.',
        21: 'Und durch dich zerschmeiße Ich das Roß und dessen Reiter, und zerschmeiße mit dir den Streitwagen und den, der darin fährt.',
        22: 'Und durch dich zerschmeiße Ich Mann und Weib, und durch dich zerschmeiße Ich den Alten und den Jungen, und zerschmeiße durch dich den Jüngling und die Jungfrau.',
        23: 'Und durch dich zerschmeiße Ich den Hirten und seinen Trieb, und zerschmeiße durch dich den Ackersmann und sein Gespann; und durch dich zerschmeiße Ich Statthalter und Landvögte.',
        24: 'Und Ich vergelte Babel und allen, die in Chaldäa wohnen, all ihr Böses, das sie in Zijon vor euren Augen taten, spricht Jehovah.',
        25: 'Siehe, Ich bin wider dich, du verderbender Berg, spricht Jehovah, der du verdirbst die ganze Erde, und recke Meine Hand aus wider dich und wälze dich von den Felsenklippen, und gebe dich zum Berge der Verbrennung.',
        26: 'Und man soll nicht von dir nehmen einen Stein zur Ecke noch zu den Grundfesten; denn du sollst zu ewigen Verwüstungen werden, spricht Jehovah.',
        27: 'Erhebet ein Panier im Lande, stoßt in die Posaune unter den Völkerschaften, heiligt Völkerschaften wider sie, laßt hören wider sie Königreiche Ararat, Minni und Aschbenas. Bestellt einen Befehlshaber wider sie, bringt Rosse herauf gleich borstigen Heuschrecken.',
        28: 'Heiligt Völkerschaften wider sie, die Könige Madais, dessen Statthalter und alle seine Landvögte und alle Lande seiner Herrschaft;',
        29: 'So daß das Land erbebe und kreiße; denn die Gedanken Jehovahs wider Babel stehen fest, daß Er zur Verwüstung setze Babels Land, daß niemand darin wohne.',
        30: 'Die Helden Babels hören auf zu streiten; sie sitzen in den Festen; ihre Macht versiegt; zu Weibern sind sie geworden. Ihre Wohnungen werden angezündet, zerbrochen ihre Riegel.',
        31: 'Ein Läufer läuft dem Läufer entgegen, und Verkünder begegnet Verkünder, dem König Babels anzusagen, daß seine Stadt vom Ende her erobert ist.',
        32: 'Die Brücken sind eingenommen, die Binsenbüsche verbrannt mit Feuer, und die Männer des Streites sind bestürzt.',
        33: 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Wie eine Tenne ist die Tochter Babels zur Zeit, da man sie tritt, ein wenig noch und es kommt für sie die Zeit der Ernte.',
        34: 'Gefressen hat mich, mich verwirrt Nebuchadrezzar, Babels König, mich hingestellt, ein leer Gefäß, hat mich verschlungen wie ein Walfisch hat seinen Wanst gefüllt mit meinen Leckerbissen und mich verstoßen.',
        35: 'Die Gewalttat an mir und meinem Fleisch sei über Babel! spricht Zijons Bewohnerin, und mein Blut auf die, so in Chaldäa wohnen! spricht Jerusalem.',
        36: 'Darum, so spricht Jehovah: Siehe, Ich hadere deinen Hader und räche deine Rache, und lasse vertrocknen ihr Meer und ihren Born trocken werden.',
        37: 'Und Babel wird zu Steinhaufen, zur Wohnstätte der Drachen, zum Erstaunen und zum Zischen, daß niemand darin wohnt.',
        38: 'Sie brüllen wie junge Löwen allzumal, sie knurren wie die Jungen der Löwinnen.',
        39: 'In ihrer Hitze will Ich ihnen ein Gastmahl vorsetzten und sie berauschen, daß sie jauchzen und schlafen einen ewigen Schlaf, und nicht erwachen, spricht Jehovah.',
        40: 'Wie Lämmer bringe Ich sie hinab zum Schlachten, wie Widder mit den Böcken.',
        41: 'Wie ward Scheschach erobert, und das Lob der ganzen Erde eingenommen! wie wurde Babel zur Verwüstung unter den Völkerschaften!',
        42: 'Über Babel stieg auf das Meer, von seiner Wogen Menge ist es bedeckt.',
        43: 'Zur Verwüstung wurden ihre Städte, ein dürres Land und eine Einöde, ein Land, da kein Mann innen wohnt, und da kein Menschsohn durchgeht.',
        44: 'Und Ich suche heim den Bel in Babel, und bringe sein Verschlungenes heraus aus seinem Mund, und sollen fürder nimmer Völkerschaften zu ihm strömen. Auch Babels Mauer fällt.',
        45: 'Zieh aus, Mein Volk, aus seiner Mitte, jeder Mann lasse seine Seele entrinnen vor der Entbrennung von Jehovahs Zorn.',
        46: 'Und damit euer Herz nicht weich werde, und ihr euch fürchtet ob dem Gerücht, das man im Lande hört, und wenn im Jahre das Gerücht kommt und im Jahr darauf kommt das Gerücht und Gewalttat ist im Lande: Herrscher wider Heerscher:',
        47: 'Darum siehe, Tage kommen, da Ich Babels Schnitzbilder heimsuche und all ihr Land beschämt wird, und alle ihre Erschlagenen in ihrer Mitte fallen.',
        48: 'Und aufjauchzen werden über Babel Himmel und Erde und alles, was darinnen ist; denn von Mitternacht werden ihr kommen die Verheerer, spricht Jehovah.',
        49: 'Wie Babel gefällt hat die Erschlagenen in Israel, so auch werden für Babel die Erschlagenen des ganzen Landes fallen.',
        50: 'Ihr, die ihr seid dem Schwert entkommen, gehet hin und bleibt nicht stehen. Gedenket aus der Ferne an Jehovah, und Jerusalem steige auf in eurem Herzen.',
        51: 'Wir schämten uns, als wir die Schmach vernahmen, Schande bedeckte unser Angesicht, als Fremde über die Heiligtümer kamen von Jehovahs Haus.',
        52: 'Darum siehe, Tage kommen, spricht Jehovah, da Ich ihre Schnitzbilder heimsuche, und der Durchbohrte in ihrem ganzen Lande jammern wird.',
        53: 'Stiege Babel auf gen Himmel und befestigte allda die Höhe seiner Stärke, sollen von Mir an sie Verheerer kommen, spricht Jehovah.',
        54: 'Die Stimme des Geschreis von Babel und großes Zerbrechen aus dem Lande der Chaldäer.',
        55: 'Denn Jehovah verheert Babel und zerstört sie mit großer Stimme, und ihre Wogen toben wie viele Wasser, sie geben dahin das Getöse ihrer Stimme.',
        56: 'Denn der Verheerer ist gekommen wider sie, wider Babel, und seine Helden sind gefangen, seine Bogen sind zerbrochen, denn ein Gott der Erwiderung ist Jehovah, vergeltend vergilt Er.',
        57: 'Und Ich berausche seine Obersten und seine Weisen, seine Statthalter und seine Landvögte und seine Helden, daß einen ewigen Schlaf sie schlafen und nicht erwachen, spricht der König. Jehovah der Heerscharen ist Sein Name.',
        58: 'So spricht Jehovah der Heerscharen: Die Mauern Babels, des breiten, sie werden umgegraben und seine hohen Tore mit Feuer angezündet, so daß die Völker sich umsonst ermüdet und die Volksstämme für das Feuer, und sich abgemattet haben.',
        59: 'Das Wort, das Jirmejahu, der Prophet, gebot Serajah, dem Sohn Nerijahs, des Sohnes Machsejahs, als er mit Zidkijahu, dem König Jehudahs, gen Babel zog, im vierten Jahr seiner Regierung, und Serajah war Oberster des Ruheortes.',
        60: 'Und Jirmejahu schrieb all das Böse, das über Babel kommen sollte, in ein Buch, all diese Worte, die über Babel geschrieben sind.',
        61: 'Und Jirmejahu sprach zu Serajah: Wie du nach Babel kommst, so siehe, daß du alle diese Worte lesest,',
        62: 'Und sprich: Du hast, Jehovah, über diesen Ort geredet, ihn auszurotten, daß kein Bewohner darinnen sei, vom Menschen und bis zum Vieh; sondern eine Verwüstung sei ewiglich.',
        63: 'Und es geschehe, wenn du das Lesen dieses Buches vollendet hast, so binde einen Stein daran und wirf es mitten in den Phrath,',
        64: 'Und sprich: Also sinke unter, Babel, und stehe nicht mehr auf vor dem Bösen, das ich bringe über sie, und sie ermatten. Soweit die Reden Jirmejahus.',
    },
    52: {
        1: 'Einundzwanzig Jahre alt war Zidkijahu, da er König ward, und regierte elf Jahre zu Jerusalem. Und der Name seiner Mutter war Chamutal, eine Tochter Jirmejahus aus Libnah.',
        2: 'Und er tat, was böse war in Jehovahs Augen, nach allem, was Jehojakim getan.',
        3: 'Denn nach dem Zorn Jehovahs über Jerusalem und Jehudah geschah es, daß Er sie verwarf vor Seinem Angesicht, und Zidkijahu empörte sich wider den König Babels.',
        4: 'Und es geschah im neunten Jahr seiner Regierung, im zehnten Monat, am zehnten des Monats, daß Nebuchadrezzar, Babels König, kam, er und all seine Streitmacht, wider Jerusalem und sie lagerten sich wider sie und bauten ein Bollwerk dawider ringsumher.',
        5: 'Und die Stadt kam in Belagerung bis in das elfte Jahr des Königs Zidkijahu.',
        6: 'Und im vierten Monat, am neunten des Monats, war die Hungersnot in der Stadt stark geworden, und es war kein Brot mehr da für das Volk des Landes,',
        7: 'Und die Stadt ward erbrochen und all die Männer des Streites entwichen, und zogen bei Nacht zur Stadt hinaus auf dem Weg zum Tor zwischen der Doppelmauer bei dem Garten des Königs. Und die Chaldäer waren wider die Stadt ringsumher, und sie gingen den Weg nach dem Blachfelde.',
        8: 'Und die Streitmacht der Chaldäer setzte hinter dem König nach, und sie erreichten Zidkijahu auf dem Blachfeld Jerichos, und alle seine Streitmacht zerstreute sich von ihm.',
        9: 'Und sie erfaßten den König und brachten ihn hinauf zum König von Babel nach Riblah im Lande Chamath, und er redete mit ihm in Gerichten.',
        10: 'Und Babels König schlachtete die Söhne Zidkijahus vor seinen Augen. Und auch alle Obersten Jehudahs schlachtete er in Riblah.',
        11: 'Und blendete die Augen Zidkijahus und band ihn mit zwei Erzfesseln, und der König Babels brachte ihn nach Babel und gab ihn in das Strafhaus bis an den Tag seines Todes.',
        12: 'Und im fünften Monat am zehnten des Monats, das Jahr war das neunzehnte Jahr Nebuchadrezzars, des Königs von Babel, kam Nebusaradan, der Hauptmann der Leibwachen, der vor dem König zu Babel stand, nach Jerusalem.',
        13: 'Und verbrannte das Haus Jehovahs und des Königs Haus und alle Häuser Jerusalems; und jedes große Haus verbrannte er mit Feuer.',
        14: 'Und alle Mauern Jerusalems ringsumher riß die ganze Streitmacht, die mit dem Hauptmann der Leibwachen war, ein.',
        15: 'Und von den Armen des Volkes und das übrige Volk, das in der Stadt verblieben war, und die Abgefallenen, die zum König von Babel abgefallen waren, und die übrigen Werkleute führte Nebusaradan, der Hauptmann der Leibwachen, weg.',
        16: 'Und von den Armen des Landes ließ Nebusaradan, der Hauptmann der Leibwachen, verbleiben zu Weingärtnern und Feldarbeitern.',
        17: 'Und die Säulen von Erz am Haus Jehovahs und die Gestelle und das Meer von Erz, das im Haus Jehovahs war, zerbrachen die Chaldäer und brachten alles Erz davon nach Babel.',
        18: 'Und die Töpfe und Schaufeln und Messer, und die Sprengbecken und die Pfannen und alle Gefäße von Erz, womit man den Dienst tat, nahmen sie.',
        19: 'Und die Becken und Rauchpfannen und Sprengschalen und die Töpfe und die Leuchter und die Pfannen und die Kannen von den goldenen, was Gold, und von den silbernen, was Silber war, nahm der Hauptmann der Leibwachen.',
        20: 'Die zwei Säulen, das eine Meer und die zwölf Rinder von Erz, die unter den Gestellen waren, die König Salomoh für das Haus Jehovahs gemacht hatte, - es war das Erz von all diesen Geräten nicht zu wägen.',
        21: 'Und die Säulen - achtzehn Ellen war die Höhe der einen Säule, und ein Faden von zwölf Ellen umgab sie, und ihre Dicke war vier Finger. Sie war hohl.',
        22: 'Und ein Knauf darauf von Erz, und die Höhe des einen Knaufs war fünf Ellen, und ein Flechtwerk und Granatäpfel ringsum auf dem Knauf, alles von Erz, und desgleichen an der zweiten Säule und die Granatäpfel.',
        23: 'Es waren aber der Granatäpfel sechsundneunzig nach dem Winde zu; aller Granatäpfel ringsum an dem Flechtwerk waren es hundert.',
        24: 'Und der Hauptmann der Leibwachen, nahm Serajah, den Oberpriester und Zephanjah, den zweiten Priester, und die drei Hüter der Schwelle.',
        25: 'Und aus der Stadt nahm er einen Verschnittenen, der über die Männer des Streites bestellt war, und sieben Männer von denen, die das Angesicht des Königs sahen, die in der Stadt gefunden wurden, und den Schreiber des Obersten des Heeres, der das Volk des Landes für das Heer eintrug, und sechzig Männer von dem Volk des Landes, die inmitten der Stadt gefunden wurden.',
        26: 'Und Nebusaradan, der Hauptmann der Leibwachen, nahm sie und ließ sie zum König von Babel nach Riblah gehen.',
        27: 'Und Babels König schlug sie und tötete sie in Riblah im Lande Hamath, und Jehudah wurde von seinem Boden weggeführt.',
        28: 'Dies ist das Volk, das Nebuchadrezzar im siebenten Jahre weggeführt, dreitausend- dreiundzwanzig Juden;',
        29: 'Im achtzehnten Jahre Nebuchadrezzars aus Jerusalem achthundertzweiunddreißig Seelen;',
        30: 'Im dreiundzwanzigsten Jahr Nebuchadrezzars führte Nebusaradan, der Hauptmann der Leibwachen, Juden, siebenhundertfünfundvierzig Seelen, im ganzen viertausendsechshundert Seelen weg.',
        31: 'Und es geschah im siebenunddreißigsten Jahre der Wegführung Jehojachins, des Königs von Jehudah, im zwölften Monat am fünfundzwanzigsten des Monats, daß Evil-Merodach, König von Babel, im Jahre, da er König ward, das Haupt Jehojachins, des Königs von Jehudah, erhob, und ihn aus dem Haus des Kerkers herausbrachte.',
        32: 'Und er redete Gutes mit ihm und setzte seinen Thron über die Throne der Könige, die bei ihm in Babel waren.',
        33: 'Und er veränderte die Kleider seines Kerkers und er aß beständig das Brot vor ihm alle Tage seines Lebens.',
        34: 'Und sein Unterhalt, ein beständiger Unterhalt ward ihm vom König von Babel Tag für Tag gegeben, bis zum Tage seines Todes, alle Tage seines Lebens.',
    },
}
